begin;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21681, 2, 218, 1681, 'hadith', 'وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «من صور في الدنيا، كُلف أن يَنفخ فيها الروح يوم القيامة وليس بنافخ».', 'I heard the Messenger of Allah (ﷺ) saying, "Whosoever makes a picture, will be punished on the Day of Resurrection, and will be asked to infuse soul therein, which he will not be able to do.".', null, 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1681', 'Riyad as-Salihin 1681', 'ریاض الصالحین 1681', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21682, 2, 218, 1682, 'hadith', 'عن ابن مسعود رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إن أشد الناس عذابًا يوم القيامة المصورون».', 'I heard the Messenger of Allah (ﷺ) saying, "Those who will receive the most severe punishment from Allah on the Day of Resurrection will be painters (of living objects).".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1682', 'Riyad as-Salihin 1682', 'ریاض الصالحین 1682', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21683, 2, 218, 1683, 'hadith', 'عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «قال الله تعالى: {ومن أظلم ممن ذهب يخلق كخلقي! فليخلقوا ذرة أو ليخلقوا حبة، أو ليخلقوا شعيرة».', 'The Messenger of Allah (ﷺ) said, "The Almighty Allah said: ''Who is more an oppressor than him who goes to create like My creation? Let him make an ant or a grain of corn or a grain of barley."''.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1683', 'Riyad as-Salihin 1683', 'ریاض الصالحین 1683', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21684, 2, 218, 1684, 'hadith', 'عن أبي طلحة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا تدخل الملائكة بيتًا فيه كلب ولا صورة».', 'The Messenger of Allah (ﷺ) said, "The angels do not enter a house in which there is a dog or a portrait.".', 'أبي طلحة رضي الله عنه', 'Abu Talhah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1684', 'Riyad as-Salihin 1684', 'ریاض الصالحین 1684', 'متفق عليه', '‏أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ ملائكة الرحمة لا تدخل بيتًا فيه كلبٌ ولا صورة ذَوَات الأرواح؛ 
وذلك أن صورة ما فيه روح: معصية فاحشة، وفيها مضاهاة لخلق الله، ووسيلة من وسائل الشرك، وبعضها صورة ما يعبد من دون الله، 
وأما سبب امتناعهم من بيت فيه كلب: لكثرة أكله النجاسات، ولأن بعضها يُسمى شيطانًا؛ والملائكة ضد الشياطين، 
ولقبح رائحة الكلب؛ والملائكة تكره الرائحة القبيحة، ولأنها منهيٌّ عن اتخاذها؛ فعُوقِب متخذها بحرمانه دخول ملائكة الرحمة بيته، وصلاتها فيه، واستغفارها له، وتبريكها عليه وفي بيته، ودفعها أذى الشيطان عنه.', 'تحريم اقتناء الكلب إلا كلب صيد أو ماشية أو زرع.
اتخاذ الصور من الأمور الخبيثة التي تَنْفِر منها الملائكة، ويكون وجودها في المكان سبب لحرمان الرحمة، ومثل ذلك الكلب.
الملائكة الذين لا يدخلون بيتًا فيه كلب أو صورة هم ملائكة الرحمة، وأما الحَفَظَة وغيرُهم ممن لهم وظيفة كمَلَك الموت فيدخلون في كل بيت.
تحريم تعليق صور ذوات الأرواح على الجدران وغيرها.
قال الخطابي: وإنما لا تدخل الملائكة بيتًا فيه كلب أو صورة مما يحرم اقتناؤه من الكلاب والصور، فأما ما ليس بحرام من كلب الصيد والزرع والماشية والصورة التي تمتهن في البساط والوسادة وغيرهما فلا يمتنع دخول الملائكة بسببه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8950', false),
(21685, 2, 218, 1685, 'hadith', 'عن ابن عمر رضي الله عنهما قال: وعد رسول الله صلى الله عليه وسلم جبريل أن يأتيه فراث عليه حتى اشتد على رسول الله صلى الله عليه وسلم، فخرج فلقيه جبريل فشكا إليه، فقال: إنا لا ندخل بيتًا فيه كلب ولا صورة.', 'Jibril (Gabriel) promised to visit the Messenger of Allah (ﷺ) but delayed and this grieved him very much. When he came out of his house, Jibril met him. The Messenger of Allah (ﷺ) asked him about the reason of delay, and he replied: "We do not enter a house in which there is a dog or a portrait.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1685', 'Riyad as-Salihin 1685', 'ریاض الصالحین 1685', 'رواه البخاري)) (( "راث": أبطأ، وهو بالثاء المثلثة', null, null, null, 'sunnah.com', null, false, null, false),
(21686, 2, 218, 1686, 'hadith', 'عن عائشة رضي الله عنها قالت: واعد رسول الله صلى الله عليه وسلم جبريل عليه السلام في ساعة أن يأتيه، فجاءت تلك الساعة ولم يأته! قالت: وكان بيده عصًا، فطرحها من يده وهو يقول: "ما يخلف الله وعده ولا رسله" ثم التفت، فإذا جرو كلب تحت سريره. فقال: "متى دخل هذا الكلب؟" فقلت: والله ما دريت به، فأمر به فأخرج، فجاءه جبريل عليه السلام: فقال رسول الله صلى الله عليه وسلم : "وعدتني، فجلست لك ولم تأتني" فقال: منعني الكلب الذي كان في بيتك، إنا لا ندخل بيتًا فيه كلب ولا صورة".', 'Jibril (Gabriel) (ﷺ) made a promise with the Messenger of Allah (ﷺ) to come at a definite hour; that hour came but he did not visit him. There was a staff in the hand of the Messenger of Allah (ﷺ). He threw it from his hand and said, "Never does Allah back out of His Promise, nor do His messengers." Then he noticed a puppy under his bed and said, "O ''Aishah, when did this dog enter?" She said: "By Allah, I don''t know." He then commanded that it should be turned out. No sooner than had they expelled it, Jibril came and the Messenger of Allah (ﷺ) said to him, "You promised to visit me. I waited for you but you did not come." Whereupon he said: "The dog kept me from coming. We do not enter a house in which there is a dog or a picture.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1686', 'Riyad as-Salihin 1686', 'ریاض الصالحین 1686', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21687, 2, 218, 1687, 'hadith', 'عن أبي الهياج حيان بن حصين قال: قال لي علي بن أبي طالب رضي الله عنه: ألا أبعثك على ما بعثني عليه رسول الله صلى الله عليه وسلم ؟ أن لا تدع صورة إلا طمستها، ولا قبرًا مشرفًا إلا سويته.', '''Ali bin Abu Talib (May Allah be pleased with him) said to me: "Shall I not send you to do a task that the Messenger of Allah (ﷺ) had assigned to me? Spare no portrait unwiped out, and leave not a high grave unlevelled.".', 'أبي الهياج حيان بن حصين قال: قال لي علي بن أبي طالب رضي الله عنه', 'Abul-Haiyaj Haiyan bin Husain said:', 'صحيح', 'رياض الصالحين 1687', 'Riyad as-Salihin 1687', 'ریاض الصالحین 1687', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21688, 2, 218, 1688, 'hadith', 'عن ابن عمر رضي الله عنهما قال سمعت رسول الله صلى الله عليه وسلم يقول: «من اقتنى كلبًا إلا كلب صيد أو ماشية فإنه ينقص فإنه ينقص من أجره كل يوم قيراطان» ((متفق عليه)). وفي رواية: قيراط.', 'The Messenger of Allah (ﷺ) said, "He who keeps a dog other than one for guarding the fields or herds or hunting, will lose two Qirat every day out of his rewards.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', null, 'رياض الصالحين 1688', 'Riyad as-Salihin 1688', 'ریاض الصالحین 1688', null, null, null, null, 'sunnah.com', null, false, null, false),
(21689, 2, 218, 1689, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "من أمسك كلبًا فإنه ينقص كل يوم من عمله قيراط إلا كلب حرث أو ماشية" ((متفق عليه)). وفي رواية لمسلم: "من اقتنى كلبًا ليس بكلب صيد، ولا ماشية ولا أرض، فإنه ينقص من أجره قيراطان كل يوم".', 'The Messenger of Allah (ﷺ) said, "He who keeps a dog, will lose out of his good deeds equal to one Qirat every day, except one who keeps it for guarding the fields or the herd.".In a narration of Muslim, the Messenger of Allah (ﷺ) is reported to have said: "He who keeps a dog for any reason other than to guard his property (lands) or his flock of sheep, his good deeds equal to two Qirat will be deducted every day."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', null, 'رياض الصالحين 1689', 'Riyad as-Salihin 1689', 'ریاض الصالحین 1689', null, null, null, null, 'sunnah.com', null, false, null, false),
(21690, 2, 218, 1690, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تصحب الملائكة رفقة كلب أو جرس».', 'The Messenger of Allah (ﷺ) said, "Angels do not accompany the travellers who have with them a dog or a bell.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1690', 'Riyad as-Salihin 1690', 'ریاض الصالحین 1690', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21691, 2, 218, 1691, 'hadith', 'وعنه أن النبي صلى الله عليه وسلم قال: «الجرس مزامير الشيطان».', 'The Prophet (ﷺ) said, "The bell is one of the musical instruments of Satan.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1691', 'Riyad as-Salihin 1691', 'ریاض الصالحین 1691', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21692, 2, 218, 1692, 'hadith', 'عن ابن عمر رضي الله عنهما قال: نهى رسول الله صلى الله عليه وسلم عن الجلالة في الإبل أن يركب عليها.', 'The Messenger of Allah (ﷺ) prohibited riding a camel which eats dung, or animal or human waste..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1692', 'Riyad as-Salihin 1692', 'ریاض الصالحین 1692', 'رواه أبو داود بإسناد صحيح', 'أفاد الحديث النَّهي عن ركوب الجلاَّلة من الإبل، والنهي عن شرب لبنها، -وهو متضمن للنهي عن أكل لحومها كما ورد في الأحاديث الأخرى-، والنهي في الحديث ليس خاصًّا بجنس الإبل بل هو عام في كل ما يتغذى على النجاسات والعذرات من الحيوان والطيور المأكولة -إن كان أكثر علفها من ذلك- ؛ لأنَّ لحمها ولبنها وعرقها صارت متولدات من النجاسة، فهي نجسة، إلا إذا غذيت بعد ذلك بطاهر ثلاثة أيام فأكثر، فيرتفع المنع حينئذ.', 'تحريم أكل لحوم الجلاَّلة، وشرب لبنها؛ لأنَّ لحمها ولبنها وعرقها يصير بذلك متولدًا من النجاسة، إلى أن تحبس وتطعم من العلف الطاهر ثلاثة أيام فأكثر.
النهي عن الركوب على الجلالة؛ والعلة في ذلك أنها قد تعرق فتلوث ما عليها بعرقها.', 'الجَلاَّلة : هي الحيوان الَّذي يأكل الجَلّة، -والجلة بفتح الجيم: هي البعرة-، فما يتغذى على العذرات، والنَّجاسات من الإبل أو البقر أو الغنم أو الدجاج أو غير ذلك من الحيوان والطير المأكول يسمى جَلَّالة, ولا تكون كذلك إلاَّ إذا غلب على علفها النجاسة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/64648', false),
(21693, 2, 218, 1693, 'hadith', 'عن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم : «البصاق في المسجد خطيئة، وكفارتها دفنها» ((متفق عليه)). والمرادُ بِدَفْنِهَا إذَا كَانَ المَسْجِدُ تُرَابًا أوْ رَمْلًا ونَحْوَهُ فَيُوَارِيهَا تَحْتَ تُرَابِهِ. قالَ أبُو المحاسِنِ الرُّويَانِي مِنْ أصحابِنا في كِتَابِهِ (البحر) وقِيلَ: المُرَادُ بِدَفْنِهَا إخْراجُهَا مِنَ المَسْجِدِ، أمَّا إِذَا كَانَ المَسْجِدُ مُبَلَّطًا أَوْ مُجَصَّصًا، فَدَلَكَهَا عَلَيْهِ بِمَدَاسِهِ أَوْ بِغَيْرِهِ كَمَا يَفْعَلُهُ كَثيرٌ مِنَ الجُهَّالِ، فَلَيْسَ ذَلِكَ بِدَفْنٍ، بَلْ زِيَادَةٌ فِي الخَطِيئَةِ وَتَكْثِيرٌ لِلقَذَرِ في المَسْجِدِ، وَعَلَى مَنْ فَعَلَ ذَلِكَ أنْ يَمْسَحَهُ بَعْدَ ذَلِكَ بِثَوْبِهِ أَوْ بِيَدِهِ أَوْ غَيرِهِ أَوْ يَغْسِلَهُ.', 'The Messenger of Allah (ﷺ) said, "Spitting in the mosque is a sin, and its expiation is that the spittle should be buried in earth.".', 'أنس رضي الله عنه', 'Anas bin Malik (May Allah be pleased with him) said:', null, 'رياض الصالحين 1693', 'Riyad as-Salihin 1693', 'ریاض الصالحین 1693', null, null, null, null, 'sunnah.com', null, false, null, false),
(21694, 2, 218, 1694, 'hadith', 'عن عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم رأى في جدار القبلة مخاطا أو بزاقا أو نخامة فحكه.', 'The Messenger of Allah (ﷺ) saw spittle or snot or sputum, sticking to the wall towards Qiblah and scratched it off..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1694', 'Riyad as-Salihin 1694', 'ریاض الصالحین 1694', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21695, 2, 218, 1695, 'hadith', 'عن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إن هذه المساجد لا تصلح لشيء من البول ولا القذر، إنما هي لذكر الله تعالى، وقراءة القرآن» أو كما قال رسول الله صلى الله عليه وسلم.', 'The Messenger of Allah (ﷺ) said, "It is not proper to use the mosque for urinating or easing oneself. They are merely built for the remembrance of Allah and the recitation of the Qur''an", or as he stated..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1695', 'Riyad as-Salihin 1695', 'ریاض الصالحین 1695', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21696, 2, 218, 1696, 'hadith', 'عن أبي هريرة رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول: «من سمع رجلا ينشد ضالة في المسجد فليقل: لا ردها الله عليك، فإن المساجد لم تبنَ لهذا».', 'The Messenger of Allah (ﷺ) said, "If anyone hears a man inquiring in the mosque about something he has lost, he should say: ''La raddaha Allahu ''alaika (May Allah not restore it to you),'' for mosques are not built for this purpose."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1696', 'Riyad as-Salihin 1696', 'ریاض الصالحین 1696', 'رواه مسلم', 'أرشد حديث أبي هريرة رضي الله عنه إلى أن من طلب بالمسجد شيئا ضائعا من بهيمة الأنعام، أن يقال له: (لا ردها الله عليك) أو (لا وجدت) -كما في رواية -، وهذا زجرٌ له عن ترك تعظيم المسجد.
ثم جاء التعليل النبوي لهذا الزجر لمن نشد ضالته بالمسجد، وهذا في قوله -عليه الصلاة والسلام-: (فإن المساجد لم تبن لهذا): أي وإنما بُنِيَت لذكر الله تعالى والصلاة والعلم والمذاكرة في الخير ونحو ذلك، ولما وضع هذا المُنْشِد الشيء في غير محله ناسب الدعاء عليه بعدم الوجدان؛ معاقبة له بنقيض قصده وترهيبا وتنفيرا من مثل فعله.
وفي الجملة فالحديث من قبيل الأمر بالمعروف والنهي عن المنكر، ويشترط له شروطه، وإذا دعا عليه بذلك فإن انزجر وكف فذاك، وإلا كرره.', 'أنَّ من سمع من ينشد ضالة في المسجد، فليدْعُ عليه جهرًا، بقوله: لا ردها الله عليك؛ فإنَّ المساجد لم تبن لهذا.
هذا الحكم عامٌّ؛ سواء كانت حيوانًا، أو متاعًا، أو نقدًا، أو غير ذلك؛ بجامع أنَّ المساجد لم تبن لهذا.
تحريم نشدان الضالة في المسجد، ووجوب الدعاء عليه بهذا الدعاء وجوبًا كفائيًا، وإعلامه باستحقاقه الدعاء؛ حيث اتَّخذ المسجد لنشدان الضوال، وإشغال المصلين والمتعبدين، بأعمال الدنيا.
ظاهره أنَّه لو خرج عند باب المسجد فنشدها، فإنَّه لا يحرم؛ لأنَّه ليس من المسجد.
بيان ما بني له المسجد، بأنَّه للصلاة وذكر الله وتلاوة كتابه، والمذاكرة في الخير، ونحو ذلك.', 'ينشد : نشد حاجة: طلبها وسأل عنها، وكذا إذا عرَّفها.
ضالة : الضائع من المواشي.
لا ردَّها الله عليك : دعاء عليه بنقيض قصده، وهو نوع من أنواع التعزير.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10890', false),
(21697, 2, 218, 1697, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: «إذا رأيتم من يبيع أو يبتاع في المسجد، فقولوا: لا أربح الله تجارتك، وإذا رأيتم من ينشد ضالة فقولوا: لا ردها الله عليك». رواه الترمذي، وقال: (حَدِيثٌ حَسَنٌ).', 'The Messenger of Allah said, "When you see someone buying or selling in the mosque, say to him: ''La arbaha-Allahu tijarataka (May Allah not make your bargain profitable)!'' When you see someone announcing something lost in it, say: ''May Allah not restore it to you!"''.', null, 'Abu Hurairah (May Allah be pleased with him) said:', null, 'رياض الصالحين 1697', 'Riyad as-Salihin 1697', 'ریاض الصالحین 1697', null, null, null, null, 'sunnah.com', null, false, null, false),
(21698, 2, 218, 1698, 'hadith', 'عن بريدة رضي الله عنه أن رجلا نشد في المسجد فقال: من دعا إلى الجمل الأحمر، فقال رسول الله صلى الله عليه وسلم : «لا وجدت، إنما بنيت المساجد لم بنيت له».', 'A man announced (the loss of his camel) in the mosque, uttering these words: "Has any one seen my red camel?" Upon this the Messenger of Allah (ﷺ) said, "May it not be restored to you! The mosques are built for what they are meant to be (i.e., prayer, remembrance of Allah, acquiring knowledge, etc.).".', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1698', 'Riyad as-Salihin 1698', 'ریاض الصالحین 1698', 'رواه مسلم', 'يخبر بريدة رضي الله عنه في هذا الحديث أن النبي صلى الله عليه وسلم سمع رجلًا يقول : "من دَعا إلى الجمل الأحمر" ينشد جمله الأحمر وأن من عرفه فليخبر عنه.
"لا وجَدْتَ" أي: لا رده الله عليك كما في الرواية الأخرى.
"إنما بُنِيَتِ المساجد لما بُنِيَتْ له" ثم بين له سبب الدعاء عليه، وهو : أن بيوت الله تعالى لم تبن لأمور الدنيا من إنشاد الضوال والبيع والشراء، بل بنيت للصلاة وذكر الله عز وجل وطلب الآخرة.', 'النهي عن إنشاد الضالة في المسجد.
إنكار المنكر في المسجد.
الدعاء على من أنْشَدَ ضَالته في المسجد.
يستحب الإكثار في المسجد من ذكر الله تعالى، والتسبيح، والتهليل، والتحميد، والتكبير وغيرها من الأذكار.', 'نَشَدَ : سأل برفع صوت لطلب ضالته التي فَقَدَها.
دَعَا إلى : تَعَرَّف على.
لما بُنِيَتْ له : من الصلاة والذكر وتعلم العلم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8949', false),
(21699, 2, 218, 1699, 'hadith', 'عن عمرو بن شعيب، عن أبيه، عن جده رضي الله عنه أن رسول الله صلى الله عليه وسلم نهى عن الشراء والبيع في المسجد، وأن تنشد فيه ضالة، أو ينشد فيه شعر.', 'The Messenger of Allah (ﷺ) prohibited (us) from buying and selling in the mosque; (he also prohibited us from) making announcement in it about something lost and from reciting poems in it..', 'عمرو بن شعيب، عن أبيه، عن جده رضي الله عنه', '''Amr bin Shu''aib on the authority of his grandfather (May Allah be pleased with him) said:', 'حسن', 'رياض الصالحين 1699', 'Riyad as-Salihin 1699', 'ریاض الصالحین 1699', 'رواه أبو داود، والترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21700, 2, 218, 1700, 'hadith', 'عن السائب بن زيد الصحابي رضي الله عنه قال: كنت في المسجد فحصبني رجل، فنظرت فإذا عمر بن الخطاب رضي الله عنه فقال: اذهب فائتني بهذين، فجئته بهما، فقال: من أين أنتما؟ فقالا: من أهل الطائف، فقال: لو كنتما من أهل البلد، لأوجعتكما، ترفعان أصواتكما في مسجد رسول الله صلى الله عليه وسلم !.', 'While I was in the mosque, someone threw a pebble at me, and when I looked up, I saw that it was ''Umar bin Al-Khattab, who said: "Go and call me these two men." I brought them and ''Umar (May Allah be pleased with him) asked them: "Where are you from?" On their replying that they belonged to At-Taif, he said: "Had you been the inhabitants of Al-Madinah, I would have given you a beating for raising your voices in the mosque of the Messenger of Allah (ﷺ).".', 'السائب بن زيد الصحابي رضي الله عنه', 'As-Sa''ib bin Yazid (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1700', 'Riyad as-Salihin 1700', 'ریاض الصالحین 1700', 'رواه البخاري', 'يخبر السائب بن يزيد رضي الله عنهما عن واقعة حصلت في حضرته وهي أن رجلين كانا يرفعان أصواتهما في مسجد رسول الله صلى الله عليه وسلم في عهد عمر رضي الله عنه فسمع عمر أصواتهما فحصب السائب بن يزيد، وذلك لأجل أن يأتي بالرجلين إليه.
قال السائب: فأتيته بهما، فسألهما من أين أنتما؟
فقالا: من أهل الطائف.
قال: لو كُنْتُمَا من أهل البلد، أي: من أهل المدينة لأَوْجَعْتُكُمَا بالعقوبة والضرب، تَرْفَعَان أصْوَاتَكُما في مسجد رسول الله صلى الله عليه وسلم ! ولما لم يكونا من أهل المدينة عذرهما بجهلهما؛ لأن الغالب خفاء أحكام الشرع على من كان حاله مثل حالهما.', 'كراهة رفع الصوت في المسجد ولو كان في ذِكْر أو قراءة القرآن، ويحرم ذلك إن أحدث تَشْوِيَشًا، وتَشْتَد الكراهة والحُرْمَة إن كان في خُصُومة وما شابهها.
إباحة الكلام في المسجد في غير معصية.
يستحب لمن أراد أن يُنَبِّه أحدًا إلى شيء في المسجد أن يُشير إليه حتى لا يرفع صوته.
الحث على الأمر بالمعروف والنهي عن المنكر في المسجد وغيره؛ لأنه من أعظم مقاصد الإسلام، ومنه أمْر ونهي من خالف آداب المساجد.
جواز العقوبة البدنية بالضرب وغيره لمن خالف شرع الله -عز وجل-.
بيوت الله -تعالى- جُعلت للطاعة والعبادة فيجب رعايتها بذلك، قال -تعالى-: (في بيوت أذن الله أن ترفع ويذكر فيها اسمه يسبح له فيها بالغدو والآصال رجال لا تلهيهم تجارة ولا بيع عن ذكر الله وإقام الصلاة وإيتاء الزكاة يخافون يوما تتقلب فيه القلوب والأبصار * ليجزيهم الله أحسن ما عملوا ويزيدهم من فضله والله يرزق من يشاء بغير حساب). 
الرفق بالجاهل وتعليمه آداب المساجد.
أن الإنسان يُعْذَر بجهله، ولذلك عذرهم عمر -رضي الله عنه- لبعدهم عن العلم وأهله.', 'حَصَبَنِي : رماني بالحَصْبَاء، وهي: صِغَار الحَصى.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8952', false),
(21701, 2, 218, 1701, 'hadith', 'عن ابن عمر رضي الله عنه أن النبي صلى الله عليه وسلم قال: "من أكل من هذه الشجرة -يعني الثوم- فلا يقربن مسجدنا" ((متفق عليه)). وفي رواية لمسلم: "مساجدنا".', 'The Prophet (ﷺ) said, "He who has eaten garlic should not come to our mosque.".The narration in Muslim is: "He who has eaten garlic should not come to our mosques."', 'ابن عمر رضي الله عنه', 'Ibn ''Umar (May Allah be pleased with them) said:', null, 'رياض الصالحين 1701', 'Riyad as-Salihin 1701', 'ریاض الصالحین 1701', null, null, null, null, 'sunnah.com', null, false, null, false),
(21702, 2, 218, 1702, 'hadith', 'عن أنس رضي الله عنه قال: قال النبي صلى الله عليه وسلم : «من أكل من هذه الشجرة، فلا يقربنا، ولا يصلين معنا».', 'The Prophet (ﷺ) said, "He who has eaten from this plant (i.e., garlic) should not approach us and should not offer Salat (prayer) along with us.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1702', 'Riyad as-Salihin 1702', 'ریاض الصالحین 1702', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21703, 2, 218, 1703, 'hadith', 'عن جابر رضي الله عنه قال: قال النبي صلى الله عليه وسلم : "من أكل ثومًا أو بصلا فليعتزلنا، أو فليعتزل مسجدنا" ((متفق عليه)). وفي رواية لمسلم: "من أكل البصل، والثوم، الكراث، فلا يقربن مسجدنا، فإن الملائكة تتأذى مما يتأذى منه بنو آدم".', 'The Prophet (ﷺ) said, "He who has eaten garlic or onion should keep away from us or our mosques.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', null, 'رياض الصالحين 1703', 'Riyad as-Salihin 1703', 'ریاض الصالحین 1703', null, null, null, null, 'sunnah.com', null, false, null, false),
(21704, 2, 218, 1704, 'hadith', 'عن عمر بن الخطاب رضي الله عنه أنه خطب يوم الجمعة فقال في خطبته: ثم إنكم أيها الناس تأكلون شجرتين ما أراهما إلا خبيثتين: البصل، والثوم -لقد رأيت رسول الله صلى الله عليه وسلم إذا وجد ريحهما من الرجل في المسجد أمر به، فأخرج إلى البقيع، فمن أكلهما، فليمتهما طبخًا.', '"O you people! You eat garlic and onion. I think the odour of these to be very offensive. I saw that if the Messenger of Allah (ﷺ) happened to find a man with such offensive odour in the mosque, he would order him to be taken out of the mosque and sent to Al-Baqi''. He who wants to eat any of these, should cook them till their odour dies out..', 'عمر بن الخطاب رضي الله عنه', 'It has been narrated that ''Umar (May Allah be pleased with him) said in the sermon of Friday prayer:', 'صحيح', 'رياض الصالحين 1704', 'Riyad as-Salihin 1704', 'ریاض الصالحین 1704', 'رواه مسلم', 'يخبر عمر رضي الله عنه من حضر الخطبة بأنهم يأكلون من شجرتين خَبِيثَتَيْن: البصل والثوم والمراد بالخُبث هنا: النتانة، والعرب تطلق الخبيث على كل مذموم ومكروه من قول أو فعل أو مال أو طعام أو شخص،
ويدل لذلك حديث جابر رضي الله عنه عن النبي صلى الله عليه وسلم : (من أكل من هذه الشجرة المُنْتِنَة، فلا يَقْرَبَنَّ مسجدنا) رواه مسلم.
"البَصَل، والثُّوم" وكل ما له رائحة كريهة كالفِجْل والكُراث وغير ذلك لاسيما التتن والتَّبْغ والسيجارة، وإنما خص الثوم والبصل بالذِّكر لكثرة أكلهما، ونص على الكراث في حديث جابر بن عبد الله رضي الله عنه عند مسلم. 
"إذا وجَد ريحَهُمَا من الرَّجُل في المسجد أَمَرَ به، فأُخرج إلى البَقِيع" كان النبي صلى الله عليه وسلم لا يكتفي بإخراجه من المسجد، بل يبعده عن المسجد حتى يوصله إلى البقيع، تعزيراً له؛ لأن ذلك مما يتأذى منه الناس وكذا الملائكة فإنها تتأذى منه، كما في الحديث الصحيح.
"فمن أكَلَهُمَا، فَلْيُمِتْهُمَا طَبْخاً" المعنى: أن من أحب أن يأكلهما فليمتهما طبخاً؛ لأن الطبخ يذهب رائحتهما الكريهة، وإذا ذهبت الرائحة جاز دخول المسجد بعد ذلك لانتفاء العلة، وفي حديث معاوية بن قرة عن أبيه عن النبي صلى الله عليه وسلم مرفوعاً: "إن كنتم لا بد آكليهما فأميتوهما طبخاً"رواه أبو داود، ومحل إماتتهما طبخاً : إذا أراد دخول المسجد للصلاة أو لغير الصلاة ، أما إذا لم يكن وقت صلاة أو ليس في وقت صلاة فلا بأس من أكلهما نيئًا؛ لإباحة أكلهما وإنما جاء الأمر بالطبخ للتأذي.', 'النهي عن أكل البصل والثُّوم عند الحضور إلى المسجد؛ لأن رائحتهما خبيثة، ويلحق بهما كل ما له رائحة كريهة كرائحة أسنان أو بَخَر في الفم أو رائحة دخان وما أشبه ذلك؛ لأن العلة قائمة وهي تأذي الملائكة بالروائح الكريهة.
أن البَصَل والثُّوم تذهب رائحتهما بالطبخ ولا بأس عند ذلك من حضور المسجد وشهود الجماعات.
الملائكة تتأذى مما يتأذى منه بنو آدم، فينبغي للمسلم أن يكون طيب الرائحة عند حضور أماكن العبادة ومجامع الناس.
حرص الإسلام على تآلف المسلمين، وإبعاد كل ما من شَأنه تنفيرهم أو تفريق جماعتهم.
إزالة المنكر باليد لمن أمْكَنه ذلك.
على ولاة الأمر أن يقوموا بمراقبة المساجد، ويعتنوا بنظافتها، ويوجهوا الناس إلى ذلك.
حرص عمر -رضي الله عنه- على طهارة المسجد.
بيان حرص الإسلام على النظافة الشخصية.', 'ما أَرَاهُما : لا أعلمها.
خَبِيثَتَيْن : يطلق الخَبِيْثُ على الحرام، كالزنا وعلى الرَّدِيء المُسْتَكْرَه طَعمُه أو ريحه كالثوم والبصل، ومنه الخبائث التي كانت العرب تَسْتَخْبِثْها، كالحية والعقرب.
البَقِيع : مقبرة أهل المدينة المنورة، وهي اليوم داخل المدينة المنورة بجوار المسجد النبوي الشريف شرقًا.
فَلْيُمِتْهُمَا طَبخا : من أراد أكلها فَليُمِتْ رائحتها ويذهبه بالطبخ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8953', false),
(21705, 2, 218, 1705, 'hadith', 'عن معاذ بن أنس الجهني، رضي الله عنه، أن النبي صلى الله عليه وسلم نهى عن الحبوة يوم الجمعة والإمام يخطب.', 'The Prophet (ﷺ) forbade (us) from sitting with our legs drawn up to our belly (Ihtiba'') during the Friday Khutbah (religious talk before the prayer)..', 'معاذ بن أنس الجهني رضي الله عنه', 'Mu''adh bin Anas Al-Juhani (May Allah be pleased with him) said:', 'حسن', 'رياض الصالحين 1705', 'Riyad as-Salihin 1705', 'ریاض الصالحین 1705', 'رواه أبو داود والترمذي وقالا: حديث حسن', 'هذا الحديث منسوخ كما أشار إليه أبو داود، ومعناه أن معاذ بن أنس رضي الله عنه يخبر عن نهي النبي صلى الله عليه وسلم عن الحِبْوَةِ يوم الجمعة وقت الخطبة.
والحِبْوَةِ: أن يَضم الإنسان فخذيه إلى بطنه وساقيه إلى فخذيه ويربط نفسه بسير أو عمامة أو نحوها، وقد نهى النبي صلى الله عليه وسلم عنها والإمام يخطب يوم الجمعة لسببين:
الأول: أنه ربما تكون هذه الحبوة سببًا لجلب النوم إليه فينام عن سماع الخطبة. 
والثاني: أنه مظنة لانكشاف العورة؛ لأن الغالب على العرب أن يكون على أحدهم الثوب الواحد، فإذا احتبى بَدَت عورته، ولهذا جاء النهي عنه كما في صحيح مسلم: "وأن يحتبي في ثوب واحد كاشفاً عن فرجه"، فهذا خاص بمن عليه ثوب واحد وعام في كل وقت. 
قال النووي رحمه الله : "وكان هذا الاحتباء عادة للعرب في مجالسهم، فإن انكشف معه شيء من عورته فهو حرام".
وأما إذا أمن ذلك فإنه لا بأس بها؛ لأن النهي إذا كان لعلة معقولة فزالت العلة فإنه يزول النهي، كما ثبت عنه صلى الله عليه وسلم في الصحيحين من حديث عبَّاد بن تميم، عن عمه أنه "رأى رسول الله صلى الله عليه وسلم مستلقيًا في المسجد، واضعًا إحدى رجليه على الأخرى".', 'كراهية الاحتباء أثناء خُطبة الجمعة؛ لأنه مَظِنة جَلْب النوم فيفوت استماع الخطبة وهو واجب، وقد ينتقض الوضوء الذي هو شرط لصحة الصلاة.
على المسلم أن يكون على هيئة تسترعي انتباهه للخطيب يوم الجمعة ليحصل المقصود من الخطبة وليخرج بفائدة منها.', 'الحِبْوَة : أن يقيم الجالس ركْبَتَيه، ويضم رجْلَيه إلى بَطْنِه بثوب يجمعها به مع ظَهره ويَشُد عليهما ويكون إليَتَاه على الأرض.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8955', false),
(21706, 2, 218, 1706, 'hadith', 'عن أم سلمة رضي الله عنها قالت قال رسول الله صلى الله عليه وسلم : «من كان له ذبح يذبحه، فإذا أهل هلال ذي الحجة، فلا يأخذن من شعره ولا من أظفاره شيئًا حتى يضحي».', 'The Messenger of Allah (ﷺ) said, "When anyone of you intends to sacrifice the animal and enter in the month of Dhul-Hijjah, he should not get his hair cut or nails pared till he has offered his sacrifice.".', 'أم سلمة رضي الله عنها', 'Umm Salamah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1706', 'Riyad as-Salihin 1706', 'ریاض الصالحین 1706', 'رواه مسلم', 'أَمَرَ النبيُّ صلى الله عليه وسلم مَن أراد أنْ يَذبح أضحية ألَّا يأخذَ مِن شَعَر رأسه أو إِبْطِه أو شاربه أو غيرها ولا مِن أظفار يده أو رجله شيئًا إذا ظَهَر هلالُ ذي الحجة حتى يضحِّي.', 'مَن نَوَى أن يضحي بعد دخول العشر فيبدأ الإمساك المذكور من حين نوى حتى يضحِّي.
إذا لم يُضَحِّ في اليوم الأول فيبقى مُمْسِكًا حتى يضحي في أيِّ يومٍ من أيام التشريق.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8954', false),
(21707, 2, 218, 1707, 'hadith', 'عن ابن عمر، رضي الله عنهما، عن النبي صلى الله عليه وسلم ، قال: "إن الله تعالى ينهاكم أن تحلفوا بآبائكم، فمن كان حالفًا، فليحلف بالله، أو ليصمت" ((متفق عليه)). وفي رواية في الصحيح "فمن كان حالفًا فلا يحلف إلا بالله أو ليسكت".', 'The Prophet (ﷺ) said, "Allah has prohibited you from taking an oath by your fathers. He who must take an oath, may do so by swearing in the Name of Allah or he should remain silent.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', null, 'رياض الصالحين 1707', 'Riyad as-Salihin 1707', 'ریاض الصالحین 1707', null, null, null, null, 'sunnah.com', null, false, null, false),
(21708, 2, 218, 1708, 'hadith', 'عن عبد الرحمن بن سَمُرَة، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "لا تحلفوا بالطواغي، ولا بآبائكم". ((رواه مسلم)). "الطواغي": جمع طاغية، وهي الأصنام، ومنه الحديث: "هذه طاغية دوس": أي: صنمهم ومعبودهم، وروي في غير مسلم: "بالطواغيت" جمع طاغوت، وهو الشيطان والصنم.', 'The Messenger of Allah (ﷺ) said, "Swear neither by the name of Taghut (i.e., false deities, false leaders, etc.) nor by your fathers.".', 'عبد الرحمن بن سَمُرَة رضي الله عنه', '''Abdur-Rahman bin Samurah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1708', 'Riyad as-Salihin 1708', 'ریاض الصالحین 1708', null, 'يَنْهَى النبيُّ صلى الله عليه وسلم عن الحَلِف بالطواغي، جمع طاغية، وهي الأصنام التي كان المشركون يَعبدونها مِن دون الله، وهي سببُ طغيانِهم وكفرِهم، 
وينهى صلى الله عليه وسلم عن الحلف بالآباء؛ حيث كان من عادة العرب في الجاهلية أن يَحلفوا بآبائهم افتخارًا وتعظيمًا.', 'الحَلف لا يجوز إلا بالله وأسمائه وصفاته.
تحريم الحلف بالطواغيت، والآباء والرؤساء والأصنام، وما شابَهَها من كل باطل.
الحلف بغير الله من الشرك الأصغر، وقد يكون شركًا أكبر، إذا قام بقلبه تعظيم المحلوف به وأنه يعظِّمه كما يعظِّم الله أو أنه يعتقد فيه شيئًا من العبادة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8959', false),
(21709, 2, 218, 1709, 'hadith', 'عن بريدة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «من حلف بالأمانة، فليس منا».', 'The Messenger of Allah (ﷺ) said, "He who swears by Amanah (trust) is not one of us.".', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1709', 'Riyad as-Salihin 1709', 'ریاض الصالحین 1709', 'حديث صحيح رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21710, 2, 218, 1710, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : «من حلف فقال: إني بريء من الإسلام، فإن كان كاذبًا، فهو كما قال، وإن كان صادقًا، فلن يرجع إلى الإسلام سالمًا».', 'The Messenger of Allah (ﷺ) said, "If anyone swears that in such and such case he will be free from Islam and afterwards he turns out to be a liar, he will be as he has sworn; but if he is speaking the truth, he will not revert safely to Islam.".', null, 'Buraidah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1710', 'Riyad as-Salihin 1710', 'ریاض الصالحین 1710', 'رواه أبو داود', 'من حلف فقال: هو بَرِيءٌ من الإسلام، أو قال: هو يهودي أو نصراني أو كافر أو ملحد، فأمره لا يخلو من حالين:
الحال الأولى: أن يكون كاذبًا فيما حلف عليه، كأن يحلف مثلا: هو بريء من الإسلام إن كان الأمر كذا وكذا، وهو كاذب فيما يخبر به، كما لو أخبر بأن زيدا قدم اليوم من السَّفر وحلف على البراء من الإسلام أو هو يهودي أو نصراني أو مشرك، وهو يعلم كَذب نفسه، فهو كما قال أي من البراءة من الإسلام أو يهودي أو نصراني.
الحال الثانية: أن يكون صادقا فيما قال، كما لو حلف على البراءة من الإسلام أو هو يهودي أو نصراني أن زيدًا قَدِم اليوم من سفره أو أنه لم يفعل هذا الشيء، وهو صادق فيما حلف عليه، فإنه في هذه الحال لنْ يَرْجِعَ إلى الإسلام سَالِمًا، كما قال رسول الله صلى الله عليه وسلم ، بل ينقص كمال إسلامه بما صَدَر منه من هذا اللفظ لشناعته وقبحه.', 'النهي عن الحلف بهذه الصيغة وأشباهها، كأن يقول: هو كافر إن فعل كذا، وهو على دِين كذا إن كان كذا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8965', false),
(21711, 2, 218, 1711, 'hadith', 'عن ابن عمر رضي الله عنهما أنه سمع رجلا يقول: لا والكعبة، قال ابن عمر: لا تحلف بغير الله، فإني سمعت رسول الله صلى الله عليه وسلم يقول: "من حلف بغير الله، فقد كفر أو أشرك".(( رواه الترمذي وقال حديث حسن)) وفسر بعض العلماء قوله: "كفر أو أشرك" على التغليظ، كما روي أن النبي صلى الله عليه وسلم قال: "الرياء شرك".', 'I heard a man saying: "No, by the Ka''bah." I admonished him: "Do not swear by any thing besides Allah, for I heard the Messenger of Allah (ﷺ) saying, ''He who swears by anyone or anything other than Allah, has indeed committed an act of Kufr or Shirk''."', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1711', 'Riyad as-Salihin 1711', 'ریاض الصالحین 1711', null, 'يُخبر النبيُّ صلى الله عليه وسلم أنَّ مَن حَلَف بغير الله وأسمائه وصفاته فقد كَفرَ بالله أو أشرك؛ لأن الحَلِفَ يقتضي تَعظيمَ المحلوفِ به، والعظمةُ إنَّما هي للهِ وحْدَه؛ فلا يُحلَفُ إلَّا باللهِ وأسمائِه وصِفاتِه سُبحانَه، وهذا الحلف من الشرك الأصغر؛ لكن لو أنَّ الحالِفَ عظَّم ما حَلَف به كتَعظيمِ اللهِ تعالى أو أشدَّ؛ فحينئذٍ يكونُ مِن الشِّركِ الأكبرِ.', 'التعظيم بالحلف حقّ لله سبحانه وتعالى فلا يُحلَف إلا بالله وأسمائه وصفاته.
حرص الصحابة على الأمر بالمعروف والنهي عن المنكر، وخصوصًا إذا كان المنكر مما يتعلق بالشرك أو الكفر.', 'من حلف: الحلف: اليمين، وهي توكيد الحكم بذكر معظّم تطمئن له نفس المخاطب.
كفر أو أشرك: يحتمل أن يكون هذا شكًّا من الراوي، ويحتمل أن تكون "أو" بمعنى الواو فيكون كفر وأشرك.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3359', false),
(21712, 2, 218, 1712, 'hadith', 'عن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم قال: «من خلف على مال امرئ مسلم بغير حقه، لقي الله وهو عليه غضبان» قال: ثم قرأ علينا رسول الله صلى الله عليه وسلم مصداقه من كتاب الله عز وجل: {إن الذين يشترون بعهد الله وأيمانهم ثمنًا قليلا}.', 'The Prophet (ﷺ) said, "He who takes oath to acquire the property of a Muslim unjustly will meet Allah and He will be angry with him" then he recited:"Verily, those who purchase a small gain at the cost of Allah''s Covenant and their oaths, they shall have no portion in the Hereafter. Neither will Allah speak to them nor look at them on the Day of Resurrection nor will He purify them, and they shall have a painful torment." (3:77).', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1712', 'Riyad as-Salihin 1712', 'ریاض الصالحین 1712', 'آل عمران: 77)) إلى آخر الآية: ((متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21713, 2, 218, 1713, 'hadith', 'عن أبي أُمامة إياس بن ثعلبة الحارثي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "من اقتطع حق امرئ مسلم بيمينه، فقد أوجب الله له النار. -وحرم عليه الجنة" فقال له رجل: وإن كان شيئًا يسيرًا يا رسول الله؟ قال: "وإن كان قضيبًا من أراك".', 'The Messenger of Allah (ﷺ) said, "He who misappropriates the right of a Muslim by taking a false oath, Allah will condemn him to the fire of Hell and will forbid Jannah for him." A person asked: "O Messenger of Allah, even if it is something insignificant?" He replied, "Yes, even if it is the twig of the Arak tree.".', 'أبي أُمامة إياس بن ثعلبة الحارثي رضي الله عنه', 'Abu Umamah Iyas bin Tha''labah Al-Harithi (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1713', 'Riyad as-Salihin 1713', 'ریاض الصالحین 1713', 'رواه مسلم', 'حَذَّرَ النبيُّ صلى الله عليه وسلم مِن الحَلِف بالله كاذبًا عالمًا وذلك لاقتطاع حقِّ امرئ مسلم، فإنّ جزاء ذلك استحقاق النار، والحِرْمان من الجنة، وهو من كبائر الذنوب.

فقال رجل يا رسول الله: وإن كان المَحْلُوف عليه شيئًا قليلًا؟ 

فقال صلى الله عليه وسلم: حتى لو كان ذلك في عُوْد السِّوَاك الذي يُؤخذ من شجرة الأراك.', 'الحذر من أخذ حقوق الآخرين، والحرص على أدائها لأصحابها مهما قَلَّتْ، وأنَّ حكم الحاكم بالخطأ لا يُبيح للإنسان ما لم يكن له.
قال النووي: غلظ تحريم حقوق المسلمين، وأنه لا فرق بين قليل الحق وكثيره؛ لقوله صلى الله عليه وسلم: "وإن قضيبًا من أراك".
قال النووي: هذه العقوبة لمن اقتطع حق المسلم ومات قبل التوبة، أما من تاب فندم على فعله وردَّ الحق إلى صاحبه وتَحَلَّل منه وعزم على أن لا يعود فقد سقط عنه الإثم.
قال القاضي: تخصيص المسلم لكونهم المخاطبين وعامة المتعاملين في الشريعة، لا أنَّ غير المسلم بخلافه، بل حُكمُه حُكمُه في ذلك.
قال النووي: الكذب هو الإخبار عن الشيء على خلاف ما هو، عمدًا كان أو سهوًا، سواء كان الإخبار عن ماض أو مستقبل.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5430', false),
(21714, 2, 218, 1714, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «الكبائر: الإشراك بالله، وعقوق الوالدين، وقتل النفس، واليمين الغموس» ((رواه البخاري)). وفي رواية: أن أعرابيًا جاء إلى النبي صلى الله عليه وسلم فقال: يا رسول الله ما الكبائر؟ قال: الإشراك بالله قال: ثم ماذا؟ قال: اليمين الغموس قلت: وما اليمين الغموس؟ قال: الذي يقتطع مال امرئ مسلم يعني بيمين هو فيها كاذب', 'The Prophet (ﷺ) said, "Of the major sins are: Associating anything in worship with Allah, disobedience to the parents, killing without justification and taking a false oath (intentionally).".Another narration is: A bedouin came to the Prophet (ﷺ) and asked him: "O Messenger of Allah, what are the cardinal sins?" He (ﷺ) replied, "Associating anything with Allah in worship." The man asked: "(What is) next?" The Messenger of Allah (ﷺ) replied, "Al-Yamin Al-Ghamus." He asked: "What do you mean by Al-Yamin Al-Ghamus?" The Messenger of Allah (ﷺ) replied, "Swearing falsely to usurp the property of a Muslim."', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-As (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1714', 'Riyad as-Salihin 1714', 'ریاض الصالحین 1714', null, 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم كبائر الذنوب، وهي التي تُوُعِّدَ فاعلُها بوعيد شديد في الدنيا أو الآخرة. 

فأوَّلُها "الإِشرَاكُ بِالله": وهو صَرْفُ أيِّ نوع من أنواع العبادة لغير الله، وتسوية غير الله بالله فيما هو من خصائص الله في ألوهيته وربوبيته وأسمائه وصفاته. 

وثانيها "عُقُوقُ الوَالِدَينِ": وهو كلُّ ما يوجب الأذى للأبوين قولًا كان أو فعلًا، وترك الإحسان إليهما. 

وثالثها "قَتْل النَّفْس": بغير حق، كالقتل ظلمًا وعدوانًا. 

ورابعها "اليَمِين الغَمُوسُ": وهي الحلف كاذبًا على علم منه بكذبه، سميت بذلك؛ لأنَّها تَغْمِسُ صاحبَها في الإِثم أو في النار.', 'اليمين الغموس لا كفارة لها؛ لشدة خطرها وجرمها، وإنما فيها التوبة.
الاقتصار على ذكر هذه الكبائر الأربع في الحديث لعظيم إثمها، وليس لحصرها.
الذنوب تنقسم إلى كبائر وصغائر، والكبيرة هي: كلُّ ذنب فيه عقوبة دنيوية، كالحدود واللعن، أو وعيد أُخروي، كالوعيد بدخول النار، وأن الكبائر دركات بعضها أغلظ من بعض في التحريم، وصغائر الذنوب هي ما سوى الكبائر.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3044', false),
(21715, 2, 218, 1715, 'hadith', 'عن عبد الرحمن بن سَمُرَة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «وإذا حلفت على يمين، فرأيت غيرها خيرًا منها، فائت الذي هو خير، وكفر عن يمينك».', 'The Messenger of Allah (ﷺ) said to me, "When you take an oath and consider something else to be better than it, make expiation for your oath and choose the better alternative.".', 'عبد الرحمن بن سَمُرَة رضي الله عنه', '''Abdur-Rahman bin Samurah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1715', 'Riyad as-Salihin 1715', 'ریاض الصالحین 1715', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21716, 2, 218, 1716, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «من حلف على يمين، فرأى غيرها خيرًا منها، فليكفر عن يمينه، وليفعل الذي هو خير».', 'The Messenger of Allah (ﷺ) said, "When you swear an oath and consider something else to be better than it, make expiation for your oath and do the thing that is better.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1716', 'Riyad as-Salihin 1716', 'ریاض الصالحین 1716', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21717, 2, 218, 1717, 'hadith', 'عن أبي موسى رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إني والله إن شاء الله لا أحلف على يمين، ثم أرى خيرًا منها إلا كفرت عن يميني، وأتيت الذي هو خير».', 'The Messenger of Allah (ﷺ) said, "Verily, I swear by Allah, if Allah wills, I shall not swear to do something but that if I consider something else to be better than it, then I shall make expiation for my oath and adopt the thing that is better.".', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1717', 'Riyad as-Salihin 1717', 'ریاض الصالحین 1717', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21718, 2, 218, 1718, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "لأن يلج أحدكم في يمينه في أهله آثم له عند الله تعالى من أن يعطي كفارته التي فرض الله عليه". ((متفق عليه)) قوله: "يلَجّ" بفتح اللام، وتشديد الجيم: أي يتمادى فيها، ولا يكفر، قوله: "آثم" هو بالثاء المثلثة، أي: أكثر إثمًا.', 'The Messenger of Allah (ﷺ) said, "Persistence in respect of his oath about his family is more sinful with Allah than the payment of its expiation prescribed by Allah.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1718', 'Riyad as-Salihin 1718', 'ریاض الصالحین 1718', null, 'معنى الحديث إذا حلف المسلم يمينًا تتعلق بأهله ويتضررون بعدم حنثه ولا يكون في رجوعه عن يمينه معصية لله عز وجل ، ثم هو يتمادى ويُصرُّ على إمضاء يمينه في أهله أكثر إثماً وأعظم جرماً له من الرجوع والكفارة، لأنه يتعين عليه أن يُكَفِّر عن يمينه التي فرضَها الله عليه ولا يتَمادَى ولا يُصر على يمينه، ما دام أن رجوعه عن يمينه ليس فيه معصية لله تعالى ، بل إن تماديه وإصراره على يمينه معصية وإثم عظيم؛ لما في ذلك من الإضرار بالأهل، وقد جعل الله له في الأمر سَعَة، وفي الصحيحين: (إذا حلفت على يمين فرأيت غيرها خيراً منها، فأت الذي هو خير، وكفر عن يمينك).', 'طلب الحِنْث باليمين، وعدم تنفيذ المُقْسَم عليه إذا كان ذلك أفضل من تنفيذه.
الإصرار على اليمين رغم ما في غيرها من فضل عليها نوع من التَّمَادي وزيادة في الإثم.
الحث على الاقتداء برسول الله -صلى الله عليه وسلم-.
الحث على إبعاد الضرر عن الأهل، ورعايتهم بمنهج الله لا بالأهواء المضطربة.
الرجوع عن الخطأ خُير من التَّمادي فيه.
جواز الحلف من غير استحلاف.
الحث على معاملة الأهل بالحسنى والاستيصاء بهم خيراً.', 'يَلَجَّ : يتمادى فيها، ولا يكفر.
آثمُ : أكثر إثمًا.
أن يعطي كفارته التي افترض الله عليه : أن يحنث بيمينه ثم يدفع الكفارة التي فرضها الله -تعالى- على حنث بيمينه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8963', false),
(21719, 2, 218, 1719, 'hadith', 'عن عائشة رضي الله عنها قالت: أنزلت هذه الآية: {لا يؤاخذكم الله باللغو في أيمانكم} في قول الرجل: لا والله، وبلى والله.', 'The Ayah: "Allah will not punish you for what is unintentional in your oaths ..." was revealed in respect of those persons who are in the habit of repeating: ''No, by Allah''; and ''Yes, by Allah.''.', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1719', 'Riyad as-Salihin 1719', 'ریاض الصالحین 1719', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21720, 2, 218, 1720, 'hadith', 'عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «الحلف منفقة للسلعة، ممحقة للكسب».', 'I heard the Messenger of Allah (ﷺ) saying, "Swearing produces a ready sale for a commodity, but blots out the blessing.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1720', 'Riyad as-Salihin 1720', 'ریاض الصالحین 1720', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21721, 2, 218, 1721, 'hadith', 'عن أبي قتادة رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول: «إياكم وكثرة الحلف في البيع، فإنه ينفق ثم يمحق».', 'I heard the Messenger of Allah (ﷺ) saying, "Beware of excessive swearing in sale, because it may promote trade but this practice will eliminate the blessing.".', 'أبي قتادة رضي الله عنه', 'Abu Qatadah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1721', 'Riyad as-Salihin 1721', 'ریاض الصالحین 1721', 'رواه مسلم', 'معنى الحديث: احذروا كثرة الحلف في البيع والشراء ولو صدقًا؛ لأن كثرة الحلف مظنة الوقوع في الكذب، فمثلًا لا ينبغي للإنسان أن يقول: والله لقد اشتريتها بمائة. ولو كان صادقًا، ولو قال: والله لقد اشتريتها بمائة. ولم يشترها إلا بثمانين صار أشد؛ لأنه يكون بذلك كاذبًا حالفًا في البيع، وقد نهى النبي صلى الله عليه وسلم عن ذلك، وأخبر بأن الأيمان في البيع سبب في إنفاق السلع، ثم إن الله تعالى يمحق بركتها؛ لأن هذا الكَسب مَبْنِي على معصية رسول الله صلى الله عليه وسلم ، ومعصية رسول الله -عليه الصلاة والسلام- معصية لله تعالى .', 'الحث على ترك الحَلِف في التعامل والتحذير منه؛ لما فيه من جعل الله تعالى آلة لترويج البضاعة وجَلب الرِّبْح والحصول على عَرَض من الدنيا قليل.
الحلف في التعامل مع الصدق مكروه، وأما مع الكذب فحرام ، وهو كبيرة ويمين غَمُوس.', 'يُنَفِّقُ ثم يَمْحَقُ : يُروِّج ثم يَنقص وتذهب بركته.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8958', false),
(21722, 2, 218, 1722, 'hadith', 'عن جابر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا يسأل بوجه الله إلا الجنة».', 'The Messenger of Allah (ﷺ) said, "No one should ask in the Face of Allah for anything except Jannah.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', null, 'رياض الصالحين 1722', 'Riyad as-Salihin 1722', 'ریاض الصالحین 1722', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(21723, 2, 218, 1723, 'hadith', 'عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «من استعاذ بالله فأعيذوه، ومن سأل بالله، فأعطوه، ومن دعاكم فأجيبوه، ومن صنع إليكم معروفًا فكافئوه، فإن لم تجدوا ما تكافئونه به، فادعوا له حتى تروا أنكم قد كافأتموه».', 'The Messenger of Allah (ﷺ) said, "Grant shelter to him who begs for it in the Name of Allah, give to him who begs in the Name of Allah, accept the invitation of him who invites you, and requite him who does a favour to you, but if you are unable to requite him, go on praying for him till you are sure that you have requited him adequately.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1723', 'Riyad as-Salihin 1723', 'ریاض الصالحین 1723', 'حديث صحيح رواه أبو داود والنسائي بأسانيد الصحيحين', 'قال رسول الله صلى الله عليه وسلم: من طلب منكم بالله أن تدفعوا عنه شركم أو شر غيركم، مثل أن يقول: يا فلان بالله عليك، أو أسألك بالله: أن تدفع عني شرك، أو شر فلان، أو احفظني من فلان، فأجيبوه، واحفظوه؛ تعظيمًا لاسم الله تعالى، ومن سأل بالله فأعطوه تعظيمًا لاسم الله تعالى، وشفقةً على عباده.
ومن دعاكم إلى طعام فأجيبوه، وهذا أيضًا من حق المسلم على المسلم.
ومن أحسن إليكم إحسانًا قوليًا أو فعليًا، فأحسنوا إليه بمثل ما أحسن إليكم، فإلم تستطيعوا أن تكافئوه وتحسنوا له بالمثل فكافئوه بالدعاء له، بأن تسألوا الله تعالى أن يكافئه على معروفه، وكرروا الدعاء، وبالغوا فيه حتى تظنوا مكافأتكم له باستجابة دعائكم له.', 'مشروعية إعطاء من سأل بالله عز وجل.

إعاذة من استعاذ بالله عز وجل.

مشروعية إجابة الداعي.

مكافأة من أحسن بالمال، فإلم يوجد المال فبالدعاء.

مشروعية مكافأة المُهدي.', 'من استعاذ بالله فأعيذوه: من سألكم بالله فأعينوه.

دعاكم: إلى وليمة ونحوها.

فكافئوه: فجازوه على إحسانه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65615', false),
(21724, 2, 218, 1724, 'hadith', 'عن أبي هريرة رضي الله عنه النبي صلى الله عليه وسلم قال: «إن أخنع اسم عند الله عز وجل رجل تسمى ملك الأملاك" ((متفق عليه)). قال سُفيانُ بن عُيَيْنَةَ: «مَلِكُ الأَمْلاَكِ» مِثْلُ: شَاهِن شَاهِ.', 'The Prophet (ﷺ) said, "The most disgraceful man near Allah is a man who calls himself (or likes others to call him) Malikul-Amlak (i.e., king of kings).".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', null, 'رياض الصالحين 1724', 'Riyad as-Salihin 1724', 'ریاض الصالحین 1724', null, null, null, null, 'sunnah.com', null, false, null, false),
(21725, 2, 218, 1725, 'hadith', 'عن بريدة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تقولوا للمنافق سيد، فإنه إن يكن سيدًا، فقد أسخطتم ربكم عز وجل».', 'The Messenger of Allah (ﷺ) said, "Do not address a hypocrite with the title of chief, (or similar titles of respect) for even if he deserves this title you will invite Allah''s Wrath by using it for him.".', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1725', 'Riyad as-Salihin 1725', 'ریاض الصالحین 1725', 'رواه أبو داود بإسناد صحيح', 'معنى الحديث أن المنافق إن كان سيدًا كبيرًا في قومه وأطلقتم عليه لقب: سيد، فقد أسخطتم الله؛ لأنه يكون تعظيمًا له، وهو ممن لا يستحق التعظيم، وإن لم يكن سيدًا في قومه أو كبيرًا في قومه، فإنه يكون كذبًا ونفاقًا، ففي الحالين ينهى عن إطلاق لفظ السيد على المنافق، ومثله الكافر والفاسق والمبتدع، فهو لا يستحق وصف السِّيادة مطلقًا، وهذا النهي عام للصحابة ومن بعدهم، وقد كان المنافقون في عهدهم على قسمين، الأول: منافقون لا يعلمهم إلا النبي صلى الله عليه وسلم وصاحب السر وهو حذيفة رضي الله عنه ، والثاني: منافقون عرف الصحابة نفاقهم، كعبد الله بن أبي، وهذا ينطبق عليه الحديث.', 'تحريم وصف المنافق بأوصاف الاحترام والتقدير، وأن وصفه بذلك يستدعي غضب الله -عز وجل-؛ لأنه تعظيم لعدوِّه الخارج عن طاعته المستحق للإهانة والتحقير.
يلحق بالمنافق: الفاسق والكافر  والمبتدع.
لا يستحق الاحترام والتقدير إلا من تواضع لله -تعالى- بطاعته، والتزام حدوده.
ينبغي على المجتمع المسلم ألا يجعل للمنافقين ثَغرة يلجؤون منها لتوجيه شؤون المسلمين، بل ينبغي إذلالهم؛ لأنهم خالفوا أمر الله ورسوله.
جواز تَسْييد غير المنافق، إن كان أهلاً لذلك، كالعلماء وأهل الفضل.', 'أسْخَطْتُمْ : أغْضَبْتُم.
إن يَكُ سَيِّدًا : أي مرتفع القَدْر على من سِواه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8962', false),
(21726, 2, 218, 1726, 'hadith', 'عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم دخل على أم السائب، أو أم المسيب فقال: "مالك يا أم السائب -أو يا أم المسيب- تزفزفين؟ " قالت: الحمى لا بارك الله فيها، فقال: "لا تسبي الحمى، فإنها تذهب خطايا بني آدم، كما يذهب الكير خبث الحديد" ((رواه مسلم)). «تُزَفْزِفِينَ» أيْ تَتَحَرَّكِينَ حَرَكَةً سَريعَةً، وَمَعْنَاهُ: تَرْتَعِدِين. وَهُوَ بِضَمِّ التاء وبالزاي المكررة والفاء المكررة، وَرُوِيَ أيضًا بالراء المكررة والقافينِ.', 'The Messenger of Allah (ﷺ) visited Umm Sa''ib (or Umm Musaiyyab) and asked her, "What ails you O Umm Sa''ib (or Umm Musaiyyab)? You are shivering." She replied: "It is a fever, may Allah not bless it!" He said to her, "Do not revile fever, for it cleanses out the sins of the sons of Adam in the same way that a furnace removes the dirt of iron.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1726', 'Riyad as-Salihin 1726', 'ریاض الصالحین 1726', null, 'يخبر جابر رضي الله عنه في هذا الحديث : أن النبي صلى الله عليه وسلم دخل على أم السائب رضي الله عنها وهي تَرْتَعِد، فسألها عن سبب ذلك، فقالت: "الحُمَّى" أي أن سبب ذلك ما أصابها من الحُمَّى. والحُمَّى: سخونة تصيب البدن، وهي نوع من الأمراض وهي أنواع متعددة.
قولها: "لا بارك الله فيها" دعاء على ما ابتليت به من مرض الحُمَّى.
فنهاها النبي صلى الله عليه وسلم عن سَبِّ الحُمى؛ لأنها من أفعال الله تعالى وكل شيء من أفعال الله فإنه لا يجوز للإنسان أن يَسُبَّه؛ لأن سبَّه سبٌّ لخالقه جل وعلا ولهذا قال النبي صلى الله عليه وسلم : "لا تسبوا الدهر فإن الله هو الدهر" وعلى المرء إذا أصيب أن يصبر، ويحتسب الأجر على الله عز وجل .
وقال: "فإنها تُذهب خَطَايَا بَنِي آدم كما يذهب الكِيْرُ خَبَثَ الحديد" والمعنى أن مرض الحُمَّى سبب في تكفير السيئات ورفع الدرجات، كما أن الحديد إذا صَهر على النار ذهب وسخه ورديئه وبقي صافيًا، كذلك تفعل الحُمَّى، فإنها تذهب صغائر ذنوب بني آدم، حتى يعود نقيًا صافيًا منها.', 'أن الآلام والأسْقَام سبب في تكفير الذنوب وزيادة في الحسنات.
لا يجوز التبرم والتَّضَجُّر من أقدار الله -تعالى-، فإن ذلك مُنَافٍ للصبر والرضا.
النهي عن سَبِّ شيء يقرب إلى الله وإن كان فيه مشقة على العباد.
حرص رسول الله -صلى الله عليه وسلم- على تقريب علوم الدين لأصحابه بأيسر أسلوب، وضرب الأمثلة المحسوسة لتستقر في أفهامهم، وترسخ في عقولهم.', 'الحُمَّى : سُخُونة تُصيب البدن.
خَطَايَا : ذنوب صغيرة متعلقة بحق الله -تعالى-.
الكِيْرُ : الآلة التي يَنفخ بها الحدَّادُ النارَ.
خَبَثَ الحديد : وسَخَه الذي في ضِمْنِه، وهي: الشوائب الغريبة عن معدنه.
تُزَفْزِفِين : تتحركين حركة سريعة، ومعناه: ترتعد', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8961', false),
(21727, 2, 218, 1727, 'hadith', 'عن أبي المنذر أبي بن كعب رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تسبوا الريح، فإذا رأيتم ما تكرهون، فقولوا: اللهم إنا نسألك من خير هذه الريح وخير ما فيها وخير ما أُمرت به، ونعوذ بك من شر هذه الريح وشر ما فيها وشر ما أُمرت به».', 'The Messenger of Allah (ﷺ) said, "Do not revile the wind. When you experience something abominable (about it), supplicate: ''Allahumma inna nas''aluka min khairi hadhihir-rihi, wa khairi ma fiha, wa khairi ma umirat bihi. Wa na''udhu bika min sharri hadhihir-rihi, wa sharri ma fiha, wa sharri ma umirat bihi. (O Allah, we beg of You the good of this wind and the good of that which it contains and the good of that which it has been commanded; and we seek refuge in you from the evil of this wind and the evil of that which it contains and the evil of that which it has been commanded).".', 'أبي المنذر أبي بن كعب رضي الله عنه', 'Abul-Mundhir Ubaiy bin Ka''b (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1727', 'Riyad as-Salihin 1727', 'ریاض الصالحین 1727', 'رواه الترمذي وقال حديث حسن صحيح', 'نَهَى صلى الله عليه وسلم عن شَتْم أو لَعْن الريح، فإنها مأمورة من خالقها، تأتي بالرحمة وبالعذاب، وسَبُّها سَبٌّ لله خالقِها، وتَسَخُّط على قضائه، ثم أَرْشَد صلى الله عليه وسلم إلى الرجوع إلى الله خالقها بسؤاله من خيرها وخير ما فيها وخير ما أُرسلت كإتيانها بالمطر ونقل اللِّقَاح ونحوه، والاستعاذة بالله من شرها وشر ما فيها وشر ما أرسلت به كإتلاف النبات والشجر وهلاك الماشية وهدم الأبنية، ونحوه، وفي سؤال الله ذلك تحقيق للعبودية لله.', 'النهي عن سب الريح؛ لأنها خَلْقٌ مُدَبَّرٌ، فيَرْجِعُ السَّبُّ إلى خالقها ومُدَبِّرِها، وهو نقص في التوحيد.
الرجوع إلى الله والاستعاذة به من شر ما خلق.
الريح تكون مأمورة بالخير، وتكون مأمورة بالشر.
قال ابن باز: سب الريح من جملة المعاصي؛ لأنها مخلوق مدبر ترسل بالخير والشر؛ فلا يجوز سبُّها، ولا يقال: لعن الله الريح، أو قاتل الله الريح، أو لا بارك الله في هذه الريح، أو ما أشبه ذلك، بل يعمل المؤمن ما أرشد إليه النبي صلى الله عليه وسلم.
يقاس على الريح في تحريم الشَّتْم والسب ما يتعلق بالحر والبرد والشمس والغبار وغير ذلك مما هو من خَلْق الله وتصريفه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5976', false),
(21728, 2, 218, 1728, 'hadith', 'عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «الريح من روح الله، تأتي بالرحمة، وتأتي بالعذاب، فإذا رأيتموها فلا تسبوها، وسلوا الله خيرها، واستعيذوا بالله من شرها».((رواه أبو داود بإسناد حسن)) قوله صلى الله عليه وسلم من روح الله هو بفتح الراء أي رحمته بعباده', 'I heard the Messenger of Allah (ﷺ) saying, "The wind is the Blessing of Allah. Sometimes it brings His Mercy and sometimes it brings His Chastisement. When you experience it, do not revile it but beg of Allah its good; and seek Allah''s Refuge against its evil.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1728', 'Riyad as-Salihin 1728', 'ریاض الصالحین 1728', null, 'الرِّيحُ من رحمة الله تعالى بعباده، تأتي بالرَّحمة وتأتي بالعَذَاب، فهو تعالى يرسل الرَّياح رحمة بعباده، فيحصل بسببها الخير والبركة للناس، كما في قوله تعالى : (وأرسلنا الرياح لواقح) وقوله تعالى : (الله الذي يرسل الرياح فتثير سحابًا فيبسطه في السماء كيف يشاء ويجعله كسفا فترى الودق يخرج من خلاله) وقوله تعالى : (وهو الذي يرسل الرياح بشرًا بين يدي رحمته حتى إذا أقلت سحابًا ثقالًا سقناه لبلد ميت فأنزلنا به الماء). الآية.
وتأتي بالعَذَاب، كما في قوله تعالى : (فأرسلنا عليهم ريحًا صرصرًا في أيام نحسات لنذيقهم عذاب الخزي في الحياة الدنيا) وقوله تعالى : (إنا أرسلنا عليهم ريحًا صرصرًا في يوم نحس مستمر تنزع الناس كأنهم أعجاز نخل منقعر) وقوله تعالى : (قالوا هذا عارض ممطرنا بل هو ما استعجلتم به ريح فيها عذاب أليم).
قال صلى الله عليه وسلم : "فإذا رَأَيْتُمُوهَا فَلاَ تَسُبُّوهَا " فلا يجوز للمسلم أن يُسبَّ الريح؛ لأنها مخلوقة من مخلوقات الله مأمورة بأمره ولا تأثير لها في شيء، لا بنفع ولا بِضُرٍّ إلا بأمر الله عز وجل ، فيكون شتمها شتمًا لخالقها ومُدبّرها، وهو الله سبحانه . 
وقال: "وسَلُوا الله خَيرها، واسْتَعِيذُوا بالله من شرِّها" بعد أن نهى النبي صلى الله عليه وسلم عن سَبِّ الرِّيح أرشد أُمَّته عند هبوبها أن يسألوا الله تعالى من خَيرها ويستعيذوا من شرِّها
والمعنى: أن يسألوا الله تعالى أن يُحقق لهم ما تحمله من خَير، ويَصْرِف عنهم من تحمله من شرٍّ.', 'النهي عن سَبِّ الريح وغيرها من ظواهر الكون؛ لأنها كلها مُسَخَّرة بأمر الله تعالى فيما خُلقت له.
ليس من خلق المسلم السَّب والشَّتم، حتى ولو كان لغير الإنسان.
ظواهر الكون آيات من آيات الله -عز وجل- ومظاهر من مظاهر قدرته يكون فيها الخير والرحمة لمن أراد الله -تعالى- رحمته، ويكون فيها الويل والثبور لمن أراد الله -تعالى- عذابه.
الرِّياح فيها الخير الكثير من صلاح الرزق والبَدن، وفيها الشَّر المُسْتَطِير من إهلاك الحَرْث والنَّسْل، فيحسُن بالمسلم أن يسأل الله تعالى أن يُمَتِّعه بخيرها ويحفظه من شَرِّها.
الالتجاء إلى الله والتضرع إليه عند هبوب الرياح وسؤال الله من خيرها والاستعاذة من شَرِّها.', 'من رَوْحِ الله : من رحمته بعباده.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8957', false),
(21729, 2, 218, 1729, 'hadith', 'عن عائشة رضي الله عنها قالت: كان النبي صلى الله عليه وسلم إذا عصفت الريح قال: اللهم إني أسألك خيرها، وخير ما فيها، وخير ما أُرسلت به، وأعوذ بك من شرها، وشر ما فيها، وشر ما أُرسلت به".', 'Whenever the wind blew strongly, The Prophet (ﷺ) would say: "Allahumma inni as''aluka khairaha, wa khaira ma fiha, wa khaira ma ursilat bihi. Wa a''udhu bika min sharriha, wa sharri ma fiha, wa sharri ma ursilat bihi. (O Allah, I beg of You its good and the good of that which it contains and the good of the purpose for which it has been sent; and I seek Your Refuge from its evil and the evil of that which it contains and the evil of the purpose for which it has been sent).".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1729', 'Riyad as-Salihin 1729', 'ریاض الصالحین 1729', 'رواه مسلم', 'تخبر عائشة رضي الله عنها أن من هديه صلى الله عليه وسلم عندما تَعْصِف الريِّح، أي عند اشتداد هُبُوِبها، قال: " اللَّهُمَّ إنِّي أسْأَلُك خَيرها وخير ما فيها.." والريح التي خلقها الله عز وجل وصرفها تنقسم إلى قسمين:
الأول: ريح عادية لا تخيف، فهذه لا يُسَن لها ذكر معين.
الثاني: ريح عاصفة تخيف؛ لأن عادا عَذَّبهم الله تعالى بالرِّيح العَقِيم والعياذ بالله، فإذا عصفت الرِّيح، فقل كما هو هديه -صلى الله عليه سلم-: "اللَّهُمَّ إنِّي أسْأَلُك خَيرها وخير ما فيها وخَير ما أُرسِلت به" أي تسال الله -عزو جل- خير هذه الريح وخير ما تحمله من منافع؛ لأنها تارة ترسل بالخير وتارة ترسل بالشَّر، فتسأل الله خير ما أُرسلت به مما ينشأ عنها.
"وأعوذ بك من شرِّها وشرِّ ما فيها وشرِّ ما أُرسِلت به" أي تستعيذ من شرِّها وشرِّ ما تحمله وشرِّ ما تُرسل به؛ لأنها قد تكون عذابا على قوم فتتعوذ من شرِّها. 
فإذا استعاذ الإنسان من شرِّها وشرِّ ما فيها وشرِّ ما أرسلت به كفاه الله شرَّها، وانتفع بخيرها.', 'الرِّياح فيها الخير الكثير من صلاح الرزق والبَدن، وفيها الشَّر المُسْتَطِير من إهلاك الحَرْث والنَّسْل، فيحسُن بالمسلم أن يسأل الله -تعالى- أن يُمَتِّعه بخيرها ويحفظه من شَرِّها.
الالتجاء إلى الله والتضرع إليه عند هبوب الرياح وسؤال الله من خيرها والاستعاذة من شَرِّها.
ليس من خلق المسلم السب والشتم واللعن.
كراهية سب الريح وغيرها من ظواهر الكون؛ لأنها مُسَخَّرةٌ لله -تعالى-.
ظواهر الكون من آيات الله فيها الرحمة لمن أراد الله رحمته، والعذاب للمتمردين عن طاعته.', 'عَصَفَت : اشْتَدَّ هُبوبها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8956', false),
(21730, 2, 218, 1730, 'hadith', 'عن زيد بن خادل الجهني رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تسبوا الديك، فإنه يوقظ للصلاة».', 'The Messenger of Allah (ﷺ) said, "Do not revile the rooster for it wakes you up for prayer.".', 'زيد بن خادل الجهني رضي الله عنه', 'Zaid bin Khalid Al-Juhani (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1730', 'Riyad as-Salihin 1730', 'ریاض الصالحین 1730', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21731, 2, 218, 1731, 'hadith', 'عن زيد بن خالد رضي الله عنه قال: صلى بنا رسول الله صلى الله عليه وسلم صلاة الصبح بالحديبية في أثر سماء كانت من الليل، فلما انصرف أقبل على الناس، فقال: "هل تدرون ماذا قال ربكم؟ " قالوا: الله ورسوله أعلم. قال: قال: "أصبح من عبادي مؤمن بي وكافر بي ، فأما من قال: مُطِرْنَا بفضل الله ورحمته، فذلك مؤمن بي كافر بالكواكب، وأما من قال: مُطِرْنَا بنوء كذا وكذا، فذلك كافر بي مؤمن بالكواكب" ((متفق عليه)). والسماء هنا: المطر.', 'The Messenger of Allah (ﷺ) led the Fajr prayer at Al-Hudaibiyyah after a rainfall during the night. At the conclusion of prayer, he turned towards the people and said, "Do you know what your Rubb has said?" They replied: "Allah and His Messenger know better." Upon this he remarked, "He has said: ''Some of My slaves have entered the morning as My believers and some as unbelievers. He who said: We have had a rainfall due to the Grace and Mercy of Allah, believes in Me and disbelieves in the stars; and he who said: We have had a rainfall due to the rising of such and such star, disbelieves in Me and affirms his faith in the stars."''.', 'زيد بن خالد رضي الله عنه', 'Zaid bin Khalid (May Allah be pleased with him) said:', null, 'رياض الصالحين 1731', 'Riyad as-Salihin 1731', 'ریاض الصالحین 1731', null, null, null, null, 'sunnah.com', null, false, null, false),
(21732, 2, 218, 1732, 'hadith', 'عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «إذا قال رجل لأخيه: يا كافر، فقد باء بها أحدهما، فإن كان كما قال وإلا رجعت عليه».', 'The Messenger of Allah (ﷺ) said, "When a person calls his brother (in Islam) a disbeliever, one of them will certainly deserve the title. If the addressee is so as he has asserted, the disbelief of the man is confirmed, but if it is untrue, then it will revert to him.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1732', 'Riyad as-Salihin 1732', 'ریاض الصالحین 1732', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21733, 2, 218, 1733, 'hadith', 'عن أبي ذر رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول: «من دعا رجلا بالكفر، أو قال: عدو الله، وليس كذلك إلا حار عليه» ((متفق عليه)). حار رجع.', 'I heard the Messenger of Allah (ﷺ) saying, "If somebody accuses another of disbelief or calls him the enemy of Allah, such an accusation will revert to him (the accuser) if the accused is innocent.".', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him) said:', null, 'رياض الصالحين 1733', 'Riyad as-Salihin 1733', 'ریاض الصالحین 1733', null, null, null, null, 'sunnah.com', null, false, null, false),
(21734, 2, 218, 1734, 'hadith', 'عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ليس المؤمن بالطعان، ولا اللعان، ولا الفاحش، ولا البذي».', 'The Messenger of Allah (ﷺ) said, "A true believer does not taunt or curse or abuse or talk indecently.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1734', 'Riyad as-Salihin 1734', 'ریاض الصالحین 1734', 'رواه الترمذي وقال حديث حسن', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنه ليس مِن شَأنِ المؤمنِ الكامِلِ الإيمانِ أنْ يكونَ عيّابًا للناس في أنسابهم، ولا كثير الشتائم واللعن، ولا الفاحش بالفعل ولا بالقول الذي لا حياء له.', 'نفيُ الإيمانِ في النصوص الشرعية لا يكون إلا لِفعل مُحرّم أو ترك واجب.
الحث على حفظِ الجوارح وصونِها عن المساوئ، خاصة اللسان.
قال السندي: وفي صيغة المبالغة في (الطعّان، واللعّان) دلالة على أن صدور الطعن واللعن على قِلَّة فيمن يستحق ذلك لا يضر في الاتصاف بصفات أهل الإيمان.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65869', false),
(21735, 2, 218, 1735, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ما كان الفحش في شيء إلا شانه، وما كان الحياء في شيء إلا زانه».', 'The Messenger of Allah (ﷺ) said, "Indecency does not leave anything untainted and decency does not leave anything ungraced and embellished.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'حسن', 'رياض الصالحين 1735', 'Riyad as-Salihin 1735', 'ریاض الصالحین 1735', 'رواه الترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21736, 2, 218, 1736, 'hadith', 'عن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم قال: «هلك المتنطعون»، قالها ثلاثًا.', 'The Prophet (ﷺ) said, "Ruined are Al-Mutanatti''un." He repeated this thrice..', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1736', 'Riyad as-Salihin 1736', 'ریاض الصالحین 1736', 'رواه مسلم."المتنطعون": المبالغون في الأمور', null, null, null, 'sunnah.com', null, false, null, false),
(21737, 2, 218, 1737, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «إن الله يبغض البليغ من الرجال الذي يتخلل بلسانه كما تتخلل البقرة».', 'The Messenger of Allah (ﷺ) said, "Verily, Allah dislikes an eloquent person who rolls his tongue as a cow rolls its tongue (while eating).".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-As (May Allah be pleased with them) said:', 'حسن', 'رياض الصالحين 1737', 'Riyad as-Salihin 1737', 'ریاض الصالحین 1737', 'رواه أبو داود والترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21738, 2, 218, 1738, 'hadith', 'عن جابر بن عبد الله رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «إن من أحبكم إلي، وأقربكم مني مجلسًا يوم القيامة، أحاسنكم أخلاقًا، وإن أبغضكم إلي وأبعدكم مني يوم القيامة، والثرثارون، والمتشدقون، والمتفيهقون».((رواه الترمذي وقال حديث حسن)). وقد سبق شرحه في باب حسن الخلق.', 'The Messenger of Allah (ﷺ) said, "The dearest and the closest of you to me on the Day of Resurrection will be those who are the best in behaviour; and the most hateful and the farthest from me on the Day of Resurrection will be the talkative and the most pretentious and the most rhetorical.".', 'جابر بن عبد الله رضي الله عنهما', 'Jabir bin ''Abdullah (May Allah be pleased with them) said:', null, 'رياض الصالحين 1738', 'Riyad as-Salihin 1738', 'ریاض الصالحین 1738', null, null, null, null, 'sunnah.com', null, false, null, false),
(21739, 2, 218, 1739, 'hadith', 'عن عائشة رضي الله عنها عن النبي صلى الله عليه وسلم قال: «لا يقولن أحدكم خبثت نفسي، ولكن ليقل: لقست نفسي» ((متفق عليه)). قال العلماء معنى خبثت أي غثيت وهو معنى لقست ولكن كره لفظ الخبث', 'The Prophet (ﷺ) said, "None of you should say: ''My soul has become evil.'' He should say: ''My soul is in bad shape."''.', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1739', 'Riyad as-Salihin 1739', 'ریاض الصالحین 1739', null, 'نهى النبي صلى الله عليه وسلم أن يقول الشخص: خَبُثت نفسي، وأمر أن يقول: لَقِسَت نفسي، أي أنه حصل لنفسه تغير وضيقة، فتوصف بالوصف الذي ليس فيه مخالفة للأدب، ولقست وخبثت بمعنى واحد، لكن لفظ الخبث قبيح، ويجمع أمورًا زائدة على المراد، بخلاف اللَّقَس، فإنه يختص بامتلاء المعدة، وإنما كره صلى الله عليه وسلم من ذلك اسم الخبث فاختار اللفظة السالمة من ذلك، وكان من سنته تبديل الاسم القبيح بالحسن، فإن عبر بما يؤدي معناه كفى، فالذي منعه النبي صلى الله عليه وسلم إنما هو أن يطلق الإنسان على نفسه لفظ الخبث، فيذم نفسه ويضيف الذم إليها، وهو ممنوع ومذموم في مثل هذا، وأما لو أضاف الإنسان لفظ الخبث إلى غيره ممن يصدق عليه لم يكن ذلك مذمومًا ولا ممنوعًا، كما قال صلى الله عليه وسلم في حديث: (...وَإِلَّا أَصْبَحَ خَبِيثَ النَّفْسِ كَسْلاَنَ).', 'النهي عن قول: خبثت نفسي، وإنما ينبغي أن يقال: لقست نفسي، أو ما في معناه، ويلتحق بهذا أن الضعيف إذا سئل عن حاله لا يقول: لست بطيب، بل يقول: ضعيف، ولا يخرج نفسه من الطيبين، فيلحقها بالخبيثين.

استحباب مجانبة الألفاظ القبيحة والأسماء السيئة، والعدول إلى ما لا قبح فيه.

ينبغي للمرء أن يطلب الخير حتى بالفأل الحسن، ويقطع الوصلة بينه وبين أهل الشر، حتى في الألفاظ المشتركة.', 'لقست: غَثَت، واللقس: الغثيان.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66287', false),
(21740, 2, 218, 1740, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "لا تسموا العنب الكَرْم، فإن الكَرْم المسلم" ((متفق عليه)). ((وهذا لفظ مسلم)). وفي رواية: "فإنما الكرم قلب المؤمن" وفي رواية للبخاري ومسلم: "يقولون الكرم، إنما الكرم قلب المؤمن".', 'The Messenger of Allah (ﷺ) said, "None of you should use the word Al-Karm for grapes, for Al-Karm is a Muslim (worthy of respect)."Another narration is: "Verily, Al-Karm is the heart of a true believer."Another narration is: "People have named grapes as Al-Karm; verily, only the heart of a believer is Al-Karm."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', null, 'رياض الصالحين 1740', 'Riyad as-Salihin 1740', 'ریاض الصالحین 1740', null, null, null, null, 'sunnah.com', null, false, null, false),
(21741, 2, 218, 1741, 'hadith', 'عن وائل بن حجر رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا تقولوا: الكَرْم، ولكن قولوا: العنب، والحَبَْلة» رواه مسلم الحبلة بفتح الحاء والباء ويقال أيضا بإسكان الباء', 'The Prophet (ﷺ) said, "Do not say Al-Karm when talking about grapes but say Al-''Inab or Al-Habalah.".', 'وائل بن حجر رضي الله عنه', 'Wa''il bin Hujr (May Allah be pleased with him) said:', null, 'رياض الصالحين 1741', 'Riyad as-Salihin 1741', 'ریاض الصالحین 1741', null, null, null, null, 'sunnah.com', null, false, null, false),
(21742, 2, 218, 1742, 'hadith', 'عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تباشر المرأة المرأة، فتصفها لزوجها كأنه ينظر إليها».', 'The Messenger of Allah (ﷺ) said, "No woman should touch another woman''s body and then describe the details of her figure to her husband in such a manner as if he was looking at her.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1742', 'Riyad as-Salihin 1742', 'ریاض الصالحین 1742', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21743, 2, 218, 1743, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا يقولن أحدكم: اللهم اغفر لي إن شئت: اللهم ارحمني إن شئت، ليعزم المسألة، فإنه لا مكره له».', 'The Messenger of Allah (ﷺ) said, "You must not supplicate: ''O Allah! forgive me if You wish; O Allah bestow mercy on me if You wish.'' But beg from Allah with certitude for no one has the power to compel Allah."Another narration of Muslim is: "A supplication should be made in full confidence and one should persistently express his desire (before Allah) in his supplication, for no bounty is too great for Allah to bestow (upon his slaves)."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1743', 'Riyad as-Salihin 1743', 'ریاض الصالحین 1743', 'متفق عليه)). ((وفي رواية لمسلم: "ولكن ليعزم، وليعظم الرغبة، فإن الله تعالى، لا يتعاظمه شيء أعطاه"', null, null, null, 'sunnah.com', null, false, null, false),
(21744, 2, 218, 1744, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا دعا أحدكم، فليعزم المسألة، ولا يقولن: اللهم إن شئت، فأعطني، فإنه لا مستكره له».', 'The Messenger of Allah (ﷺ) said, "When one of you supplicates, let him be decisive and he should not say: ''O Allah, bestow upon me such and such if You wish'', because no one has the power to compel Him.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1744', 'Riyad as-Salihin 1744', 'ریاض الصالحین 1744', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21745, 2, 218, 1745, 'hadith', 'عن حذيفة بن اليمان رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا تقولوا: ما شاء الله وشاء فلان، ولكن قولوا: ما شاء الله، ثم شاء فلان». رواه أبو داود بإسناد صحيح', 'The Prophet (ﷺ) said, "Say not: ''What Allah wills and so-and-so wills'', but say: ''What Allah wills, and then what so-and-so wills."''.', 'حذيفة بن اليمان رضي الله عنه', 'Hudhaifah bin Yaman (May Allah be pleased with him) said:', 'صحيح بمجموع طرقه', 'رياض الصالحين 1745', 'Riyad as-Salihin 1745', 'ریاض الصالحین 1745', null, 'نَهَى النبيُّ صلى الله عليه وسلم أنْ يقولَ المسلمُ في كلامه: "ما شاء الله وشاء فلان"، 
أو ما شاء الله وفلان؛ 
وذلك لأنَّ مَشيئةَ الله وإرادتَه مُطْلَقَةٌ ولا يشاركه فيها أحد، 
وفي استخدام الواو في العطف إشعارٌ بمشاركةِ أحدٍ مع الله والتسوية بينهما. 
ولكن يقول: ما شاء الله، ثم شاء فلان، 
فيجعل مشيئةَ العبدِ تابعةً لمشيئة الله بقول: "ثم" بدلًا من "و"، لأن "ثم" تفييد التعقيب والتراخي.', 'تحريم قول: "ما شاء الله وشئت"، وما أشبه ذلك من الألفاظ مما فيه العطف على الله بالواو؛ لأنه من شرك الألفاظ والأقوال.
جواز قول: "ما شاء الله ثم شئت"، وما أشبه ذلك مما فيه العطف على الله بثُمَّ؛ لانتفاء المحذور فيه.
إثبات المشيئة لله، وإثبات المشيئة للعبد، وأن مشيئة العبد تابعة لمشيئة الله تعالى.
النهي عن إشراك الخلق في مشيئة الله ولو باللفظ.
إن اعتقد القائل أن مشيئة العبد كمشيئة الله جل وعلا مساوية لها في الشمول والإطلاق، أو أن العبد له مشيئة مستقلة فهو شرك أكبر، أما إن اعتقد أنه دونه؛ فهو شرك أصغر.', null, 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3352', false),
(21746, 2, 218, 1746, 'hadith', 'عن أبي برزة رضي الله عنه أن رسول الله صلى الله عليه وسلم كان يكره النوم قبل العشاء والحديث بعدها.', 'The Messenger of Allah (ﷺ) disliked going to bed before the ''Isha'' (night) prayer and indulging in conversation after it.".', 'أبي برزة رضي الله عنه', 'Abu Barzah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1746', 'Riyad as-Salihin 1746', 'ریاض الصالحین 1746', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21747, 2, 218, 1747, 'hadith', 'عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم صلى العشاء في آخر حياته، فلما سلم، قال: «أرأيتكم ليلتكم هذه؟ فإن على رأس مائة سنة لا يبقي ممن هو على ظهر الأرض اليوم أحد».', 'Once, towards the end of his life, the Messenger of Allah (ﷺ) concluded the ''Isha'' (night) prayer and said, "After one hundred years from tonight none of the people on the surface of the earth will survive.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1747', 'Riyad as-Salihin 1747', 'ریاض الصالحین 1747', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21748, 2, 218, 1748, 'hadith', 'عن أنس رضي الله عنه أنهم انتظروا النبي صلى الله عليه وسلم ، فجاءهم قريبًا من شطر الليل فصلى بهم، يعني العشاء، قال: ثم خطبنا فقال: «ألا إن الناس قد صلوا. ثم رقدوا، وإنكم لن تزالوا في صلاة ما انتظرتم الصلاة».', 'Once the Prophet (ﷺ) delayed the ''Isha'' (night) prayer till midnight. He (ﷺ) turned to us after the prayer and said, "All the people slept after offering their prayers, but you who waited, will be accounted as if you were engaged in your prayer throughout the period.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1748', 'Riyad as-Salihin 1748', 'ریاض الصالحین 1748', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21749, 2, 218, 1749, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا دعا الرجل امرأته إلى فراشه فأبت، فبات غضبان عليها، لعنتها الملائكة حتى تصبح» ((متفق عليه)). وفي رواية: حتى: ترجع.', 'The Messenger of Allah (ﷺ) said, "If a man calls his wife to his bed and she refuses, and thus he spends the night angry with her, the angels continue cursing her till the morning.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1749', 'Riyad as-Salihin 1749', 'ریاض الصالحین 1749', null, 'في هذا الحديث دلالة أنَّ على المرأة إذا دعاها الرجل إلى حاجته في الجماع أن تجيبه، وإلا عرضت نفسها للعن الملائكة، لكن هذا مقيدٌ بما إذا غضب الزوج كما ورد في رواية البخاري، أما إذا رضي بذلك فلا بأس، وكذلك إذا كان هناك عذر شرعي كما لو كانت مريضة لا تستطيع معاشرته أو كان عليها عذر يمنعها من الحضور إلى فراشه فهذا لا بأس به، وإلا فإنه يجب عليها أن تحضر وأن تجيبه وإذا كان هذا في حق الزوج على الزوجة فكذلك ينبغي للزوج إذا رأى من أهله أنهم يريدون التمتع فإنه ينبغي أن يجيبهم ليعاشرها كما تعاشره فإن الله تعالى قال: (وعاشروهن بالمعروف).', 'عِظم حق الزوج على زوجته، وأنه يجب له عليها السمع والطاعة في المعروف.
أنَّه يحرم على المرأة أن تمتنع أو تماطل أو تتكرَّه على زوجها إذا دعاها إلى فراشه من أجل الجماع، وأنَّ امتناعها هذا يُعتبر كبيرةً من كبائر الذنوب؛ فإنَّه يترتب عليه أنَّ الملائكة تلعنها حتى تصبح.
أنَّ العشرة الحسنة والصُحبة الطيبة هي أنْ تسعى المرأة في قضاء حقوق زوجها الواجبة عليها، وتلبية رغباته، وأن تؤديها على أكمل وجه ممكن.
جواز لعن العصاة ولو كانوا مسلمين، لكنه مقيد بكونه لعنًا عامًّا ولا يجوز توجيهه للمعين.
 في الحديث دليل على قبول دعاء الملائكة للآدميين من خير أو شر.', 'دعا الرجل امرأته : أي طلبها.
إلى فراشه : بكسر الفاء، وهو هنا كناية عن الجماع.
لعنتها الملائكة : دعت عليها الملائكة باللعنة.
حتى تصبح : حتى يطلع الصباح، لكن هذا القيد أغلبي، لأن أكثر طلب الجماع يكون في الليل، فإذا طلب الرجل جماع زوجته نهارا وامتنعت يلحقها الوعيد أيضًا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58098', false),
(21750, 2, 218, 1750, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا يحل للمرأة أن تصوم وزوجها شاهد إلا بإذنه، ولا تأذن في بيته إلا بإذنه».', 'The Messenger of Allah (ﷺ) said, "It is not lawful for a woman to observe an optional Saum (fast) without the permission of her husband when he is at home. Nor should she allow anyone to enter his house without his permission.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1750', 'Riyad as-Salihin 1750', 'ریاض الصالحین 1750', 'متفق عليه', 'لا يجوز للمرأة أن تصوم نفلًا أو واجبًا على التراخي وزوجها موجود عندها إلا بإذنه، لأن من حقه الاستمتاع بها في كل وقت، ولا يجوز لها أن تأذن لأحد رجل أو امرأة أن يدخل في بيته إلا بإذنه، فلو علمَتْ رضاه جاز، وما أنفقت من نفقة من ماله قدرًا يعلم رضاه به عن غير إذنه الصريح في ذلك القدر المعين، بل عن إذن عام سابق يتناول هذا القدر وغيره، فإنه يكتب له من أجر ذلك القدر  نصفَه.', 'وجوب أخذ الإذن من الزوج في صيام زوجته غير رمضان، والواجب المضيق، كالقضاء.

عدم إدخال الناس في بيت الزوج إلا بعد أخذ إذنه.

إنفاق الزوجة من مال زوجها بالمعروف يثمر تساويهما في الأجر.', 'شطره: نصفه، أو جزء منه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65954', false),
(21751, 2, 218, 1751, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: «أما يخشى أحدكم إذا رفع رأسه قبل الإمام أن يجعل الله رأسه رأس حمار! أو يجعل الله صورته صورة حمار».', 'The Prophet (ﷺ) said, "Does he who raises up his head before the Imam not fear that Allah will make his head that of a donkey or make his appearance similar to that of donkey?".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1751', 'Riyad as-Salihin 1751', 'ریاض الصالحین 1751', 'متفق عليه', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم الوعيدَ الشديدَ على مَن يَرفَعُ رأسَه قبل إمامِهِ، بأنْ يجعلَ اللهُ رأسَه رأسَ حِمار، أو يَجعلَ صورتَه صورةَ حمار.', 'للمأموم مع الإمام أربع حالات: ثلاث منهي عنها، وهي: المسابقة والموافقة والتأخر، والمشروع للمأموم: المتابعة للإمام.
وجوب متابعة المأموم للإمام في الصلاة.
الوعيدُ بتغيير صورة من يرفع رأسه قبل الإمام إلى صورة حمار أَمْرٌ ممكن، وهو مِن المسخ.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3086', false),
(21752, 2, 218, 1752, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم: نهى عن الخصر في الصلاة.', 'We are prohibited from placing the hand on the side during As-Salat (the prayer)..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1752', 'Riyad as-Salihin 1752', 'ریاض الصالحین 1752', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21753, 2, 218, 1753, 'hadith', 'عن عائشة رَضِيَ اللهُ عنها، قالت: سَمِعْتُ رسولَ الله - صلى الله عليه وسلم - يقولُ: «لا صَلاَةَ بِحَضْرَةِ طَعَامٍ، وَلاَ وَهُوَ يُدَافِعُهُ الأَخْبَثَانِ».', 'I heard the Messenger of Allah (ﷺ) saying, "No Salat (prayer) should be performed when the food has been served, nor should it be performed when a person is in need of relieving himself.".', null, '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1753', 'Riyad as-Salihin 1753', 'ریاض الصالحین 1753', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21754, 2, 218, 1754, 'hadith', 'عن أنس بن مالك قَالَ : قَالَ رسولُ اللهِ : « مَا بَالُ أقْوامٍ يَرْفَعُونَ أبْصَارَهُمْ إِلَى السَّمَاءِ في صَلاَتِهِمْ » ! فَاشْتَدَّ قَولُهُ في ذَلِكَ حَتَّى قَالَ : « لَيَنْتَهُنَّ عَنْ ذَلِكَ ، أَوْ لَتُخطفَنَّ أَبْصَارُهُمْ » ! . رواه البخاري', 'The Messenger of Allah (ﷺ) said, "How is it that some people raise their eyes towards the sky during As-Salat (the prayer)?" He stressed (this point) and added, "People must refrain from raising their eyes towards heaven in Salat (prayer), or else their sights will certainly be snatched away.".', null, 'Anas bin Malik (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1754', 'Riyad as-Salihin 1754', 'ریاض الصالحین 1754', null, 'حذَّر النبي صلى الله عليه وسلم الذين يرفعون أبصارهم إلى السماء في الصلاة عند الدعاء أو غيره، ثم اشتد زَجْرُه وتوعُّدُه صلى الله عليه وسلم على من يفعل ذلك بأنه يخشى على أبصارهم أن تُخطف منهم وتؤخذ بسرعة بحيث لا يشعرون إلا وقد فَقَدوا نِعمة البَصر.', 'حُسن دعوة النبي صلى الله عليه وسلم وبيان الحق؛ لأنه صلى الله عليه وسلم لم يَكشف عن المُخالف؛ لأن المقصود بيان الحقِّ وقد حصل؛ ولأن فيه سَترًا على المخالف وأدعى للقبول.
النَّهي الأكيد، والوعيد الشَّديد على من رفع بَصره إلى السماء في الصلاة.
قال في عون المعبود: والعلة في ذلك أنه إذا رفع بصره إلى السماء خرج عن سمت القبلة وأعرض عنها وعن هيئة الصلاة.
منافاة رفع البصر للخشوع في الصلاة.
عِظَم شأن الصلاة، وأنه يجب على المُصلِّي أن يكون فيها على كمال الأدب مع الله عز وجل.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10883', false),
(21755, 2, 218, 1755, 'hadith', 'عن عائشة رضي الله عنها قالت: سألت رسول الله صلى الله عليه وسلم عن الالتفات في الصلاة فقال: «هو اختلاس يختلسه الشيطان من صلاة العبد».', 'I asked the Messenger of Allah (ﷺ) about random looks in Salat (prayer), and he replied, "It is something which Satan snatches from the slave''s Salat.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1755', 'Riyad as-Salihin 1755', 'ریاض الصالحین 1755', 'رواه البخاري', 'سألت عائشة رسول الله صلى الله عليه وسلم ، عن حكم الالتفات في الصلاة، هل يَضرُّ بالصلاة ويؤثر عليها؟
فذكر لها أن هذا الالتفات هو اختطاف يختطفه الشيطان من صلاة العَبْد على وجه السُّرعة والخُفْيَة من أجل أن يُخِلَّ بها وينقص ثوابها.', 'حِرص عائشة -رضي الله عنها- على أخذ العلم لأجل العمل به.
التَّحذير من الالتِفَات في الصلاة؛ لأنه من عَمَل الشيطان؛ لما يترتب عليه من حصول النَّقص في الصلاة.
كراهة الالتِفَات في الصلاة إلاَّ لحاجة، ما لم يكن الالتِفَات باستدَارة جميع البَدن عن القِبْلة أو استدبارها، فإنه يبطل الصلاة؛ لأن استقبال القبلة شرط في الصلاة.', 'الالتِفَات : صَرف الوجه إلى جِهة اليَمين أو الشِّمال.
اخْتِلاس : انتقاص ينتقصه الشيطان من صلاة العبد على وجه الخفية والسرعة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10878', false),
(21756, 2, 218, 1756, 'hadith', 'عن أنس رضي الله عنه قال: قال لي رسول الله صلى الله عليه وسلم : «إياك والالتفات في الصلاة، فإن الالتفات في الصلاة هلكة، فإن كان لابد، ففي التطوع لا في الفريضة».', 'The Messenger of Allah (ﷺ) said to me, "Beware of looking around in Salat (prayer), because random looks in Salat are a cause of destruction. If there should be no help from it, it is permissible in the voluntary and not in obligatory Salat.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1756', 'Riyad as-Salihin 1756', 'ریاض الصالحین 1756', 'رواه الترمذي وقال حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21757, 2, 218, 1757, 'hadith', 'عن أبي مرثد كناز بن الحصين رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «لا تصلوا إلى القبور، ولا تجلسوا عليها».', 'I heard the Messenger of Allah (ﷺ) saying: "Do not offer Salat (prayer) facing the graves and do not sit on them.".', 'أبي مرثد كناز بن الحصين رضي الله عنه', 'Abu Marthad Kannaz bin Husain (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1757', 'Riyad as-Salihin 1757', 'ریاض الصالحین 1757', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21758, 2, 218, 1758, 'hadith', 'عن أبي الجهيم عبد الله بن الحارث بن الصمة الأنصاري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لو يعلم المار بين المصلي ماذا عليه لكان أن يقف أربعين خيرًا له من أن يمر بين يديه».', 'The Messenger of Allah (ﷺ) said, "If the person who passes in front of a praying person, realizes the enormity of the sinfulness of this act, it will have been better for him to wait forty than to pass in front of him."', 'أبي الجهيم عبد الله بن الحارث بن الصمة الأنصاري رضي الله عنه', 'Abul-Juhaim ''Abdullah bin Al-Harith (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1758', 'Riyad as-Salihin 1758', 'ریاض الصالحین 1758', 'قال الراوي: لا أدري قال أربعين يومًا، أو أربعين شهرًا، أو أربعين سنة)). ((متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21759, 2, 218, 1759, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إذا أقيمت الصلاة، فلا صلاة إلا المكتوبة».', 'The Prophet (ﷺ) said, "When the Iqamah is called, no prayer should be performed except the obligatory prayer.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1759', 'Riyad as-Salihin 1759', 'ریاض الصالحین 1759', 'رواه مسلم', 'نهى النبي صلى الله عليه وسلم من كان في المسجد أن يبدأ في صلاة نافلة بعد إقامة الصلاة للفريضة.', 'النهي عن صلاة النافلة إذا أقيمت صلاة الفريضة وهو في المسجد.
النهي عن افتتاح نافلة بعد إقامة الصلاة، سواء كانت راتبة كسنة الصبح والظهر أو غيرها.
إذا أقيمت الصلاة وهو في النافلة؛ فإن بقي منها أقل من ركعة أتمّها خفيفة، وإلا قطعها حتى يدرك فضيلة تكبيرة الإحرام.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65739', false),
(21760, 2, 218, 1760, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا تخصوا ليلة الجمعة بقيام من بين الليالي، ولا تخصوا يوم الجمعة بصيام من بين الأيام إلا أن يكون في صوم يصومه أحدكم».', 'The Prophet (ﷺ) said, "Do not choose the Friday night among all other nights for standing in (Tahajjud) prayer, and do not choose Friday among all other days for Saum (fasting) except that one you have accustomed to.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1760', 'Riyad as-Salihin 1760', 'ریاض الصالحین 1760', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21761, 2, 218, 1761, 'hadith', 'وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «لا يصومن أحدكم يوم الجمعة إلا يومًا قبله أو بعده».', 'I heard the Messenger of Allah (ﷺ) as saying: "None of you should observe fast on Friday except that he should observe fast either one day before it or one day after it.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1761', 'Riyad as-Salihin 1761', 'ریاض الصالحین 1761', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21762, 2, 218, 1762, 'hadith', 'عن محمد بن عباد قال: سألت جابرًا رضي الله عنه: أنهى النبي صلى الله عليه وسلم عن صوم يوم الجمعة؟ قال: نعم.', 'I asked Jabir (May Allah be pleased with him). Did the Prophet (ﷺ) prohibit fasting on Friday?" He said, "Yes.".', 'محمد بن عباد قال: سألت جابرًا رضي الله عنه', 'Muhammad bin ''Abbad (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1762', 'Riyad as-Salihin 1762', 'ریاض الصالحین 1762', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21763, 2, 218, 1763, 'hadith', 'عن أم المؤمنين جويرة بنت الحارس رضي الله عنها أن النبي صلى الله عليه وسلم دخل عليها يوم الجمعة وهي صائمة، فقال: " أصمت أمس؟" قالت: لا، قال: " تريدين أن تصومي غدا " قالت: لا، قال : "فأفطري".', 'Juwairiyah bint Al-Harith (May Allah be pleased with her), the Mother of the Believers, said that the Prophet (ﷺ) visited her on a Friday and she was observing fast. He asked, "Did you observe fast yesterday?" She said, "No." He asked, "Do you intend to observe fast tomorrow?" She said, "No." He said, "In that case, give up your fast today.".', 'أم المؤمنين جويرة بنت الحارس رضي الله عنها', null, 'صحيح', 'رياض الصالحين 1763', 'Riyad as-Salihin 1763', 'ریاض الصالحین 1763', 'رواه البخاري', 'دخل النبي صلى الله عليه وسلم على جُوَيرِيَة بنت الحارث رضي الله عنها زوج رسول الله عليه الصلاة والسلام، في يوم الجمعة وكانت صائمة، فسألها عليه الصلاة والسلام هل صمتي يوم أمس؟ أي يوم الخميس، قالت: لا، فسألها هل ستصومين غدًا يوم السبت؟ قالت لا، فأمرها بأن تفطر.
وفيه النهي عن إفراد يوم الجمعة بالصيام؛ تعظيمًا له، أما من كان هذا صيامه المعتاد كمن يصوم يومًا بعد يوم فلا يدخل في النهي، وفيه جواز صيام يوم السبت في غير رمضان، والحديث الوارد في النهي عن صيامه لا يصح، واستنكره العلماء المتقدمون.', 'النهي عن إفراد صوم يوم الجمعة لذاته تعظيمًا له.

لا يدخل في النهي من صام يوم الجمعة ضمن صيامه المعتاد.', '--', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65521', false),
(21764, 2, 218, 1764, 'hadith', 'عن أبي هريرة وعائشة رضي الله عنهما أن النبي صلى الله عليه وسلم نهى عن الوصال.', 'The Prophet (ﷺ) prohibited observing continuous voluntary fasts beyond one day..', 'أبي هريرة وعائشة رضي الله عنهما', 'Abu Hurairah and ''Aishah (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1764', 'Riyad as-Salihin 1764', 'ریاض الصالحین 1764', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21765, 2, 218, 1765, 'hadith', 'عن ابن عمر رضي الله عنهما قال: نهى رسول الله صلى الله عليه وسلم عن الوصال. قالوا :إنك تواصل؟ قال: «إني لست مثلكم، إني أُطعم وأُسقى» ((متفق عليه)). ، وهذا لفظ البخاري.', 'The Messenger of Allah (ﷺ) prohibited observing continuous fasts beyond one day. The Companions submitted: "But you do it." He replied, "I am not like you. I am given to eat and to drink (from Allah).".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', null, 'رياض الصالحين 1765', 'Riyad as-Salihin 1765', 'ریاض الصالحین 1765', null, null, null, null, 'sunnah.com', null, false, null, false),
(21766, 2, 218, 1766, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « لأن يجلس أحدكم على جمرة، فتحرق ثيابه، فتخلص على جلده خير له من أن يجلس على قبر».', 'The Messenger of Allah (ﷺ) said, "It is much better for one of you to sit on a live coal, which will burn his clothes and get to his skin than to sit on a grave.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1766', 'Riyad as-Salihin 1766', 'ریاض الصالحین 1766', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21767, 2, 218, 1767, 'hadith', 'عن جابر رضي الله عنه قال: نهى رسول الله صلى الله عليه وسلم أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه.', 'The Messenger of Allah (ﷺ) forbade that the graves should be plastered (made into permanent structures), used as sitting places (for the people) or building over them..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1767', 'Riyad as-Salihin 1767', 'ریاض الصالحین 1767', 'رواه مسلم', 'نهى النبي صلى الله عليه وسلم أن يبنى القبر بالجِصِّ، وهي مادة بيضاء يُزيَّن بها البناء، وعن الجلوس فوق القبر وعن البناء عليه، سواءٌ كان البناء غرفةً أو قُبَّةً أو مسجدًا، والقبر يُحترم كما يحترم المسلم المدفون فيه، فيعامل بالأدب وبالتسليم عليه والدعاء له، وبنحو ذلك، دون ما ثبت النهي عنه، ووجه النهي عن البناء والتجصيص في القبور أن ذلك مباهاة واستعمال زينة الدنيا في أول منازل الآخرة، وهذا غير مناسب، وفيه تشبه بمن كان يعظِّم القبور ويعبدها من الأمم السابقة، وهو وسيلة للوقوع في مثل ما وقعوا فيه.', 'بيان النهي عن تجصيص القبر.

بيان النهي عن البناء على القبر.

بيان النهي عن الجلوس على القبر.

أن هذا النهي على التحريم؛ لعدم ورود صارف له.', 'يجصص: يبنى بالجص ويُطلى به.

يقعد عليه: يُجلس عليه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65572', false),
(21768, 2, 218, 1768, 'hadith', 'عن جرير بن عبد الله رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : «أيما عبد أبق، فقد برئت منه الذمة ».', 'The Messenger of Allah (ﷺ) said, "If a slave runs away from his master, his responsibility to him is absolved.".', 'جرير بن عبد الله رضي الله عنه', 'Jarir bin Abdullah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1768', 'Riyad as-Salihin 1768', 'ریاض الصالحین 1768', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21769, 2, 218, 1769, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم : "إذا أبق العبد، لم تقبل له صلاة " ((رواه مسلم)) . وفي رواية: "فقد كفر " .', 'The Prophet (ﷺ) said, "When the slave runs away from his master, his Salat (prayer) will not be accepted.".Another narration is: "He is guilty of disbelief (i.e., in case he believes in the lawfulness of doing so)."', null, 'Jarir bin Abdullah (May Allah be pleased with him) said:', null, 'رياض الصالحين 1769', 'Riyad as-Salihin 1769', 'ریاض الصالحین 1769', null, null, null, null, 'sunnah.com', null, false, null, false),
(21770, 2, 218, 1770, 'hadith', 'عن عائشة رضي الله عنها، أن قريشًا أهمهم شأن المرأة المخزومية التي سرقت فقالوا: من يكلم فيها رسول الله صلى الله عليه وسلم ؟ فقالوا: ومن يجترئ عليه إلا أسامة بن زيد، حب رسول الله صلى الله عليه وسلم :، فكلمه أسامة فقال صلى الله عليه وسلم :"أتشفع في حد من حدود الله تعالى؟ "ثم قام فاختطب، ثم قال: "إنما أهلك الذين قبلكم أنهم كانوا إذا سرق فيهم الشريف تركوه، وإذا سرق فيهم الضعيف، أقاموا عليه الحد، وايم الله لو أن فاطمة بنت محمد سرقت لقطعت يدها" ((متفق عليه)). وفي رواية فتلون وجه رسول الله صلى الله عليه وسلم " فقال: "أتشفع في حد من حدود الله؟" قال أسامة: استغفر لي يا رسول الله قال: ثم أمر بتلك المرأة فقطعت يدها.', 'The Quraish were anxious about a woman from Banu Makhzum who had committed theft and asked : "Who will speak to the Messenger of Allah (ﷺ) about her?" Then they said: "No one will be bold enough to do so except Usamah bin Zaid, the (Companion who was) dearly loved by the Messenger of Allah (ﷺ)." So Usamah (May Allah be pleased with him) spoke to him and the Messenger of Allah (ﷺ) (angrily) said, "Are you interceding regarding one of the punishments prescribed by Allah?" He then got up and delivered an address in which he said, "Indeed what destroyed the people before you was just that when a person of high rank among them committed a theft, they spared him; but if the same crime was done by a poor person they inflicted the prescribed punishment on him. I swear by Allah that if Fatimah daughter of Muhammad should steal, I would have her hand cut off.".In another narration ''Aishah (May Allah be pleased with her) said: (Upon hearing the intercession of Usamah), the face of the Messenger of Allah (ﷺ) changed color (because of anger) and he said, "Do you dare to intercede in matters prescribed by Allah?" Usamah pleaded: "O Messenger of Allah! Pray for my forgiveness." ''Aishah (May Allah be pleased with her) added: Thereafter the Messenger of Allah (ﷺ) gave orders to have that woman''s hand cut off.', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1770', 'Riyad as-Salihin 1770', 'ریاض الصالحین 1770', null, 'كانت امرأة من بني مخزوم تستعير المتاع من الناس احتيالاً، ثم تجحده.
فاستعارت مرةً حُلِيًا فجحدته، فوُجِدَ عندها، وبلغ أمرها النبي صلى الله عليه وسلم فعزم على تنفيذ حد الله تعالى بقطع يدها، وكانت ذات شرف، ومن أسرة عريقة في قريش.
فاهتمت قريش بها وبهذا الحكم الذي سينفذ فيها، وتشاوروا فيمن يجعلونه واسطة إلى النبي صلى الله عليه وسلم ليكلمه في خلاصها، فلم يروا أولى من أسامة بن زيد، فإنه المقرب المحبوب للنبي صلى الله عليه وسلم ، فكلمه أسامة.
فغضب منه صلى الله عليه وسلم وقال له - منكراً عليه: - "أتشفع في حدٍّ من حدود الله"؟
ثم قام خطيبا في الناس ليبين لهم خطورة مثل هذه الشفاعة التي تعطل بها حدود الله، ولأن الموضوع يهم الكثير منهم، فأخبرهم أن سبب هلاك من قبلنا في دينهم وفي دنياهم: أنهم يقيمون الحدود على الضعفاء والفقراء، ويتركون الأقوياء والأغنياء، فتعم فيهم الفوضى وينتشر الشر والفساد، فيحق عليهم غضب الله وعقابه.
ثم أقسم صلى الله عليه وسلم وهو الصادق المصدوق- لو وقع هذا الفعل من سيدة نساء العالمين ابنته فاطمة- أعاذها الله من ذلك- لنفذ فيها حكم الله تعالى صلى الله عليه وسلم .', 'امتِنَاعُ الشَّفَاعَةِ في الحَدِّ بَعْدَ بُلُوغِهِ السُّلْطان.
أَنَّ جَاحِدَ الْعَاريَة حُكْمُهِ حُكْمُ السَّارِقِ، فَيُقْطَع.
وجُوبُ الْعَدْلِ والْمُسَاوَاةِ بَيْنَ النَّاسِ، سَوَاءً مِنهم الغِني أو الفَقير، والشَّرِيف أو الوَضِيع، في الأحْكَامِ والحُدُودِ، وفيما هُمْ مُشْتَركُونُ فِيهِ.
أَنَّ إِقَامَةَ الحُدُودِ عَلَى الضُّعَفَاء وتَعْطِيلِها في حَقِّ الْأَقْوِيَاء سبب الهلاك والدَّمَار وشَقَاوَة الدَّارَيْن.
جَوَازُ الْمُبَالَغَةِ فِي الكلام، والتَّشبيهُ والتَّمْثيل، لِتَوضِيح الحقِّ وتَبيينه وتَأْكِيده.
مَنْقَبَةٌ كُبْرَى لِأَسَامة، إذ لم يروا أولى منه للشَّفاعة عند النبي -صلى الله عليه وسلم - وقَدْ وَقَعَتْ الحَادِثَة فِي فَتْحِ مَكَة.
عظيم منزلة فاطمة -رضي الله عنها- عند النبي -صلى الله عليه وسلم-.
تعظيم أمر المحاباة للأشراف في حقوق الله تعالى.
الاعتبار بأحوال من مضى من الأمم ولا سيما من خالف أمر الشارع.
دخول النساء مع الرجال في حد السرقة.', 'أَهَمَّهُمْ : جَلَب لهم هَمًّا.
الْمَخْزُومِيَّةِ : هي فاطمة بنت الأسود بن عبد الأسد، بنت أخي أبي سلمة، وبنو مخزوم أحد أفخاذ قريش، وهم من أشراف تلك القبيلة الشريفة فيسمونهم ريحانة قريش.
مَنْ يُكَلِّمُ؟ : أي مَنْ يَشْفَعُ فِيهَا بِتَرْكِ قَطْعِ يَدِهَا.
وَمَنْ يَجْتَرِئُ عَلَيْهِ إلاَّ أُسَامَةُ : ومَنْ يَسْتَطِيعُ أَنْ يُكَلِمه إِلَّا أُسَامَة
حِبُّ : أي مَحْبُوبِهِ.
فَاخْتَطَبَ : خَطَبَ النَّاس.
وَأَيْمُ الله : هذا يَمِينٌ وقَسَمٌ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/2955', false),
(21771, 2, 218, 1771, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "اتقوا اللاعنين" قالوا: وما اللاعنان؟ قال: "الذي يتخلى في طريق الناس أو في ظلهم".', 'The Messenger of Allah (ﷺ) said, "Avoid two habits which provoke cursing." The Companions said: "What are those things which provoke cursing?" He said, "Relieving on the thoroughfares or under the shades where people take shelter and rest.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1771', 'Riyad as-Salihin 1771', 'ریاض الصالحین 1771', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21772, 2, 218, 1772, 'hadith', 'عن جابر رضي الله عنه : أن رسول الله صلى الله عليه وسلم نهى أن يبال في الماء الراكد. رواه مسلم', 'The Messenger of Allah (ﷺ) forbade urinating into stagnant water..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', null, 'رياض الصالحين 1772', 'Riyad as-Salihin 1772', 'ریاض الصالحین 1772', null, null, null, null, 'sunnah.com', null, false, null, false),
(21773, 2, 218, 1773, 'hadith', 'عن النعمان بن بشير رضي الله عنهما أن أبًا له أتي به رسول الله صلى الله عليه وسلم فقال: إني نحلت ابني هذا غلامًا كان لي، فقال رسول الله صلى الله عليه وسلم : "أكل ولدك نحلته مثل هذا؟" فقال: لا، فقال رسول الله صلى الله عليه وسلم فأرجعه". وفي رواية: فقال رسول الله صلى الله عليه وسلم : "أفعلت هذا بولدك كلهم؟" قال: لا، قال: "اتقوا الله واعدلوا بين أولادكم" فرجع أبي، فرد تلك الصدقة. وفي رواية: فقال رسول الله صلى الله عليه وسلم : "يا بشير ألك ولد سوى هذا؟" قال: نعم، قال: "أكلهم وهبت له مثل هذا؟" قال: لا، قال: "فلا تشهدني إذًا فإني لا أشهد على جور" وفي رواية "لا تشهدني على جور" وفي رواية: "أشهد على هذا غيري" ثم قال: "أيسرك أن يكونوا إليك في البر سواء؟" قال" بلى، قال: "فلا إذًا".', 'My father took me to the Messenger of Allah (ﷺ) and said to him: "I have gifted one of my slaves to this son of mine." The Messenger of Allah (ﷺ) said, "Have you given such gift to every son of yours?" He replied, "No." Thereupon he said, "Take this gift back."Another narration is: The Messenger of Allah (ﷺ) said, "Be mindful of your obligation to Allah and do justice in respect of your children." My father came back and revoked his gift.Another narration is: The Messenger of Allah (ﷺ) asked, "Have you other children besides this one?" He said, "Yes." The Messenger of Allah (ﷺ) asked, "Have you awarded a gift like this to all of them." He said, "No." The Messenger of Allah (ﷺ) said, "I am not going to bear witness to this act of injustice."Another narration is: The Messenger of Allah (ﷺ) asked, "Do you not except goodness from all of them as you except from him?" He said, "Yes, of course." The Messenger of Allah (ﷺ) said, "Then don''t do this (i.e., do not give a gift to one son only).".', 'النعمان بن بشير رضي الله عنهما', 'An-Nu''man bin Bashir (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1773', 'Riyad as-Salihin 1773', 'ریاض الصالحین 1773', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21774, 2, 218, 1774, 'hadith', 'عن زينب بنت أبي سلمة رضي الله عنهما قالت: دخلت على أم حبيبة رضي الله عنه زوج النبي صلى الله عليه وسلم حين توفي أبوها أبو سفيان بن حرب رضي الله عنه، فدعت بطيب فيه صفرة خلوق أو غيره، فدهنت منه جارية، ثم مست بعارضيها. ثم قالت: والله مالي بالطيب من حاجة، غير أني سمعت رسول الله صلى الله عليه وسلم يقول على المنبر: "لا يحل لامرأة تؤمن بالله واليوم الآخر أن تحد على ميت فوق ثلاث ليال، إلا على زوج أربعة أشهر وعشرا" قالت زينب: ثم دخلت على زينب بنت جحش رضي الله عنها حين توفي أخوها، فدعت بطيب، فمست منه، ثم قالت: أما والله مالي بالطيب من حاجة، غير أني سمعت رسول الله صلى الله عليه وسلم يقول على المنبر: "لا يحل لامرأة تؤمن بالله واليوم الآخر أن تحد على ميت فوق ثلاث إلا على زوج أربعة أشهر وعشرًا".', 'I went to Umm Habibah (May Allah be pleased with her) the wife of the Prophet (ﷺ), when her father Abu Sufyan bin Harb (May Allah be pleased with him) died. Umm Habibah (May Allah be pleased with her) sent for a yellow coloured perfume or something else like it, and she applied it to a slave-girl and then rubbed it on her own cheeks and said: "By Allah, I have no need for perfume, I heard the Messenger of Allah (ﷺ) saying from the pulpit, ''It is not permissible for a woman who believes in Allah and the Last Day to mourn for the dead beyond three days, except for the death of her husband; in which case the period of mourning is of four months and ten days."'' Zainab said: I then visited Zainab, daughter of Jahsh (May Allah be pleased with her) when her brother died; she sent for perfume and applied it and then said: "Beware! By Allah, I don''t feel any need of perfume but I heard the Messenger of Allah (ﷺ) saying from the pulpit, ''It is not permissible for a woman who believes in Allah and the Last Day to mourn the dead beyond three days except in case of her husband (for whom the period is) four months and ten days."''', 'زينب بنت أبي سلمة رضي الله عنهما', 'Zainab bint Abu Salamah (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1774', 'Riyad as-Salihin 1774', 'ریاض الصالحین 1774', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21775, 2, 218, 1775, 'hadith', 'عن أنس رضي الله عنه قال: نهى رسول الله صلى الله عليه وسلم أن يبيع حاضر لباد وإن كان أخاه لأبيه وأمه.', 'The Messenger of Allah (ﷺ) forbade that a person in the city should make a deal on behalf of a villager on commission even if he is his real brother."', 'أنس رضي الله عنه', 'Anas bin Malik (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1775', 'Riyad as-Salihin 1775', 'ریاض الصالحین 1775', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21776, 2, 218, 1776, 'hadith', 'عن ابن عمر قال: قال رسول الله صلى الله عليه وسلم :«لا تتلقوا السلع حتى يهبط بها إلى الأسواق».', 'The Messenger of Allah (ﷺ) said, "Do not meet the merchandise till they arrive in the market.".', null, 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1776', 'Riyad as-Salihin 1776', 'ریاض الصالحین 1776', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21777, 2, 218, 1777, 'hadith', 'عن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «لا تتلقوا الركبان، ولا يبع حاضر لباد» فقال له طاوس: ما قوله: لا بيع حاضر لباد؟ قال: لا يكون له سمسارًا.', 'The Messenger of Allah (ﷺ) said, "The caravans carrying merchandise should not be met on the way to purchase from them; a man in the city should not sell for a man of the desert."Tawus asked him (Ibn ''Abbas): "What do these words really imply?" He said: "He should not work as an agent on his behalf.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1777', 'Riyad as-Salihin 1777', 'ریاض الصالحین 1777', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21778, 2, 218, 1778, 'hadith', 'عن أبي هريرة رضي الله عنه قال: نهى رسول الله صلى الله عليه وسلم أن يبيع حاضر لباد، ولا تناجشوا ولا يبيع الرجل على بيع أخيه، ولا يخطب على خطبة أخيه، ولا تسأل المرأة طلاق أختها لتكفأ ما في إنائها. وفي رواية قال: نهى رسول الله صلى الله عليه وسلم عن التلقي وأن يبتاع المهاجر للأعرابي، وأن تشترط المرأة طلاق أختها، وأن يستام الرجل على سوم أخيه، ونهى عن النجش والتصرية".', 'The Messenger of Allah (ﷺ) forbade that a man in the city should be the commission agent of a man from the desert and prohibited the practice of Najsh (i.e., offering a high price for something in order to allure another customer who is interested in the thing); and that a man should make an offer while the offer of his brother is pending; or that he should make a proposal of marriage while that of his brother is pending; or that a woman should try that a sister of hers might be divorced so that she might take her place.Another narration is: The Messenger of Allah (ﷺ) forbade the people from meeting the caravan on the way for entering into business transaction with them; and the selling of the goods by a dweller of the city on behalf of a man of the desert; and the seeking by a woman the divorce of her sister (from her husband); and the practice of Najsh and leaving the animals unmilked (for sometime for the purpose of accumulation of milk to deceive the buyer)..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1778', 'Riyad as-Salihin 1778', 'ریاض الصالحین 1778', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21779, 2, 218, 1779, 'hadith', 'عن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم قال: «لا يبع بعضكم على بيع بعض، ولا يخطب على خطبة أخيه إلا أن يأذن له».', 'The Messenger of Allah (ﷺ) said, "A person should not enter into a transaction when his (Muslim) brother has already negotiated, nor should he make a proposal of marriage when that of his brother is pending, except with the permission of the latter."', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1779', 'Riyad as-Salihin 1779', 'ریاض الصالحین 1779', 'متفق عليه، وهذا لفظ مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21780, 2, 218, 1780, 'hadith', 'عن عقبة بن عامر أن رسول الله صلى الله عليه وسلم قال: «المؤمن أخو المؤمن، فلا يحل لمؤمن أن يبتاع على بيع أخيه ولا يخطب على خطبة أخيه حتى يذر».', 'The Messenger of Allah (ﷺ) said, "A Mu''min is the brother of another Mu''min; and thus it is not permissible for a Mu''min to make an offer while the offer of his brother is pending, nor should he make a proposal of marriage while that of his brother is pending till he withdraws his proposal.".', null, '''Uqbah bin ''Amir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1780', 'Riyad as-Salihin 1780', 'ریاض الصالحین 1780', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21781, 2, 218, 1781, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إن الله تعالى يرضى لكم ثلاثا، ويكره لكم ثلاثًا: فيرضى لكم أن تعبدوه، ولا تشركوا به شيئًا، وأن تعتصموا بحبل الله جميعًا ولا تفرقوا، ويكره لكم: قيل وقال، وكثرة السؤال، وإضاعة المال».', 'The Messenger of Allah (ﷺ) said, "Verily, Allah likes three things for you and disapproves three things for you. He likes that you should worship Him Alone, not to associate anything with Him (in worship) and to hold fast to the Rope of Allah and not to be divided among yourselves; and He disapproves for you irrelevant talk, persistent questioning and the squandering of the wealth.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1781', 'Riyad as-Salihin 1781', 'ریاض الصالحین 1781', 'رواه مسلم، وتقدم شرحه', 'أخبر النبي صلى الله عليه وسلم أن الله يحب من عباده ثلاث خصال، ويكره منهم ثلاثًا، فيحب منهم: 

أن يوحدوه ولا يشركوا به شيئًا، وأن يعتصموا بعهد الله والقرآن وسنة نبيه جميعًا، ولا يتفرقوا عن جماعة المسلمين. 

ويكره لهم: اللغو وفضول الكلام فيما لا يعنيهم، والسؤال عما لم يقع، أو سؤال الناس أموالهم، وما في أيديهم، وما لم تدعو إليه حاجة، وإضاعة المال وصرفه في غير وجوهه الشرعية، وتعريضه للتلف.', 'يحب الله تعالى من عباده الإخلاص في عبادته، ويبغض الكفر به.
الحض على الاعتصام والتمسك بحبل الله تعالى؛ لما فيه من اجتماع وائتلاف.
الحث على الجماعة، والأمر بلزومها وتوحيد صفوفها، والنهي عن ضدها من التفرق والاختلاف.
النهي عن كثرة الكلام بما لا يعني؛ لأنه إن كان مباحًا ففيه إضاعة الوقت، وإن كان حرامًا ففيه كثرة المآثم.
ترك الخوض في أخبار الناس وتتبع أحوالهم وحكاية أقوالهم وأفعالهم.
النهي عن كثرة السؤال لأموال الناس.
تحريم إضاعة المال، والحث على المحافظة عليه فيما ينفع.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66236', false),
(21782, 2, 218, 1782, 'hadith', 'عن وراد كاتب المغيرة شعبة قال: أملى على المغيرة بن شعبة في كتاب إلى معاوية رضي الله عنه ، أن النبي صلى الله عليه وسلم أن يقول في دبر كل صلاة مكتوبة: "لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد" وكتب إليه أنه "كان ينهى عن قيل وقال، وإضاعة المال، وكثرة السؤال، وكان ينهى عن عقوق الأمهات، ووأد البنات، ومنع وهات".', 'Al-Mughirah bin Shu''bah dictated a letter to me addressed to Mu''awiyah (May Allah be pleased with him) that the Prophet (ﷺ) used to supplicate at the end of each obligatory Salat (prescribed prayer): "La ilaha illallahu, wahadahu la sharika lahu, lahul-mulku, wa lahul-hamdu, wa Huwa ''ala kulli shai''in Qadir. Allahumma la mani''a lima a''taita, wa la mu''tiya lima mana''ta, wa la yanfa''u dhal-jaddi mink-al-jaddu. (There is no true god except Allah, the One, Who has no partner. His is the sovereignty and His is the praise, and He is Able to do everything. O Allah! Nobody can withhold what You give; and nobody can give what You withhold; and the high status of a person is of no avail against Your Will)." He also wrote to him that the Prophet (ﷺ) used to forbid irrelevant talk, wasteful expenditure, persistent questioning, disobedience of parents (especially mothers), infanticide of daughters by burying them alive, depriving others of their rights and acquisition of property wrongfully..', 'وراد كاتب المغيرة شعبة قال: أملى على المغيرة بن شعبة في كتاب إلى معاوية رضي الله عنه', 'Warrad, the scribe of Al-Mughirah bin Shu''bah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1782', 'Riyad as-Salihin 1782', 'ریاض الصالحین 1782', 'متفق عليه وسبق شرحه', 'كان النبيُّ صلى الله عليه وسلم يقول عَقِيب كلِّ صلاةِ فريضة: " لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ".

أي: أُقِرُّ واعترفُ بكلمة التَّوحيد لا إله إلا الله، فالعبادة الحَقَّة أُثْبِتُها لله، وأَنفيها عمّا سواه، فلا معبود بحق إلا الله، ومُقِرٌّ أنَّ المُلْك الحقيقيّ التام لله، وجميع حمد أهل السموات والأرض مُستَحقٌّ لله تعالى، حيث هو قادر على كل شيء، وما قدَّره الله مِن عطاءٍ أو منعٍ لا رادَّ له، وعنده لا ينفع ذا الغنى غِناه، إنما ينفعه العمل الصالح.', 'استحباب هذا الذكر عقيب الصلوات لما اشتمل عليه من ألفاظ التوحيد والحمد.
المبادرة إلى امتثال السنن، وإشاعتها.', 'أملى: ألقى علي لأكتب.
لا ينفع ذا الجد منك الجدّ: لا ينفع ذا الغنى منك غناه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65102', false),
(21783, 2, 218, 1783, 'hadith', 'عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: "لا يُشر أحدكم إلى أخيه بالسلاح، فإنه لا يدري لعل الشيطان ينزع في يده، فيقع في حفرة من النار" ((متفق عليه)). وفي رواية لمسلم قال: قال أبو القاسم صلى الله عليه وسلم : "من أشار إلى أخيه بحديدة، فإن الملائكة تلعنه، حتى ينزع وإن كان أخاه لأبيه وأمه". قوله صلى الله عليه وسلم : "ينزِع" ضبط بالعين المهملة مع كسر الزاي، وبالغين المعجمة مع فتحها، ومعناهما متقارب، ومعناه بالمهملة يرمي، وبالمعجمة أيضًا يرمي ويفسد، وأصل النزع الطعن والفساد.', 'The Messenger of Allah (ﷺ) said, "None of you should point at his brother with a weapon because he does not know that Satan may make it lose from his hand and, as a result, he may fall into a pit of Hell-fire (by accidentally killing him).".The narration in Muslim is: Abul-Qasim (i.e., the Messenger of Allah) (ﷺ) said, "He who points at his (Muslim) brother with a weapon is cursed by the angels even if the other person should be his real brother."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1783', 'Riyad as-Salihin 1783', 'ریاض الصالحین 1783', null, 'حذر النبي صلى الله عليه وسلم أن يشير المسلم على أخيه المسلم بأي نوع من أنواع السلاح، فإنه لا يعلم لعل الشيطان يحمله على تحريك السلاح في يده، فيقتل أخاه أو يؤذيه، فيقع في المعصية التي تفضي به إلى أن يقع في حفرة من النار.', 'بيان حرمة دم المسلم.
وجوب احترام المسلم والحذر من إيصال الشر إليه بالفعل أو القول، ومن ذلك الإشارة بالحديدة أو بالسلاح، ولو مازحًا؛ لأن الشيطان قد ينزغ بيده ويزين له ضرب أخيه، أو ينزع السلاح من يده فيقع من غير اختياره فيضر أخاه.
سد الذرائع بالنهي عما يفضي إلى المحظور.
الحرص على سلامة المجتمع وحفظ العلاقات بين الناس، وعدم تخويفهم وترويعهم ولو بالإشارة والتهديد.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66246', false),
(21784, 2, 218, 1784, 'hadith', 'عن جابر رضي الله عنه قال: «نهى رسول الله صلى الله عليه وسلم أن يتعاطى السيف مسلولا».', 'The Messenger of Allah (ﷺ) prohibited from presenting a drawn sword to another.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', 'حسن', 'رياض الصالحين 1784', 'Riyad as-Salihin 1784', 'ریاض الصالحین 1784', 'رواه أبو داود والترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21785, 2, 218, 1785, 'hadith', 'عن أبي الشعثاء قال: كنا قعودًا مع أبي هريرة رضي الله عنه في المسجد فأذن المؤذن، فقام رجل من المسجد يمشي، فأتبعه أبو هريرة بصره حتى خرج من المسجد فقال أبو هريرة: أما هذا فقد عصى أبا القاسم صلى الله عليه وسلم ".', 'We were sitting with Abu Hurairah (May Allah be pleased with him) in the mosque when the Mu''adhdhin proclaimed the Adhan. A man stood up in the mosque and started walking out. Abu Hurairah (May Allah be pleased with him) stared at him till he went out of the mosque. Upon this Abu Hurairah (May Allah be pleased with him) said: Indeed, this man has disobeyed Abul-Qasim (ﷺ)..', 'أبي الشعثاء قال: كنا قعودًا مع أبي هريرة رضي الله عنه', 'Abu Sha''tha'' said:', 'صحيح', 'رياض الصالحين 1785', 'Riyad as-Salihin 1785', 'ریاض الصالحین 1785', 'رواه مسلم', 'يذكر أبو الشعثاء أنهم كانوا قعودا مع أبي هريرة في المسجد، فأذن المؤذن، فإذا برجل بعد الأذان يمشي، فظل أبو هريرة رضي الله عنه ينظر إليه هل سيخرج من المسجد أم ماذا يريد؟ فلما تبين له أنه خرج، أخبر أنه بفعله هذا قد عصى النبي صلى الله عليه وسلم .', 'أهمية وفضل الجلوس في المسجد انتظاراً للصلاة.
تنبيه على عظم فضل صلاة الجماعة.
تحريم الخروج من المسجد بعد الأذان إلا لعذر، كمرض وحدث أو خرج لحاجة وسيرجع قريبًا.
من مهام الداعية الانتباه لأفعال المدعوين، والتنبيه على المخالفات الشرعية.', 'فأتبعه بصره : أي لاحقه  ببصره لينظر مراده.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5731', false),
(21786, 2, 218, 1786, 'hadith', 'عن أبي هريرة رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم : «من عرض عليه ريحان، فلا يرده، فإنه خفيف المحمل طيب الريح».', 'The Messenger of Allah (ﷺ) said, "He who is presented with a flower of sweet basil should not reject it, because it is light in weight and pleasant in odour.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1786', 'Riyad as-Salihin 1786', 'ریاض الصالحین 1786', 'رواه مسلم', 'من أُهدي إليه طيب أو عُرِض عليه التطيب به فينبغي قبوله، فإنه لا مشقة في حمله وكذلك ريحه طيب.', 'استحباب قبول هدية الريحان؛ فإنه لا تكثر المنة بأخذه، وقد جرت العادة بالتسامح في بذله.
ينبغي على المسلم أن يكون طيب الريح ويستعمل الطيب.
استحباب عرض المسلم على إخوانه الطيب ولاسيما عند حضور الجمع والجماعات.', 'ريحان : نبت له ريح طيب.
المحمل : الحمل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5732', false),
(21787, 2, 218, 1787, 'hadith', 'عن أنس بن مالك رضي الله عنه أن النبي صلى الله عليه وسلم كان لا يرد الطيب".', 'The Prophet (ﷺ) never refused a gift of perfume..', 'أنس بن مالك رضي الله عنه', 'Anas bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1787', 'Riyad as-Salihin 1787', 'ریاض الصالحین 1787', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21788, 2, 218, 1788, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه قال: سمع رسول الله صلى الله عليه وسلم رجلا يُثني على رجل ويُطريه في المدحة، فقال: «أهلكتم، أو قطعتم ظهر الرجل» ((متفق عليه)). (23).', 'The Prophet (ﷺ) heard a person lauding another person or praising him too much. Thereupon he said, "You killed the man," or he said, "You ruined the man.".', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1788', 'Riyad as-Salihin 1788', 'ریاض الصالحین 1788', null, 'سمع النبي صلى الله عليه وسلم رجلًا يصف رجلًا بالخير، ويبالغ جدًّا في وصفه بما ليس فيه من الصفات الحميدة، فنهاه النبي صلى الله عليه وسلم ، وأخبر أن هذا قد يكون سببا في هلكته؛ لأن ذلك يوجب أن هذا الممدوح يترفع ويتعالى.', 'المدح في الوجه مظنة الاغترار بالنفس والوقوع في العجب، وهذه الصفات مهلكة لدين العبد.
الحث على القصد وعدم مدح الشخص الشخص في وجهه إلا بالاعتدلال، وعدم التملق وتحري الحق.
تفقد أحوال الناس، وتصحيح الأخطاء، وبيان الصواب في المدح.
اتباع هدي النبي -صلى الله عليه وسلم- في مدح الشخص.
استشعار أمانة الكلمة وترك مدح غير المستحقين له.', 'يثني على رجل : أي: يصفه بالخير.
يطريه : الإطراء: المبالغة في المدح.
المدحة : اسم هيئة، والمدح: الثناء على الشخص بما له من الصفات.
قطعتم ظهر الرجل : كناية عن إيقاعه في الهلكة، لما يحمله ذلك على العجب المهلك لصاحبه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5734', false),
(21789, 2, 218, 1789, 'hadith', 'عن أبي بكر رضي الله عنه أن رجلا ذُكر عند النبي صلى الله عليه وسلم ، فأثنى عليه رجل خيرًا، فقال النبي صلى الله عليه وسلم : "ويحك! قطعت عنق صاحبك" يقوله مرارًا "وإن كان أحدكم مادحًا لا محالة، فليقل: أحسب كذا وكذا إن كان يرى أنه كذلك وحسيبه الله، ولا يزكي على الله أحدًا".', 'Mention of a man was made to the Prophet (ﷺ) and someone praised him whereupon he (ﷺ) said, "Woe be to you! You have broken the neck of your friend!" He repeated this several times and added, "If one of you has to praise his friend at all, he should say: ''I reckon him to be such and such and Allah knows him well'', if you think him to be so-and-so, you will be accountable to Allah because no one can testify the purity of others against Allah.".', 'أبي بكر رضي الله عنه', 'Abu Bakrah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1789', 'Riyad as-Salihin 1789', 'ریاض الصالحین 1789', 'متفق عليه', 'في الحديث توجيهات السنة المباركة؛ فالمسلم يبعد عن المبالغة في الثناء، فالغرور والعجب أحد مداخل الشيطان، والمبالغة في الثناء والمدح تغمر الممدوح بالغرور والتكبر فيهلك، فيعتدل المسلم في ثنائه ومدحه ويكل أمر الناس لله سبحانه العالم بخفايا النفوس.', 'من كان مادحاً لا محالة فليوكل حال الممدوح في النهاية إلى الله فهو حسيبه وأعلم بحاله.
الثناء على العبد ينبغي أن يكون على سبيل حسن الظن به وليس على سبيل الجزم والقطع.
النهي عن الجزم في المدح والقطع بمصائر العباد، وكذلك مدحهم جزافاً بما ليس فيهم.', 'ويحك : كلمة تقال للترحم لمن وقع منه أمر لا يستحقه.
لا محالة : لا بدَّ، ولا حيلة له في ترك ذلك.
أحسبه : أظنه.
لا يزكي : لا يقطع بزكاة وطهارة أحد من العيوب.
وحسيبه الله : محاسبه على عمله.
قطعت عنق صاحبك : أهلكتموه، وهو استعارة من قطع العنق لاشتراكهما في الهلاك.
يقوله مرارًا : أي هذه الكلمة المأتي بها، والتكرير للمبالغة في الزجر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5735', false),
(21790, 2, 218, 1790, 'hadith', 'عن همام بن الحارث، عن المقداد، رضي الله عنه أم رجلا جعل يمدح عثمان رضي الله عنه ، فعمد المقداد، فجثا على ركبتيه، فجعل يحثو في وجهه الحصباء، فقال له عثمان: ما شأنك؟ فقال: إن رسول الله صلى الله عليه وسلم قال: "إذا رأيتم المادحين، فاحثوا في وجوههم التراب" ((رواه مسلم)). فهذه الأحاديث في النهي، وجاء في الإباحة أحاديث كثيرة صحيحة. قال العلماء: وطريق الجمع بين الأحاديث أن يقال: إن كان الممدوح عنده كمال إيمان ويقين، ورياضة نفس، ومعرفة تامة بحيث لا يفتن، ولا يغتر بذلك، ولا تلعب به نفسه، فليس بحرام ولا مكروه، وإن خيف عليه شيء من هذه الأمور، كره مدحه في وجهه كراهة شديدة، وعلى هذا التفصيل تنزل الأحاديث المختلفة في ذلك. ومما جاء في الإباحة قوله صلى الله عليه وسلم لأبي بكر رضي الله عنه: "أرجو أن تكون منهم" أي من الذين يُدعون من جميع أبواب الجنة لدخولها، وفي الحديث الآخر: "لست منهم" أي: لست من الذين يُسبلون أُزرهم خيلاء. وقال صلى الله عليه وسلم لعمر رضي الله عنه: "ما رآك الشيطان سالكًا فجًا إلا سلك فجًا غير فجك" والأحاديث في الإباحة كثيرة، وقد ذكرت جملة من أطرافها في كتاب: "الأذكار".', 'A person began to praise ''Uthman (May Allah be pleased with him), and Al-Miqdad (May Allah be pleased with him) sat upon his knees and began to throw pebbles upon the flatterer''s face. ''Uthman (May Allah be pleased with him) said: "What is the matter with you?" He said: "Verily, the Messenger of Allah (ﷺ) said, ''When you see those who shower undue praises upon others throw dust upon their faces."''.', 'همام بن الحارث، عن المقداد رضي الله عنه', 'Hammam bin Al- Harith (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1790', 'Riyad as-Salihin 1790', 'ریاض الصالحین 1790', null, 'عن المقداد رضي الله عنه أن رجلا امتدح عثمان رضي الله عنه فجلس المقداد على ركبتيه وأخذ صغير الحصى ورماها في وجه هذا المادح، فسأله عثمان لماذا فعل ذلك، فأخبر أن النبي صلى الله عليه وسلم أمرنا إذا رأينا المداحين أن نرمي في وجوههم التراب.', 'لا يجوز الإصغاء لأقوال المداحين وعدم مكافأتهم على مدحهم إلا بحثو الحصباء في وجوههم.
سرعة استجابة الصحابة لرسول الله -صلى الله عليه وسلم-، وتطبيق سنته.
السنة قد تخفى على كبار الصحابة -رضي الله عنهم-.
الأصل في الأدلة الشرعية العمل بظاهرها الذي يقتضيه لسان العرب، كما هو فهم المقداد للحديث وإقرار عثمان -رضي الله عنهم-.', 'عمد : قصد.
جثا : جلس على ركبتيه وهي جلسة المستوفز.
يحثو : يرمي.
الحصباء : صغار الحصى.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5736', false),
(21791, 2, 218, 1791, 'hadith', 'عن ابن عباس رضي الله عنه أن عمر بن الخطاب رضي الله عنه خرج إلى الشام حتى إذا كان بسرغ لقيه أمراء الأجناد -أبو عبيدة بن الجراح وأصحابه- فأخبروه أن الوباء قد وقع بالشام، قال بن عباس: فقال عمر: ادع لي المهاجرين الأولين، فدعوتهم، فاستشارهم، وأخبرهم أن الوباء قد وقع بالشام، فاختلفوا، فقال بعضهم: خرجت لأمر، ولا نرى أن ترجع عنه. وقال بعضهم: معك بقية الناس وأصحاب رسول الله صلى الله عليه وسلم ، ولا نرى أن تقدمهم على هذا الوباء. فقال: ارتفعوا عني، ثم قال: ادع لي الأنصار، فدعوتهم، فاستشارهم، فسلكوا سبيل المهاجرين، واختلفوا كاختلافهم، فقال: ارتفعوا عني، ثم قال: ادع لي من كان ها هنا من مشيخة قريش من مهاجرة الفتح، فدعوتهم، فلم يختلف عليه منهم رجلان، فقالوا: نرى أن ترجع بالناس، ولا تقدمهم على هذا الوباء، فنادى عمر رضي الله عنه في الناس: إني مصبح على ظهر، فأصبحوا عليه فقال أبو عبيدة بن الجراح رضي الله عنه : أفرار من قدر الله؟ فقال عمر رضي الله عنه : لو غيرك قالها يا أبا عبيدة! -وكان عمر يكره خلافه- نعم نفر من قدر الله إلى قدر الله، أرأيت لو كان لك إبل، فهبطت وادياً له عدوتان، إحداهما خصبة، والأخرى جدبة، أليس إن رعيت الخصبة رعيتها بقدر الله، وإن رعيت الجدبة رعيتها بقدر الله؟ قال: فجاء عبد الرحمن بن عوف رضي الله عنه ، وكان متغيباً في بعض حاجته، فقال: إن عندي من هذا علما، سمعت رسول الله صلى الله عليه وسلم يقول: «إذا سمعتم به بأرض، فلا تقدموا عليه، وإذا وقع بأرض وأنتم بها، فلا تخرجوا فرارا منه» فحمد الله تعالى عمر رضي الله عنه وانصرف. ((متفق عليه)). والعدوة: جانب الوادي.', '''Umar bin Al- Khattab (May Allah be pleased with him) set out for Ash-Sham (the region comprising Syria, Palestine, Lebanon and Jordan). As he reached at Sargh (a town by the side of Hijaz) he came across the governor of Al-Ajnad, Abu ''Ubaidah bin Al-Jarrah (May Allah be pleased with him) and his companions. They informed him that an   had broken out in Syria. Ibn ''Abbas relates: ''Umar (May Allah be pleased with him) said to me: "Call to me the earliest Muhajirun (Emigrants)." So I called them. He sought their advice and told them that an epidemic had broken out in Ash-Sham. There was a difference of opinion whether they should proceed further or retreat to their homes in such a situation. Some of them said: "You have set forth to fight the enemy, and therefore you should not go back;" whereas some of them said: "As you have along with you many eminent Companions of Messenger of Allah (ﷺ), we would not advice you to set forth to the place of the plague (and thus expose them deliberately to a danger)." ''Umar (May Allah be pleased with him) said: "You can now go away." He said: "Call to me the Ansar (the Helpers)." So I called them to him, and he consulted them and they differed in their opinions as well. He said: "Now, you may go." He again said: "Call the old (wise people) of the Quraish who had emigrated before the conquest of Makkah." I called them. ''Umar (May Allah be pleased with him) consulted them in this issue and not even two persons among them differed in the opinions. They said: "We think that you should go back along with the people and do not take them to this scourge. ''Umar (May Allah be pleased with him) made an announcement to the people, saying: "In the morning I intend to go back, and I want you to do the same." Abu ''Ubaidah bin Al-Jarrah (May Allah be pleased with him) said: "Are you going to run away from the Divine Decree?" Thereupon ''Umar (May Allah be pleased with him) said: "O Abu ''Ubaidah ! Had it been someone else to say this." (''Umar (May Allah be pleased with him) did not like to differ with him). He said: "Yes, we are running from the Divine Decree to the Divine Decree. What do you think if you have camels and you happen to get down a valley having two sides, one of them covered with foliage and the other being barren, will you not act according to the Divine Decree if you graze them in vegetative land? In case you graze them in the barren land, even then you will be doing so according to the Divine Decree.There happened to come ''Abdur-Rahman bin ''Auf who had been absent for some of his needs. He said: I have knowledge about it. I heard the Messenger of Allah (ﷺ) saying, "If you get wind of the outbreak of plague in a land, you should not enter it; but if it spreads in the land where you are, you should not depart from it." Thereupon ''Umar bin Khattab (May Allah be pleased with him) praised Allah and went back..', 'ابن عباس رضي الله عنه', 'Ibn ''Abbas (May Allah be pleased with them)', null, 'رياض الصالحين 1791', 'Riyad as-Salihin 1791', 'ریاض الصالحین 1791', null, null, null, null, 'sunnah.com', null, false, null, false),
(21792, 2, 218, 1792, 'hadith', 'عن أسامة بن زيد رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إذا سمعتم الطاعون بأرض، فلا تدخلوها، وإذا وقع بأرض، وأنتم فيها، فلا تخرجوا منها».', 'The Prophet (ﷺ) said, "If you get wind of the outbreak of plague in a land, do not enter it; and if it breaks out in a land in which you are, do not leave it.".', 'أسامة بن زيد رضي الله عنه', 'Usamah bin Zaid (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1792', 'Riyad as-Salihin 1792', 'ریاض الصالحین 1792', 'متفق عليه', 'إذا نزل وباء بأرض لم يدخلها الإنسان فلا يجوز له دخولها حفاظاً على صحته وصحة غيره، وإذا دخل المرض في أرض هو فيها لم يجز له الخروج وعليه أن يصبر على قدر الله ليكتب له الأجر.', 'إذا وقع الوباء في الأرض فإنه لا يجوز للإنسان أن يخرج منها فرارا منه وأما إذا خرج لحاجة فلا بأس.
الإسلام وضع قواعد الحَجْر الصحي، فمنع الدخول على الوباء والفرار منه.
إثبات العدوى وانتشار المرض بإذن الله لا بذاته، فليس الأمر كما يعتقد بعض الناس أن العدوى وهي انتقال المرض تحصل بقوتها دون إرادة الله -تعالى-.', 'الطاعون : هو مرض عام ووباء سريع الانتشار تفسد به الأمزجة والأبدان.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5737', false),
(21793, 2, 218, 1793, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: "أجتنبوا السبع الموبقات" قالوا: يا رسول الله وما هن؟ قال: "الشرك بالله، والسحر، وقتل النفس التى حرم الله إلا بالحق، وأكل الربا، وأكل مال اليتيم، والتولي يوم الزحف، وقذف المحصنات الغافلات".', 'The Prophet (ﷺ) said, "Avoid the seven destructive things." It was asked: (by those present): "What are they, O Messenger of Allah?" He replied, "Associating anyone or anything with Allah in worship; practising sorcery, killing of someone without a just cause whom Allah has forbidden, devouring the property of an orphan, eating of usury, fleeing from the battlefield and slandering chaste women who never even think of anything touching chastity and are good believers.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1793', 'Riyad as-Salihin 1793', 'ریاض الصالحین 1793', 'متفق عليه', 'يأمرُ رسولُ الله صلى الله عليه وسلم أمَّتَه بالابتعاد عن سبع جرائم ومَعاصٍ مهلكاتٍ، ولما سُئل عنها: ما هي؟ بيّنها بأنها:

 أولًا: الشرك بالله، باتخاذ النظير والمثيل له سبحانه من أي شكل كان، وصَرْف أي عبادة من العبادات لغير الله تعالى، وبدأ بالشرك؛ لأنه أعظم الذنوب.

ثانيًا: السحر -وهو عبارة عن عُقََد ورُقَى وأدوية وتدخينات-، يؤثِّر في بَدَن المسحور بالقتل أو بالمرض، أو يفرِّق بين الزوجين، وهو عمل شيطاني، وكثير منه لا يُتَوَصَّل إليه إلا بالشرك والتقرّب إلى الأرواح الخبيثة بشيء مما تحب.

ثالثًا: قتل النفس التي منع الله من قتلها إلا بمسوِّغٍ شرعي يُنفِّذُه الحاكم.

رابعًا: تناول الربا بأكلٍ أو بغيره من وجوه الانتفاع.

خامسًا: التعدِّي على مال الصغير الذي مات أبوه وهو دون البلوغ.

سادسًا: الفرار من المعركة مع الكفار.

سابعًا: اتهام الحرائر العفيفات بالزنا، وكذلك اتهام الرجال.', 'الكبائر ليست محصورة في سبع، وتخصيص هذه السبع لِعِظَمِها وخطرِها.
جواز قتل النفس إذا كان بحقٍّ، كالقصاص والردة والزنا بعد إحصان، وينفِّذه الحاكم الشرعي.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3331', false),
(21794, 2, 218, 1794, 'hadith', 'عن ابن عمر رضي الله عنهما قال: «نهى رسول الله صلى الله عليه وسلم أن يسافر بالقرآن إلى أرض العدو».', 'The Messenger of Allah (ﷺ) forbade travelling to the land of the enemy carrying the Qur''an..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1794', 'Riyad as-Salihin 1794', 'ریاض الصالحین 1794', 'متفق عليه', 'نهى النبي صلى الله عليه وسلم عن أخذ القرآن والسفر به إلى بلاد الكفر الذين لا يدينون بالاسلام فيكون عرضة للامتهان هناك، وإذا غلب على الظن السلامة من ذلك جاز.', 'وجوب تعظيم كتاب الله وعدم تعريضه لأماكن التهلكة والاستهانة.
تحريم السفر بالقرآن إلى بلاد الأعداء إذا خيف أو غلب على الظن وقوعه في أيديهم، وذلك لئلا يتمكنوا من القرآن فيهينوه، ويجوز حمله إلى بلادهم؛ للبلاغ وإقامة الحجة عليهم، وللتحفظ والتفهم لأحكامه عند الحاجة إذا كان للمسلمين قوة أو سلطان أو ما يقوم مقامهما من العهود والمواثيق ونحو ذلك مما يكفل حفظه ويرجى معه التمكن من الانتفاع به في البلاغ والحفظ والدراسة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5738', false),
(21795, 2, 218, 1795, 'hadith', 'عن أم سلمة رضي الله عنها أن رسول الله صلى الله عليه وسلم قال: "الذي يشرب في آنية الفضة إنما يجرجر في بطنه نار جهنم" ((متفق عليه)). وفي رواية لمسلم: "أن الذي يأكل أو يشرب في آنية الفضة والذهب"', 'The Messenger of Allah (ﷺ) said, "Whosoever drinks in utensils of silver, in fact, kindles in his belly the fire of Hell.".The narration of Muslim is: "Verily, the person who eats or drinks in utensils made of gold and silver."', 'أم سلمة رضي الله عنها', 'Umm Salamah (May Allah be pleased with her) said:', null, 'رياض الصالحين 1795', 'Riyad as-Salihin 1795', 'ریاض الصالحین 1795', null, null, null, null, 'sunnah.com', null, false, null, false),
(21796, 2, 218, 1796, 'hadith', 'عن حذيفة رضي الله عنه، قال: إن النبي صلى الله عليه وسلم نهانا عن الحرير، والديباج والشرب في آنية الذهب والفضة، وقال: "هن لهم في الدنيا وهم لكم في الاخرة" ((متفق عليه)). وفي رواية في الصحيحين عن حذيفة رضي الله عنه، قال: سمعت رسول الله صلى الله عليه وسلم يقول: "لا تلبسوا الحرير ولا الديباج، ولا تشربوا في آنية الذهب والفضة ولا تأكلوا في صحافها".', 'The Prophet (ﷺ) prohibited us from wearing silk or Dibaj and from drinking out of gold and silver vessels and said, "These are meant for them (non- Muslims) in this world and for you in the Hereafter."In another narration Hudhaifah (May Allah be pleased with him) said: The Messenger of Allah (ﷺ) said, "Do not wear silk and Dibaj, nor eat or drink from utensils made of gold and silver.".', 'حذيفة رضي الله عنه', 'Hudhaifah (May Allah be pleased with him)', null, 'رياض الصالحين 1796', 'Riyad as-Salihin 1796', 'ریاض الصالحین 1796', null, null, null, null, 'sunnah.com', null, false, null, false),
(21797, 2, 218, 1797, 'hadith', 'عن أنس بن سيرين قال: كنت مع أنس بن مالك رضي الله عنه عند نفر من المجوس، فجيء بفالوذج على إناء من فضة، فلم يأكله، فقيل له: حوله، فحوله على إناء من خلنج، وجيء به فأكله. ((رواه البيهقي بإسناد حسن)).الخلنج الجفنة', 'I was with Anas bin Malik (May Allah be pleased with him) in the company of some Magians when Faludhaj (a sweet made of flour and honey) was brought in a silver utensil, and Anas did not take it. The man was told to change the utensil. So he changed the utensil and when he brought it to Anas, he took it..', 'أنس بن سيرين قال: كنت مع أنس بن مالك رضي الله عنه', 'Anas bin Sirin (May Allah be pleased with him) said:', 'قال النووي: بإسناد حسن', 'رياض الصالحين 1797', 'Riyad as-Salihin 1797', 'ریاض الصالحین 1797', null, 'كان أنس بن مالك رضي الله عنه عند قوم من المجوس فجيء له بنوع من الحلوى اسمه الفالوذج على إناء من فضة فلم يأكله، فحولوه له على إناء من خشب فأكله.', 'الطعام الحلال الموضوع في صحاف الذهب والفضة لا يحرم بذاته وإنما يحرم الأكل فيها، فإذا حول إلى آنية أخرى؛ فلا بأس به.
من دعي إلى طعام في آنية منهي عنها؛ فلا يجوز له الأكل حتى يوضع في إناء غيره.
المسلم إذا علم حكما شرعيا انقاد له وطبقه.
الابتعاد عن الترفه والتشبه بالكفار في المأكل والمشرب والملبس.', 'فالوذج. : نوع من الحلوى.
خلنج : شجرة بين صفرة وحمرة تتخذ من خشبة الأواني.
نفر. : اسم يقع على جماعة من الرجال خاصة ما بين الثلاثة إلى العشرة.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6372', false),
(21798, 2, 218, 1798, 'hadith', 'عن أنس رضي الله عنه قال: نهى النبي صلى الله عليه وسلم أن يتزعفر الرجل.', 'The Prophet (ﷺ) prohibited men from wearing saffron-dyed clothes..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1798', 'Riyad as-Salihin 1798', 'ریاض الصالحین 1798', 'متفق عليه', 'نهى النبي صلى الله عليه وسلم أن يصبغ الرجل جسده أو ثيابه بالزعفران، وكان ذلك من طيب النساء، فنهي الرجال عن ذلك منعًا من التشبه.', 'النهي عن لبس الثياب المزعفرة.
النهي خاص بالرجال؛ لأنَّ الثياب المصبوغة بذلك مما يتزين به النساء.
تحريم تشبه الرجال بالنساء في اللباس.', 'يتزعفر : يصبغ ثوبه، أو يطلي جسمه بالزعفران.
الزعفران : نبت ذو لون أصفر أو أحمر يصبغ به.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6373', false),
(21799, 2, 218, 1799, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنه قال: رأى النبي صلى الله عليه وسلم علي ثوبين معصفرين فقال: "أمك أمرتك بهذا؟" قلت: أغسلهما؟ قال: "بل احرقهما". وفي رواية فقال: "إن هذا من ثياب الكفار فلا تلبسها".', 'The Prophet (ﷺ) saw me dressed in two saffron-coloured garments and asked, "Has your mother commanded you to wear these?" I asked him, "Shall I wash them out?" He replied, "You had better set them to fire."Another narration is: "These are garments of the disbelievers. So do not wear them.".', 'عبد الله بن عمرو بن العاص رضي الله عنه', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1799', 'Riyad as-Salihin 1799', 'ریاض الصالحین 1799', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21800, 2, 218, 1800, 'hadith', 'عن عليّ رضي الله عنه قال: حفظت عن رسول الله صلى الله عليه وسلم : «لا يتم بعد احتلام، ولا صمات يوم إلى الليل». قال الخطابي في تفسير هذا الحديث: كان من نسك الجاهلية الصمات، فنهوا في الإسلام عن ذلك، وأمروا بالذكر والحديث بالخير.', 'I have retained in my memory the saying of the Messenger of Allah (ﷺ) that: "No one is considered an orphan after he has attained the age of maturity; and it is unlawful to remain silent from dawn till night.".', 'عليّ رضي الله عنه', '''Ali (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1800', 'Riyad as-Salihin 1800', 'ریاض الصالحین 1800', null, 'أولًا: لا يعتبر الشخص يتيمًا إذا بلغ.
ثانيًا: كانوا في الجاهلية يدينون لله عز وجل بالصمت، فيظل يومه ساكتًا ولا يتكلم حتى تغيب الشمس، فنهى المسلمون عن ذلك؛ لأن هذا يؤدي إلى ترك التسبيح والتهليل والتحميد والأمر بالمعروف والنهي عن المنكر وقراءة القرآن وغير ذلك، وأيضا هو من فعل الجاهلية فلذلك نهي عنه.', 'وجوب مخالفة أعمال الجاهلية وأحوالها.
ارتفاع اسم اليتيم عن البالغ، ويقتضي ذلك ارتفاع أحكامه.
ليس من شعائر الدين التعبد بالصمت والإمساك عن الكلام فإنه حرام.', 'يتم : الانفراد، واليتيم من مات أبوه وهو صغير دون البلوغ.
احتلام : بلوغ.
صمات : سكوت يوم إلى الليل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6374', false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21801, 2, 218, 1801, 'hadith', 'عن قيس بن أبي حازم قال: دخل أبو بكر الصديق رضي الله عنه على امرأة من أحمس يقال لها: زينب، فرأها لا تتكلم. فقال: ما لها لا تتكلم؟ فقالوا: حجت مصمته، فقال لها: تكلمي فإن هذا لا يحل، هذا من عمل الجاهلية! فتكلمت. رواه البخاري', 'Abu Bakr (May Allah be pleased with him) came upon a woman named Zainab from the Ahmas tribe and noticed that she was observing total silence. He said: "What has happened to her? Why does she not speak?'''' People informed him that she had sworn to remain silent. He then said to her: "You should speak, it is not permissible (to observe silence), for it is an act of the Days of Ignorance (Jahiliyyah)." (After hearing this) she started speaking.', 'قيس بن أبي حازم قال: دخل أبو بكر الصديق رضي الله عنه', 'Qais bin Abu Hazim (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1801', 'Riyad as-Salihin 1801', 'ریاض الصالحین 1801', null, 'دخل أبو بكر رضي الله عنه على امرأة من قبيلة أحمس اسمها زينب، فوجدها لا تتكلم، فسألهم: لماذا لا تتكلم، فقالوا: حجت ساكتة، فقال لها: تكلمي، فإن ترك الكلام بالكلية لا يجوز؛ فإنه كان من عبادات الجاهلية ثم حرمه الإسلام، ودخول الرجل على المرأة من غير ريبة ولا خلوة كما فعل الصديق رضي الله عنه جائز.', 'المستحب التكلم بالخير من أمر بمعروف أو نهي عن منكر أو إفشاء السلام أو تعليم الناس، وإلا، فلا.
من حلف ألا يتكلم يستحب له الكلام ولا كفارة عليه.
وجوب مخالفة أعمال الجاهلية وأحوالها.
ليس من شعائر الدين التعبد بالصمت والإمساك عن الكلام فإنه حرام.', 'من عمل : من عبادتهم التي يزعمون أنها تقربهم إلى الله -تعالى-.
أحمس : قبيلة من قريش، وسموا حمسا لأنهم تحمسوا في دينهم أي : تشددوا.
مصمتة : ساكتة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6375', false),
(21802, 2, 218, 1802, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه أن النبي صلى الله عليه وسلم قال: «من ادعى إلى غير أبيه وهو يعلم أنه غير أبيه، فالجنة عليه حرام».', 'The Prophet (ﷺ) said, "He who (falsely) attributes his fatherhood to anyone besides his real father, knowing that he is not his father, will be forbidden to enter Jannah.".', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1802', 'Riyad as-Salihin 1802', 'ریاض الصالحین 1802', 'متفق عليه', 'ورد الحديث لبيان التحذير من أمر كان يفعله أهل الجاهلية وهو الانتساب إلى غير الوالد، فالإنسان يجب عليه أن ينتسب إلى أهله أبيه جده و جد أبيه، وما أشبه ذلك ولا يحل له أن ينتسب إلى غير أبيه وهو يعلم أنه ليس بأبيه، فمثلًا إذا كان أبوه من القبيلة الفلانية ورأى أن هذه القبيلة فيها نقص عن القبيلة الأخرى فانتمى إلى قبيلة ثانية أعلى حسبًا لأجل أن يزيل عن نفسه عيب قبيلته فإن هذا متوعد بالحرمان من الجنة.', 'تحريم الانتساب إلى غير الآباء مع العلم بهم.
حرص الإسلام على المحافظة على الأنساب.
وجوب بر الوالدين .', 'ادعى : انتسب كاذباً.
مواليه : معتقيه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6376', false),
(21803, 2, 218, 1803, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا ترغبوا عن آبائكم، فمن رغب عن أبيه، فهو كافر».', 'The Prophet (ﷺ) said, "Do not turn away from your fathers, for he who turns away from his father, will be guilty of committing an act of disbelief."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1803', 'Riyad as-Salihin 1803', 'ریاض الصالحین 1803', 'متفق عليه', 'من رَغِبَ عن نسب أبيه عالمًا مختارًا، فهو كفر أصغر، وليس المراد حقيقة الكفر، الذي يخلد صاحبه في النار، بل هو كفر دون كفر، وهذا تأكيد وتشديد لتحريم هذا الفعل وتقبيحه.', 'تحريم الانتساب إلى غير الآباء مع العلم بهم.
حرص الإسلام على المحافظة على الأنساب.
وجوب بر الوالدين.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6377', false),
(21804, 2, 218, 1804, 'hadith', 'عن يزيد بن شريك بن طارق قال: رأيت عليا رضي الله عنه على المنبر يخطب، فسمعته يقول: لا والله ما عندنا من كتاب نقرؤه إلا كتاب الله، وما في هذه الصحيفة، فنشرها فإذا فيها أسنان الإبل، وأشياء من الجراحات، وفيها: قال رسول الله صلى الله عليه وسلم : "المدينة حرم ما بين عير إلى ثور، فمن أحدث فيها حدثاً، أو آوى محدثاً، فعليه لعنة الله والملائكة والناس أجمعين، لا يقبل الله منه يوم القيامة صرفاً ولا عدلاً، ذمة المسلمين واحدة، يسعى بها أدناهم، فمن أخفر مسلماً، فعليه لعنة الله والملائكة والناس أجمعين، لا يقبل الله منه يوم القيامة صرفاً ولا عدلاً، ومن ادعى إلى غير أبيه، أو انتمى إلى غير مواليه، فعليه لعنة الله والملائكة والناس أجمعين، لا يقبل الله منه يوم القيامة صرفاً ولا عدلاً" ((متفق عليه)). "ذِمَّةُ المُسْلِمِينَ"أيْ: عَهْدُهُمْ وأمانتُهُم."وَأخْفَرَهُ": نَقَضَ عَهْدَهُ."والصَّرفُ": التَّوْبَةُ، وَقِيلَ: الحِيلَةُ."وَالْعَدْلُ": الفِدَاءُ.', 'I saw ''Ali (May Allah be pleased with him) giving a Khutbah (sermon) from the pulpit and I heard him saying: "By Allah, we have no book to read except Allah''s Book and what is written in this scroll. He unrolled the scroll which showed a list of what sort of camels to be given as blood-money, and other legal matters relating to killing game in the sanctuary of Makkah and the expiation thereof. In it was also written: The Messenger of Allah (ﷺ) said: ''Al-Madinah is a sanctuary from ''Air to Thaur (mountains). He who innovates in this territory new ideas in Islam, commits a sin therein, or shelters the innovators, will incur the Curse of Allah, the angels, and all the people, and Allah will accept from him neither repentance nor a ransom on the Day of Resurrection. The asylum (pledge of protection) granted by any Muslim (even of the) lowest status is to be honoured and respected by all other Muslims, and whoever betrays a Muslim in this respect (by violating the pledge) will incur the Curse of Allah, the angels, and all the people; and Allah will accept from him neither repentance nor a ransom on the Day of Resurrection. Whoever attributes his fatherhood to someone other than his (real) father, and takes someone else as his master other than his (real) master without his permission, will incur the Curse of Allah, the angels and all the people, and Allah will accept from him neither repentance nor a ransom on the Day of Resurrection.".', 'يزيد بن شريك بن طارق قال: رأيت عليا رضي الله عنه', 'Yazid bin Sharik bin Tariq (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1804', 'Riyad as-Salihin 1804', 'ریاض الصالحین 1804', null, 'قال علي رضي الله عنه وهو يخطب على المنبر: والله ليس عندنا كتاب نقرؤه غير كتاب الله عز وجل إلا هذا الكتاب، فبسطه فإذا فيها دية أسنان الإبل، ومسائل الجراحات وأحكامها، وفيها أخبر رسول الله صلى الله عليه وسلم أن المدينة حرام كمكة، ما بين جبل عير إلى جبل ثور، فمن ابتدع فيها بدعة في الدين أو تسبب لإِحداث أذى المسلمين من جرم أو ظلامة، أو آوى محدثا فعليه لعنة الله بمنعه له من الرحمة، وسؤال الملائكة والناس أجمعين ذلك من الله تعالى ، ولا يقبل الله منه يوم القيامة فريضة ولا نافلة ولا توبة ولا فداء.
وأن أمان المسلم للكافر صحيح بشروطه المعروفة، فإذا وجدت حرم التعرض له، فمن نقض أمان مسلم وتعرض للكافر الذي أمَّنه فعليه لعنة الله بمنعه له من الرحمة وسؤال الملائكة والناس أجمعين ذلك من الله تعالى ، ولا يقبل الله منه يوم القيامة فريضة ولا نافلة ولا توبة ولا فداء.
ومن انتسب إلى غير أبيه أو انتمى معتق إلى غير مواليه فعليه لعنة الله بمنعه له من الرحمة وسؤال الملائكة والناس أجمعين ذلك من الله تعالى، ولا يقبل الله منه يوم القيامة فريضة ولا نافلة ولا توبة ولا فداء؛ لما فيه من كفر النعمة، وتضييع حقوق الإِرث والولاء والعقل وغير ذلك، مع ما فيه من القطيعة والعقوق.', 'ذمة المسلمين سواء صدرت من واحد منهم أو أكثر شريف أو وضيع، فإذا أمن أحد من المسلمين كافراً وأعطاه ذمة لم يكن لأحد نقضه؛ لأن المسلمين كنفس واحدة.
تحريم نقض العهد وإخفار ذمة المسلم.
من نسب إلى غير من هو له كان كالدعي الذي تبرأ عمن هو منه، وألحق نفسه بغيره؛ فيستحق به الدعاء عليه بالطرد والإبعاد عن الرحمة.
المدينة حرم ما بين حرتيها وحماها كله؛ لا يختلي خلاها، ولا ينفر صيدها، ولا تلتقط لقطتها، ولا يقطع منها شجرة إلا أن يعلف رجل بعيره، ولا يحمل فيها سلاح لقتال.
تحريم إيواء أهل الجرائم وأهل البدع وتوقيرهم؛ لأن ذلك ثلم في الدين وتعظيم للفاسقين.
بيان شرف المدينة وفضلها ولذلك عظّم المعصية فيها.
جواز لعن أصحاب الكبائر من غير تعيين شخص.', 'عير : جبل صغير قرب المدينة.
ثور : جبل صغير وراء جبل أحد.
أحدث فيها حدثاً : ابتدع فيها بدعة أو فعل فيها جريمة أو فتنة للناس.
انتمى إلى غير مواليه : ادعى أنه عتيق غير من أعتقوه.
ذمة المسلمين : عهدهم وأمانتهم.
أخفر مسلمًا : نقض عهده.
صرف : الصرف التوبة، وقيل الحيلة.
عدل : العدل الفداء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6381', false),
(21805, 2, 218, 1805, 'hadith', 'عن أبي ذر رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول: «ليس من رجل ادعى لغير أبيه وهو يعلمه إلا كفر، ومن ادعى ما ليس له، فليس منا، وليتبوأ مقعده من النار، ومن دعا رجلاً بالكفر، أو قال: عدو الله، وليس كذلك إلا حار عليه».', 'I heard the Messenger of Allah (ﷺ) saying: "A person who attributes his fatherhood to anyone other than his real father, knowing that he is not his father, commits an act of disbelief. And he who makes a claim of anything which in fact does not belong to him, is none of us. He should make his abode in Hell, and he who labels anyone as disbeliever or calls him the enemy of Allah and he is in fact not so, his charge will revert to him.".', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1805', 'Riyad as-Salihin 1805', 'ریاض الصالحین 1805', 'متفق عليه وهذا لفظ رواية مسلم', 'في هذا الحديث وعيد شديد وإنذار أكيد، لمن ارتكب عملا من هذه الثلاثة، فما بالك بمن عملها كلها؟
أولها: أن يكون عالمًا أباه، مثبتًا نسبه فينكره ويتجاهله، مدّعيًا النسب إلى غير أبيه، أو إلى غير قبيلته.
وثانيها: أن يدعي "وهو عالم" ما ليس له من نسب، أو مال، أو حق من الحقوق، أو عمل من الأعمال، أو علم من العلوم، أو يزعم صفة فيه يستغلها ويصرف بها وجوه الناس إليه، وهو كاذب فهذا عذابه عظيم، إذ تبرأ منه النبي صلى الله عليه وسلم ، وأمره أن يختار له مقرا في النار؛ لأنه من أهلها.
وثالثها: أن يرمِىَ بريئا بالكفر، أو اليهودية، أو النصرانية، أو بأنه من أعداء الله.
فمثل هذا يرجع عليه ما قال؛ لأنه أحق بهذه الصفات القبيحة من المسلم الغافل عن أعمال السوء وأقواله.', 'فيه دليل على تحريم الانتفاء من نسبه المعروف، والانتساب إلى غيره، سواء أكان ذلك من أبيه القريب، أم من أجداده، ليخرج من قبيلته إلى قبيلة أخرى، لما يترتب عليه من المفاسد العظيمة، من ضياع الأنساب، واختلاط المحارم بغيرهم، وتقطع الأرحام، وغير ذلك.
اشترط العلم؛ لأن تباعد القرون، وتسلسل الأجداد، قد يوقع في الخلل والجهل، والله لا يكلف نفسًا إلا وُسْعَهَا، ولا يؤاخذ بالنسيان والخطأ.
قوله "ومن ادَّعى ما ليس له" يدخل فيه كل دعوى باطلة، من نسب، أو مال، أو علم، أو صنعة، أو غير ذلك.فكل شيء يدَّعيه، وهو كاذب، فالنبي -صلى الله عليه وسلم- برئ منه، وهو من أهل النار، فليختر مقامه فيها.كيف إذا أيد دعاويه الباطلة بالأيمان الكاذبة، ليأكل بها أموال الناس؟! فهذا ضرره عظيم وأمره كبير.
الوعيد الثالث فيمن أطلق الكفر، أو الفسق، أو نفى الإيمان، أو غير ذلك على غير مستحق، فهو أحق منه به؛ لأن هذا راجع عليه، فالجزاء من جنس العمل.
يؤخذ منه التنبه على تحريم تكفير الناس بغير مسوغ شرعي، وكفر بواح ظاهر.فإن التكفير والإخراج من الملة، أمر خطير، لا يقدم عليه إلا عن بصيرة، وتثبت، وعلم.
ليس معنى هذا أن من اشتهر بالنسبة إلى غير أبيه أن يدخل في الوعيد كالمقداد بن الأسود، وإنما المراد من تحول عن نسبه لأبيه إلى غير أبيه عالمًا عامدًا مختارًا.', 'ادعى : انتسب واعتزى.
وهو يعلمه : أتى بهذا الشرط لأن الأنساب قد تتراخى فيها مدد الآباء والأجداد ويتعذر العلم بحقيقتها، وقد يقع اختلال في النسب في الباطن من جهة النساء ولا يشعر به.
كفر : كفرًا مخرجًا عن الملة إذا استحل ذلك بعد معرفة النصوص، وكفر دون كفر إذا لم يستحله.
من ادعى ما ليس له : كائنًا ما كان علمًا أو تعليمًا أو صلاحًا أو حالًا أو مالًا أو نعمةً أو غير ذلك.
فليس منا : ليس على هدينا وطريقتنا.
وليتبوأ : فليتخذ له مباءة، وهي المنزل.
ومن دعا رجلا بالكفر : قال له يا كافر.
حار : رجع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6144', false),
(21806, 2, 218, 1806, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: «إن الله تعالى يغار، وغيرة الله أن يأتي المرء ما حرم الله عليه».', 'The Prophet (ﷺ) said, "Allah, the Exalted, becomes angry, and His Anger is provoked when a person does what Allah has declared unlawful.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1806', 'Riyad as-Salihin 1806', 'ریاض الصالحین 1806', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21807, 2, 218, 1807, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «من حلف فقال في حلفه: باللات والعزى، فليقل: لا إله إلا الله، ومن قال لصاحبه: تعالى أقامرك فليتصدق».', 'The Prophet (ﷺ) said, "He who takes an oath and involuntarily says: ''By Al-Lat and Al-''Uzza'' should at once affirm: ''La ilaha illallah (there is no true god except Allah)'', and he who says to his companion: ''Come let''s gamble'' should make expiation by giving something in charity.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1807', 'Riyad as-Salihin 1807', 'ریاض الصالحین 1807', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21808, 2, 219, 1808, 'hadith', 'عن النواس بن سمعان رضي الله عنه قال: ذكر رسول الله صلى الله عليه وسلم الدجال ذات غداة، فخفض فيه، ورفع حتى ظنناه في طائفة النخل. فلما رحنا إليه، عرف ذلك فينا، فقال: "ما شأنكم؟" قلنا: يا رسول الله ذكرت الدجال الغداة، فخفضت فيه حتى ظنناه في طائفة النخل فقال: "غير الدجال أخوفنى عليكم؛ إن يخرج وأنا فيكم، فأنا حجيجه دونكم؛ وإن يخرج ولست فيكم، فامرؤ حجيج نفسه، والله خليفتي على كل مسلم، إنه شاب قطط، عينه طافية، كأني أشبهه بعبد العزى بن قطن، فمن أدركه منكم فليقرأ عليه فواتح سورة الكهف، إنه خارج خلة بين الشام والعراق، فعاث يمينا وعاث شمالاً، يا عباد الله فاثبتوا" قلنا: يا رسول الله وما لبثه في الأرض؟ قال: "أربعون يوماً: يوم كسنة، ويوم كشهر، ويوم كجمعة، وسائر أيامه كأيامكم" قلنا : يا رسول الله ، فذلك اليوم الذي كسنة أتكفينا فيه صلاة يوم؟ قال: لا، اقدروا له قدره" فقلنا: يا رسول الله وما إسراعه في الأرض؟ قال: "كالغيث استدبرته الريح، فيأتي على القوم، فيدعوهم، فيؤمنون به، ويستجيبون له فيأمر السماء فتمطر، والأرض فتنبت، فتروح عليهم سارحتهم، أطول ما كانت ذرى، وأسبغه ضروعاً، وأمده خواصر، ثم يأتي القوم فيدعوهم، فيردون عليه قوله، فيصرف عنهم، فيصبحون ممحلين ليس بأيديهم شيء من أموالهم، ويمر بالخربة فيقول لها: أخرجي كنوزك، فتتبعه كنوزها كيعاسيب النحل، ثم يدعو رجلاً ممتلئاً شبابا فيضربه بالسيف، فيقطعه جزلتين رمية الغرض، ثم يدعوه، فيقبل، ويتهلل وجهه يضحك، فبينما هو كذلك إذ بعث الله تعالى المسيح ابن مريم،صلى الله عليه وسلم ، فينزل عند المنارة البيضاء شرقي دمشق بين مهرودتين، واضعاً كفيه على أجنحة ملكين، إذا طأطأ رأسه، قطر، وإذا رفعه تحدر منه جمان كاللؤلؤ، فلا يحل لكافر يجد نفسه إلا مات، ونفسه ينتهي إلى حيث ينتهي طرفه، فيطلبه حتى يدركه بباب لد فيقتله، ثم يأتي عيسى ، صلى الله عليه وسلم ، قوم قد عصمهم الله منه، فيمسح عن وجوههم، ويحدثهم بدرجاتهم في الجنة، فبينما هو كذلك إذ أوحى الله تعالى إلى عيسى صلى الله عليه وسلم إني قد أخرجت عباداً لي لا يدان لأحد بقتالهم، فحرز عبادي إلى الطور، ويبعث الله يأجوج ومأجوج وهم من كل حدب ينسلون، فيمر أوائلهم على بحيرة طبرية فيشربون ما فيها، ويمر آخرهم فيقول: لقد كان بهذه مرة ماء، ويحصر نبي الله عيسى، صلى الله عليه وسلم ، وأصحابه حتى يكون رأس الثور لأحدهم خيراً من مائة دينار لأحدكم اليوم، فيرغب نبي الله عيسى، صلى الله عليه وسلم وأصحابه، رضي الله عنهم، إلى الله تعالى، فيرسل الله تعالى عليهم النغف في رقابهم، فيصبحون فرسى كموت نفس واحدة ثم يهبط نبي الله عيسى، صلى الله عليه وسلم ، وأصحابه رضي الله عنهم، إلى الله تعالى، فيرسل الله تعالى عليهم النغف في رقابهم فيصبحون فرسى كموت نفس واحدة ثم يهبط نبي الله عيسى، صلى الله عليه وسلم ، وأصحابه رضي الله عنهم، إلى الأرض، فلا يجدون في الأرض موضع شبر إلا ملأه زهمهم ونتنهم، فيرغب، نبي الله عيسىصلى الله عليه وسلم ، وأصحابه رضي الله عنهم إلى الله تعالى، فيرسل الله تعالى طيراً كأعناق البخت، فتحملهم، فتطرحهم حيث شاء الله، ثم يرسل الله عز وجل مطراً لا يكن منه بيت مدر ولا وبر، فيغسل الأرض حتى يتركها كالزلقة، ثم يقال للأرض: أنبتي ثمرتك، وردي بركتك، فيومئذ تأكل العصابة من الرمانة، ويستظلون بقحفها، ويبارك في الرسل حتى إن اللقحة من الإبل لتكفي الفئام من الناس، واللقحة من البقر لتكفي القبيلة من الناس، واللقحة من الغنم لتكفي الفخذ من الناس، فبينما هم كذلك إذ بعث الله تعالى ريحاً طيبة، فتأخذهم تحت آباطهم، فتقبض روح كل مؤمن وكل مسلم؛ ويبقى شرار الناس يتهارجون فيها تهارج الحمر فعليهم تقوم الساعة" ((رواه مسلم)). قوله: «خلة بين الشام والعراق» : أي طريقا بينهما. وقوله: «عاث» بالعين المهملة والثاء المثلثة، والعيث: أشد الفساد. «والذرى» : بضم الذال المعجمة وهو أعالي الأسنمة وهو جمع ذروة بضم الذال وكسرها « واليعاسيب» : ذكور النحل. «وجزلتين» : أي قطعتين، «والغرض» : الهدف الذي يرمى إليه بالنشاب، أي: يرميه رمية كرمية النشاب إلى الهدف. «والمهرودة» بالدال المهملة والمعجمة، وهي: الثوب المصبوغ. قوله: «لا يدان» : أي لا طاقة. «والنغف» : دود. «وفرسى» : جمع فريس، وهو القتيل. و «الزلقة» : بفتح الزاي واللام وبالقاف، ... وروي: الزلفة بضم الزاي وإسكان اللام وبالفاء وهي المرآة. ... «والعصابة» : الجماعة. «والرسل» بكسر الراء: اللبن. «واللقحة» : اللبون. «والفئام» بكسر الفاء وبعدها همزة ممدودة: الجماعة. ... «والفخذ» من الناس: دون القبيلة.', 'One morning the Messenger of Allah (ﷺ) made a mention of Dajjal, and he described him to be insignificant and at the same time described him so significant that we thought he was on the date-palm trees (i.e., nearby). When we went to him (the Prophet (ﷺ)) in the evening, he perceived the sign of fear on our faces. He said, "What is the matter with you?'''' We said: "O Messenger of Allah, you talked about Dajjal this morning raising your voice and lowering it until we thought he was hiding in the palm-trees grove: He said: "Something other than Dajjal make worry about you. If he appears while I am with you, I will defend you against him. But if he appears after I die, then everyone of you is his own defender. Allah is the One Who remains after me to guide every Muslim. Dajjal will be a young man with very curly hair with one eye protruding (with which he cannot see). I compare (his appearance) to that of Al-`Uzza bin Qatan. He who amongst you survives to see him, should recite over him the opening Ayat of Surat Al-Kahf (i.e., Surat 18: Verses 1-8). He will appear on the way between Syria and Iraq and will spread mischief right and left. O slaves of Allah! Remain adhered to the truth.'''' We asked: "O Messenger of Allah! How long will he stay on the earth?'''' He said, "For forty days. One day will be like a year, one day like a month, one day like a week and the rest of the days will be like your days.'''' We said: "O Messenger of Allah! Will one day''s Salat (prayer) suffice for the Salat of that day which will be equal to one year?'''' Thereupon he said, "No, but you must make an estimate of time and then offer Salat.'''' We said: "O Messenger of Allah! How quickly will he walk upon the earth?'''' Thereupon he said, "Like cloud driven by the wind (i.e., very quickly). He will come to the people and call them to his obedience and they will affirm their faith in him and respond to him. He will then give command to the sky and it will send its rain upon the earth and he will then send his command to the earth and it will grow vegetation. Then in the evening their pasturing animals will come to them with their humps very high and their udders full of milk and their flanks stretched. He will then come to another people and invite them, but they will reject him and he will leave them, in barren lands and without any goods and chattels! He would then walk through the waste land and say to it: `Bring forth your treasures'', and the treasures will come out and follow him like swarms of bees. He will then call a person brimming with youth and strike him with the sword and cut him into two pieces and make these pieces lie at a distance, which is generally between the archer and his target. He will then call that young man and he will come forward, laughing, with his face gleaming out of joy; and it will be at this very time that Allah will send `Isa (Jesus), son of Maryam (Mary) who will descend at the white minaret in the eastern side of Damascus, wearing two garments lightly dyed and placing his hands on the wings of two angels. When he will lower his head, there would fall drops of water from his head, and when he will raise it up, drops like pearls would scatter from it. Every disbeliever who will find his (i.e., `Isa''s) smell will die and his smell will reach as far as he will be able to see. He will then search for Dajjal until he will catch hold of him at the gate of Ludd (village near Jerusalem), and will kill him. Then the people, whom Allah will have protected, will come to `Isa son of Maryam, and he will wipe their faces and will inform them of their ranks in Jannah, and it will be under such conditions that Allah will reveal to `Isa these words: `I have brought forth from amongst my slaves such people against whom none will be able to fight, so take these people safely to the mountain.'' And then Allah will send Ya''juj and Ma''juj (Gog and Magog people) and they will sworn down from every slope. The first of them will pass the Lake Tabariyah (near the Dead Sea in Palestine) and drink all its water. And when the last of them will pass, he will say: `There was once water there.'' Prophet `Isa (ﷺ) and his companions will then be so much hard-pressed that the head of an ox will be dearer to them than one hundred dinar, and `Isa along with his companions, will make supplication to Allah, Who will send insects which will attack their (Ya''juj and Ma''juj people) neck until they all will perish like a single person. Prophet, `¦sa and his companions will then come down and they will not find in the earth as much space as a single span which would not be filled with their corpses and their stench. Prophet `Isa and his companions will then again beseech Allah, Who will send birds whose necks will be like those of Bactrian camels, and they will carry them and throw them where Allah will desire. Then Allah will send down rain which will spare no house in the city or in the countryside. It would wash away the earth until it appears like a mirror. Then the earth will be told to bring forth its fruit and restore its blessings; and as a result of this, there will grow such a big pomegranate that a group of people will eat from it and seek shelter under its skin. Milk will be so blessed that the milk of one she-camel will suffice for a large company and the cow will give so much milk, that it will suffice for a whole tribe. The sheep will give so much milk that the whole family will be able to drink out of that, and at that time Allah will send a pleasant wind which will soothe people even under their armpits, and will take the life of every Muslim and true believer, and only the wicked will survive. They will commit adultery in public like asses and the Resurrection Day will be held.''''', 'النواس بن سمعان رضي الله عنه', 'An-Nawwas bin Sam`an (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1808', 'Riyad as-Salihin 1808', 'ریاض الصالحین 1808', null, 'من علامات الساعة الكبرى خروج الدجال، وهو ما ذكر في الحديث فهي من أمور الغيب التي يجب الإيمان والتصديق بها كما أخبر بها نبي الله صلى الله عليه وسلم، فذكرت أوصافه كاملة حتى لا تخفى على المسلم من أمره، وقد أعطاه الله من القدرات العجيبة والخوارق امتحاناً واختباراً للناس، ويمر على الأرض جميعاً إلا مكة والمدينة، ويكون نهاية أمره على نبي الله عيسى عليه الصلاة والسلام، ثم يظهر يأجوج ومأجوج ويملؤن الأرض فساداً، وهم من علامات الساعة أيضاً، ويتضرع نبي الله عيسى والمؤمنون إلى الله تعالى حتى يخلصهم الله منهم، وتقوم الساعة بعد هذه الأحداث والوقائع الكبرى وقد قبض الله تعالى أرواح عباده المؤمنين، وتقوم القيامة على شرار الخلق.', 'إثبات ظهور الدجال، وبيان عظم فتنته، وأنها أشد فتنة تمر بالمسلمين.
من صفات الدجال أنه: شديد جعودة الشعر، عينه كالعنبة الطافية فهي بارزة ذهب نورها لأنه أعور.
يخرج الدجال بين العراق والشام.
يمكث الدجال أربعين يوماً؛ يوم كسنة، ويوم كشهر، ويوم كجمعة، وسائر أيامه مثل أيام الناس.
فساده يملأ الأرض بسرعة مذهلة حيث لا يأمن مؤمن من شره، ولا يخلو من فتنته موطن خلا مكة والمدينة فإنه لا يطأها.
يُعطى من الآيات العجيبة فتنة للعباد مثل سرعته في الأرض، وإنزال المطر، وكنوز الأرض تتبعه كما يتبع النحل أميره.
جواز تعظيم شأن الكذاب والدجال لبيان شدة فتنته وتحذير الأمة منه.
وجوب تحذير الأمة الإسلامية من الدجاجلة، ولذلك فاضت السنة تحذيراً وإخباراً ووصفاً ولم تترك مجالاً لذلك.
شفقة رسول الله صلى الله عليه وسلم على أمته وخوفه عليهم من الدجاجلة الذين يأتون من بعده.
سعة رحمة الله -تعالى- بالمؤمنين، حيث زودهم بسلاح يبطل حجج الدجال، ومن ذلك : أ/ بيان صفاته مما يدل على كذبه ودجله .ب/ قدرة المؤمن على قراءة ما كتب على جبينه مما يدل على كفره .ج/ حفظ فواتح سورة الكهف عاصم من شره، فمن أدركه فليقرأها عليه.
الحض على الثبات في الفتن وعدم الزيغ.
بيان فضل سورة الكهف وأن فواتحها حرز ووقاية من فتنة الدجال.
حب الصحابة رضي الله عنهم للعلم.
جواز التشبيه للتقريب.
إثبات نزول المسيح عيسى ابن مريم صلى الله عليه وسلم، والأخبار في ذلك متواترة.
بيان أن عيسى صلى الله عليه وسلم هو الذي يقتل الدجال.
بيان عظم يأجوج ومأجوج وأن فتنتهم تملأ الأرض وأنهم من علامات الساعة الكبرى.
المال عند الشدة والجوع لا يساوي شيئاً لقوله عليه الصلاة والسلام: حتى يكون رأس الثور لأحدهم خير من مائة دينار لأحدكم اليوم.
رسول الله صلى الله عليه وسلم أقوى حجة وبيان من الدجال، فلو أنه ظهر في زمنه لكان رسول الله صلى الله عليه وسلم الغالب له لا محالة.', 'خفض فيه ورفع : حقره وصغره ثم عظمه وفخمه لعظم فتنته.
حتى ظنناه في طائفة النخل : حتى توهمنا أنه على مقربة من نخل المدينة.
قطط : شديد جعودة الشعر.
عينه طافية : ذهب نورها أو عينه بارزة وفيها بصيص من نور.
عبد العزى بن قطن : رجل من بني المصطلق من خزاعة هلك في الجاهلية.
استدبرته الريح : جاءت بعده فجففته، والمراد بيان سرعة إفساده في الأرض.
ويستجيبون له : يجيبونه ويتبعونه.
فتروح : ترجع عليهم.
سارحتهم : بهائمهم.
وأسبغه ضروعاً : أطوله لكثرة اللبن.
أمُدّ خواصر : لكثر امتلائها من الشبع.
ممحلين : ينقطع عنهم المطر وتيبس الأرض والكلاْ.
الخربة : الموضع الخراب.
اليعاسيب : ذكور النحل.
ممتلىء شباباً : في عنفوان شبابه.
جزلتين : قطعتين.
الغرض : الهدف الذي يرمى إليه بالنشاب.
قطر : نقط الماء منه.
جمان اللؤلؤ : حبات من الفضة تصنع على هيئة اللؤلؤ الكبار، والمراد ينحدر منه الماء على هيئة اللؤلؤ في صفائه.
لدّ : بلدة قريبة من بيت المقدس في فلسطين.
حدب : غليظ الأرض ومرتفعها.
ينسلون : يسرعون، والمراد يظهرون من كل مكان.
طبرية : بلدة مطلة على البحيرة، في طرف الجبل، وهي اليوم تحت سيطرة يهود لعنهم الله وطهر البلاد منهم.
زهمهم : ريحهم المنتنة.
كموت نفس واحدة : يموتون دفعة واحدة.
المدر : هو الطين الصلب.
الوبر : هو الخباء.
يتهارجون تهارج الحمر : يجامع الرجال النساء علانية بحضرة الناس كما تفعل الحمير ولا يكترثون لذلك.
النغف : دود يكون في أنوف الإبل والغنم.
عاث : العيث: أشد الفساد.
الذرى : جمع ذروة، وهو أعالي الأسنمة.
الزلقة : المرآة.
الرسل : اللبن.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6380', false),
(21809, 2, 219, 1809, 'hadith', 'عن ربعي بن حراش قال: انطلقت مع أبي مسعود الأنصاري إلى حذيفة بن اليمان رضي الله عنهم فقال له أبو مسعود، حدثني ما سمعت من رسول الله صلى الله عليه وسلم ، في الدجال قال: «إن الدجال يخرج ، وإن معه ماء وناراً ، فأما الذي يراه الناس ماء فنار تحرق، وأما الذي يراه الناس نارأً، فماء بارد عذب، فمن أدركه منكم، فليقع في الذي يراه ناراً، فإنه ماء عذب طيب» فقال أبو مسعود: وأنا قد سمعته.', 'I accompanied Abu Mas''ud Al-Ansari to Hudaifah bin Al-Yaman (May Allah be pleased with them). Abu Mas''ud said to him: "Tell us what you heard from the Messenger of Allah (ﷺ) about Dajjal (the Antichrist)." Hudaifah said: He (ﷺ) said, "Dajjal will appear, and with him will be water and fire. That which people consider to be water will in fact be a burning fire, and that which people will consider to be fire will in fact be cool and sweet water. He who from amongst you happens to face him, should jump into that which he sees as fire for that will be nice and sweet water." Abu Mas''ud said: "I have also heard this from the Messenger of Allah (ﷺ)."', 'ربعي بن حراش قال: انطلقت مع أبي مسعود الأنصاري إلى حذيفة بن اليمان رضي الله عنهم', 'Rib''i bin Hirash (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1809', 'Riyad as-Salihin 1809', 'ریاض الصالحین 1809', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21810, 2, 219, 1810, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «يخرج الدجال في أمتى فيمكث أربعين لا أدري يوماً أو أربعين شهراً، أو أربعين عاماً، فيبعث الله تعالى عيسى بن مريم. صلى الله عليه وسلم ، فيطلبه فيهلكه، ثم يمكث الناس سبع سنين ليس بين اثنين عداوة، ثم يرسل الله عز وجل،ريحاً باردة من قبل الشام، فلا يبقى على وجه الأرض أحد في قلبه مثقال ذرة من خير أو إيمان إلا قبضته، حتى لو أن أحدكم دخل في كبد جبل، لدخلته عليه حتى تقبضه، فيبقى شرار الناس في خفة الطير، وأحلام السباع لا يعرفون معروفاً ، ولا ينكرون منكراً، فيتمثل لهم الشيطان، فيقول: ألا تستجيبون؟ فيقولون : فما تأمرنا؟ فيأمرهم بعبادة الأوثان، وهم في ذلك دار رزقهم، حسن عيشهم ، ثم ينفخ في الصور، فلا يسمعه أحد إلا أصغى ليتا ورفع ليتا، وأول من يسمعه رجل يلوط حوض إبله فيصعق ويصعق الناس، ثم يرسل الله -أو قال: ينزل الله - مطرا كأنه الطل أو الظل، فتنبت منه أجساد الناس، ثم ينفخ فيه أخرى فإذا هم قيام ينظرون ، ثم يقال: يا أيها الناس هلم إلى ربكم ، وقفوهم إنهم مسؤولون ، ثم يقال: أخرجوا بعث النار فيقال: من كم؟ فيقال: من كل ألف تسعمائة وتسعة وتسعين، فذلك يوم يجعل الولدان شيباً، وذلك يوم يكشف عن ساق" ((رواه مسلم)). «الليت» : صفحة العنق. ومعناه يضع صفحة عنقه ويرفع صفحته الأخرى.', 'The Messenger of Allah (ﷺ) said, "Dajjal (the Antichrist) will appear in my Ummah and he will stay in the world for forty. I do not know whether this will be forty days or forty months or forty years. Allah will then send (Prophet) ''Isa (Jesus), son of Maryam (Mary). ''Isa will pursue him and slaughter him. Then people will survive for seven years (i.e., after the demise of ''Isa) in the state that there will be no rancour between two persons. Then Allah will send a cool breeze from the side of Ash-Sham. None will remain upon the face of the earth having the smallest particle of good or Faith in him but he will die, so much so that even if someone amongst you will enter the innermost part of a mountain, this breeze will reach that place also and will cause him to die. Only the wicked people will survive and they will be as fast as birds (i.e., to commit evil) and as ferocious towards one another as wild beasts. They will never appreciate the good, nor condemn evil. Then Shaitan (Satan) will come to them in the garb of a man and will say: ''Will you not obey me?'' They will say: ''What do you order us to do?'' He will command them to worship idols. They will have abundance of sustenance and will lead comfortable lives. Then the Trumpet will be blown. Every one hearing it, will turn his neck towards it and will raise it. The first one to hear that Trumpet will be a man who will be busy repairing the basin for his camels. He will become unconscious. Allah will send, or will cause to send, rain which will be like dew and there will grow out of it (like wild growth) the bodies of the people. Then the second Trumpet will be blown and they will stand up and begin to look around. Then it will be said: ''O people! Go to your Rubb.'' Then there will be a command: ''Make them stand there.'' After it they will be called to account. Then it will be said: ''Separate from them the share of the Fire.'' It will be asked: ''How much?'' It will be said: ''Nine hundred and ninety-nine out of every thousand.'' That will be the Day which will make children hoary-headed men because of its terror and that will be the Day when the Shin will be uncovered.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them) said:', null, 'رياض الصالحين 1810', 'Riyad as-Salihin 1810', 'ریاض الصالحین 1810', null, null, null, null, 'sunnah.com', null, false, null, false),
(21811, 2, 219, 1811, 'hadith', '-وعن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ليس من بلد إلى سيطؤه الدجال، إلا مكة والمدينة، وليس نقب من أنقابها إلا عليه الملائكة صافين تحرسهما، فينزل بالسبخة، فترجف المدينة ثلاث رجفات، يخرج الله منها كل كافر ومنافق».', 'The Messenger of Allah (ﷺ) said, "There will be no land which will not be trampled by Dajjal (the Antichrist) but Makkah and Al-Madinah; and there will be no passage leading to them which will not be guarded by the angels, arranged in rows. Dajjal will appear in a barren place adjacent to Al- Madinah and the city will be shaken three times. Allah will expel from it every disbeliever and hypocrite.".', null, 'Anas bin Malik (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1811', 'Riyad as-Salihin 1811', 'ریاض الصالحین 1811', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21812, 2, 219, 1812, 'hadith', 'وعنه رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «يتبع الدجال من يهود أصبهان سبعون ألفا عليهم الطيالسة».', 'The Messenger of Allah (ﷺ) said, "Dajjal (the Antichrist) will be followed by seventy thousand Jews of Isfahan and will be dressed in robes of green coloured satin.".', null, 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1812', 'Riyad as-Salihin 1812', 'ریاض الصالحین 1812', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21813, 2, 219, 1813, 'hadith', 'عن أم شريك رضي الله عنها أنها سمعت النبي صلى الله عليه وسلم يقول: لينفرن الناس من الدجال في الجبال".', 'I heard the Prophet (ﷺ) saying, "People will run away from Dajjal (the Antichrist) seeking shelter in the mountains.".', 'أم شريك رضي الله عنها', 'Umm Sharik (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1813', 'Riyad as-Salihin 1813', 'ریاض الصالحین 1813', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21814, 2, 219, 1814, 'hadith', 'عن عمران بن حصين رضي الله عنهما قال: سمعت رسول الله صلى الله عليه وسلم يقول: «ما بين خلق آدم إلى قيام الساعة أمر أكبر من الدجال».', 'I heard the Messenger of Allah (ﷺ) saying, "Between time of the creation of Adam and the Resurrection Day, there is nothing greater than the mischief of Dajjal (the Antichrist).".', 'عمران بن حصين رضي الله عنهما', '''Imran bin Hussain (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1814', 'Riyad as-Salihin 1814', 'ریاض الصالحین 1814', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21815, 2, 219, 1815, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال: "يخرج الدجال فيتوجه قبله رجل من المؤمنين فيتلقاه المسالح: مسالح الدجال، فيقولون له: إلى أين تعمد؟ فيقول: أعمد إلى هذا الذي خرج فيقولون له أوَ ما تؤمن بربنا؟ فيقول: ما بربنا خفاء! فيقولون: اقتلوه، فيقول بعضهم لبعض: أليس قد نهاكم ربكم أن تقتلوا أحداً دونه، فينطلقون به إلى الدجال، فإذا رآه المؤمن قال: يا أيها الناس إن هذا الدجال الذي ذكر رسول الله صلى الله عليه وسلم ؛ فيأمر الدجال به فيشبّح؛ فيقول: خذوه وشجوه، فيوسع ظهره وبطنه ضرباً، فيقول: أوَ ما تؤمن بي؟ فيقول: أنت المسيح الكذاب! فيؤمر به ، فيؤشر بالمنشار من مفرقه حتى يفرق بين رجليه، ثم يمشي الدجال بين القطعتين ، ثم يقول له: قم ، فيستوي قائماً، ثم يقول له: أتؤمن بي؟ فيقول: ما ازددت فيك إلا بصيرة، ثم يقول: يا أيها الناس إنه لا يفعل بعدي بأحد من الناس، فيأخذه الدجال ليذبحه، فيجعل الله ما بين رقبته إلى ترقوته نحاساً، فلا يستطيع إليه سبيلا، فيأخذ بيديه ورجليه فيقذف به، فيحسب الناس أنما قذفه إلى النار، وإنما ألقي في الجنة" فقال رسول الله صلى الله عليه وسلم : "هذا أعظم الناس شهادة عند رب العالمين" ((رواه مسلم)). وروى البخاري بعضه بمعناه "المسالح" :هم الخفراء والطلائع.', 'I heard the Prophet (ﷺ) saying, "Dajjal (the Antichrist) will come forth and a person from amongst the believers will go towards him and the armed watchmen of Dajjal will meet him and they will say to him: ''Where do you intend to go?'' He will say: ''I intend to go to this one who has appeared.'' They will say to him: ''Don''t you believe in our lord (meaning Dajjal)?'' He will say: ''There (i.e., we know Him to be Allah, Alone, without any partners) is nothing hidden about our Rubb.'' Some of them will say: ''Let us kill him'', but some others will say: ''Has your lord (Dajjal) not forbidden you to kill anyone without his consent?'' So they will take him to Dajjal. When the believer will see him, he will say: ''O people! This is Dajjal about whom the Messenger of Allah (ﷺ) has informed us.'' Dajjal will have him laid on his stomach and have his head. He will be struck on his back and on his stomach. Dajjal will ask him: ''Don''t you believe in me?'' He will say: ''You are the false Messiah.'' He will then give his order to have him sawn with a saw into two from the parting of his hair up to his legs. After that Dajjal will walk between the two halves and will say to him: ''Stand up'', and he will stand on his feet. He will then say to him: ''Don''t you believe in me?'' The person will say: ''It has added to my insight that you are Dajjal''. He will add: ''O people! He will not be able to behave with anyone amongst people in such a manner after me.'' Dajjal will try to kill him. The space between his neck and collarbone will turn into copper and he will find no way to kill him. So he will catch hold of him by his hand and feet and throw him into (what appears to be the fire). The people will think that he has been thrown into the fire whereas he will be thrown into Jannah." The Messenger of Allah (ﷺ) added, "He will be the most eminent amongst the people with regard to martyrdom near the Rubb of the worlds."', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', null, 'رياض الصالحين 1815', 'Riyad as-Salihin 1815', 'ریاض الصالحین 1815', null, null, null, null, 'sunnah.com', null, false, null, false),
(21816, 2, 219, 1816, 'hadith', 'عن المغيرة بن شعبة رضي الله عنه قال: ما سأل أحد رسول الله صلى الله عليه وسلم عن الدجال أكثر مما سألته؛ وإنه قال لي: "مايضرك؟ "قلت: إنهم يقولون: إن معه جبل خبز ونهر ماء! قال: "هو أهون على الله من ذلك".', 'No one asked the Messenger of Allah (ﷺ) more about Dajjal than I asked him. He said to me, "He will not harm you." I said: "O Messenger of Allah, it is reported that he will have with him a mountain of bread and a river full of water." Thereupon he said, "He (Dajjal) is far too worthless and insignificant near Allah (to let him deceive the believers).".', 'المغيرة بن شعبة رضي الله عنه', 'Al-Mughirah bin Shu''bah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1816', 'Riyad as-Salihin 1816', 'ریاض الصالحین 1816', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21817, 2, 219, 1817, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ما من نبي إلا وقد أنذر أمته الأعور الكذاب، ألا إنه أعور، وإن ربكم عز وجل ليس بأعور، مكتوب بين عينيه ك ف ر».', 'The Messenger of Allah (ﷺ) said, "There has not been a Prophet who has not warned his Ummah of that one-eyed liar (Dajjal). Behold, he is blind in one eye and your Rubb (Allah) is not blind. On his forehead are the letters: (K.F.R.) (meaning Kafir- disbeliever).".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1817', 'Riyad as-Salihin 1817', 'ریاض الصالحین 1817', 'متفق عليه', 'كل نبي أرسله الله أنذر أمته وحذرها من المسيح الدجال؛ لأنهم علموا بخروجه وشدة فتنته، وبينوا لهم شيئاً من صفاته، وذكر في هذا الحديث أنه أعور والله سبحانه منزه عن هذا، ومن صفاته كذلك أنه مكتوب بين عينيه ك ف ر.', 'حرص الأنبياء على أممهم.
خطر فتنة الدجال.
المسيح الدجال كافر.
بيان أن الدجال أعور والله سبحانه ليس كذلك.
إثبات صفة العين لله وأن الله له عينان إذ العور يكون لمن له عينان.', 'نبي : هو الذي أنبأ عن الله أي: يخبر عن الله.
أنذر : أي: خوفه وحذره.
الأعور : ذهاب بصر إحدى العينين.
كَ فَ رَ : أي المسيح الدجال كفر بالله وجحد عبادة الله -تعالى-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5832', false),
(21818, 2, 219, 1818, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ألا أحدثكم حديثاً عن الدجال ما حدث به نبي قومه! إنه أعور، وإنه يجيء معه بمثال الجنة والنار، فالتي يقول إنها الجنة هي النار».', 'The Messenger of Allah (ﷺ) said, "Let me tell you something about Dajjal (the Antichrist) which no Prophet had told his people. He is blind (in one eye) and will bring with him something like Jannah and Hell; but what he calls Jannah will be in fact Hell.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1818', 'Riyad as-Salihin 1818', 'ریاض الصالحین 1818', 'متفق عليه', 'يُخبِرُ النبيُّ صلى الله عليه وسلم أصحابه عن الدجال وصفاته وعلاماته بما لم يحدِّث به نبي قبله، فمن ذلك:

 أنه أعور العين.

وأن الله تعالى جعل معه مثل الجنة والنار، بحسب رؤيا العين.

 لكن جنته نار، وناره جنة، من أطاعه أدخله هذه الجنة فيما يرى الناس، ولكنها نار محرقة، ومن عصاه أدخله النار فيما يراه الناس، ولكنها جنة طيبة، 
ثم حذرنا النبي صلى الله عليه وسلم من فتنته كما حذّر به نوح قومه.', 'عظم فتنة الدجال.
النجاة من فتنة الدجال تكون بصدق الإيمان واللجوء إلى الله تعالى والاستعاذة بالله منه في التشهد الأخير، وحفظ عشر آيات من أول سورة الكهف.
شدة حرص النبي صلى الله عليه وسلم على أمته، حيث بين للمسلمين من صفات الدجال ما لم يبينه نبي قبله.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3110', false),
(21819, 2, 219, 1819, 'hadith', 'عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم ذكر الدجال بين ظهراني الناس فقال: « إن الله ليس بأعور، ألا إن المسيح الدجال أعور العين اليمنى، كأن عينه عنبة طافية».', 'One day the Messenger of Allah (ﷺ) mentioned Al-Masih Dajjal (the Antichrist) in the presence of the people and said, "Verily, Allah is not one-eyed but Al-Masih Ad-Dajjal is blind in the right eye which looks like a swollen grape."', 'ابن عمر رضي الله عنهما', '''Abdullah bin ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1819', 'Riyad as-Salihin 1819', 'ریاض الصالحین 1819', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21820, 2, 219, 1820, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « لا تقوم الساعة حتى يقاتل المسلمون اليهود، حتى يختبيء اليهودي من وراء الحجر والشجر، فيقول الحجر والشجر: يا مسلم هذا يهودي خلفى تعالى فاقتله، إلا الغرقد فإنه من شجر اليهود».', 'The Messenger of Allah(ﷺ) said, "The Last Hour will not come until the Muslims fight against the Jews, until a Jew will hide himself behind a stone or a tree, and the stone or the tree will say: ''O Muslim, there is a Jew behind me. Come and kill him,'' but Al-Gharqad tree will not say so, for it is the tree of the Jews.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1820', 'Riyad as-Salihin 1820', 'ریاض الصالحین 1820', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21821, 2, 219, 1821, 'hadith', 'وعنه رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « والذي نفسي بيده لا تذهب الدنيا حتى يمر الرجل بالقبر، فيتمرغ عليه، ويقول: ياليتني مكان صاحب هذا القبر، وليس به الدين، ما به إلا البلاء».', 'The Messenger of Allah (ﷺ) said, "By Him in Whose Hand my soul is, the world will not come to an end until a man passes by a grave and will lie over it saying, ''Would that I were in this grave (i.e., dead)!'' Not he will say so because of religious reasons but because of widespread mischief and severe trials of this world.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1821', 'Riyad as-Salihin 1821', 'ریاض الصالحین 1821', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21822, 2, 219, 1822, 'hadith', 'وعنه رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : " لا تقوم الساعة حتى يحسر الفرات عن جبل من ذهب يقتتل عليه، فيقتل من كل مائة تسعة وتسعون، فيقول كل رجل منه: لعلي أن أكون أنا أنجو". وفي رواية: "يوشك أن يحسر الفرات عن كنز من ذهب، فمن حضره فلا يأخذ منه شيئاً".', 'The Messenger of Allah (ﷺ) said, "The Hour will not come to pass before the River Euphrates dries up to unveil the mountain of gold, for which people will fight. Ninety-nine out of one hundred will die (in the fighting) and every man amongst them will say: ''Perhaps I may be the only one to remain alive."''Another narration is: "The time is near when the River Euphrates will dry up to unveil a treasure of gold. Whosoever may be alive at that time, should not take anything of it."', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1822', 'Riyad as-Salihin 1822', 'ریاض الصالحین 1822', 'متفق عليه', 'يخبرنا نبينا الكريم صلى الله عليه وسلم أن قرب قيام الساعة يكشف نهر الفرات عن كنز من ذهب أو جبل من ذهب بمعنى أن الذهب يخرج جبلا، وأن الناس سيقتتلون عليه لأن ذلك من الفتن، ثم ينهانا صلى الله عليه وسلم عن الأخذ منه لمن أدرك ذلك؛ لأنه لا أحد ينجو منه، وربما يتأول بعض من يحضر ذلك هذا الحديث ويصرفه عن معناه ليسوغ لنفسه الأخذ منه، نعوذ بالله من الفتن.', 'فيه التنبيه إلى قرب الساعة وأن الناس غافلون عما فيها من أهوال.
التنافس على حطام الدنيا وزينتها يفضي إلى البغي والاقتتال.
أن الذهب يسلب العقول، فكل إنسان يقاتل غيره ويقول لعلي أنا الذي أنجو ويقاتل من أجل أن يحصل على الذهب.
أن الناس جبلوا على الطمع والجشع بسبب حبهم للدنيا فلو كان لأحدهم وادي من ذهب لابتغى واحدا آخر.
حرمة الأخذ من ذلك الذهب لقوله -صلى الله عليه وسلم-: "فمن حضره لا يأخذ منه شيئا".', 'يوشك : يقرب
يحسر : يكشف
الفرات : هو النهر المعروف في شرقي العراق', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3115', false),
(21823, 2, 219, 1823, 'hadith', 'وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «يتركون المدينة على خير ما كانت، لا يغشاها إلا العوافي -يريد: عوافي السباع والطير، وآخر من يحشر راعيان من مزينة يريدان المدينة ينعقان بغنمهما فيجدانها وحوشاً، حتى إذا بلغا ثنية الوداع خراً على وجوههما».', 'The Messenger of Allah (ﷺ) said, "People will desert Al-Madinah in spite of it being in better condition except for wild beasts and birds. The Last Hour will happen upon two shepherds of the tribe of Muzainah. They will enter Al-Madinah driving their sheep but will find it full of wild beasts and would turn away. When they will arrive at the hill named Thaniyyat-ul-Wada'' they will fall on their faces.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1823', 'Riyad as-Salihin 1823', 'ریاض الصالحین 1823', 'متفق عليه', 'يخبرنا النبي الكريم -ضلى الله عليه وسلم- في هذا الحديث أن المدينة النبوية زادها الله تشريفا وتعظيما يخرج عنها ساكنوها، ولا يبقى فيها إلا السباع والطيور ليس فيها أحد، وأن هذا سيحصل في آخر الزمان، وأنه سيأتي راعيا غنم من مزينة إلى المدينة يصيحان بغنمهما، فيجدانها ذات وحشة لخلائها، وهما آخر من يحشر، فإذا بلغا ثنية الوداع سقطا ميتين.', 'أن الترك للمدينة سيكون في آخر الزمان عند قيام الساعة، ويوضحه قوله (وآخر من يحشر).
أن الناس قرب قيام الساعة سوف يهجرون المدينة النبوية، ويهاجرون إلى غيرها من البلدان؛ طلبا لشهواتهم، وهي يومئذ خير البلاد.
الإخبار عن أمر مستقبل وهو أمر غيبي، وهذا من أعلام النبوة ودلائلها.
الإخبار عن آخر الناس موتا، وهما راعيان من قبيلة مزينة، ووصف دقيق لحالهما.', 'لا يغشاها : لا يقصدها ويسكنها.
العوافي : جمع عافية، وهي التي تطلب القوت والرزق من الدواب والطير.
ينعقان : يصيحان.
ثنية الوداع : الطريق في الجبل، يخرج إليه المشيعون للمسافر يودعونه عنده، وهو طريق في المدينة النبوية.
وحوشا : ذات وحوش؛ لذهاب أهلها عنها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3116', false),
(21824, 2, 219, 1824, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه أن النبي صلى الله عليه وسلم قال: "يكون خليفة.', 'The Prophet (ﷺ) said, "From your caliphs there will be one in the Last Days who will distribute wealth without counting it.".', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1824', 'Riyad as-Salihin 1824', 'ریاض الصالحین 1824', 'متفق عليه)). خلفائكم في آخر الزمان يحثو المال ولا يعده" ((رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21825, 2, 219, 1825, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه أن النبي صلى الله عليه وسلم قال: «ليأتين على الناس زمان يطوف الرجل فيه بالصدقة من الذهب، فلا يجد أحداً يأخذها منه، ويرى الرجل الواحد يتبعه أربعون امرأة يلذن به من قلة الرجال وكثرة النساء».', 'The Prophet (ﷺ) said, "A time will come when a man will go about with alms from his gold and will not find anyone to receive it. One man will be seen being followed by forty women dependant upon him on account of the scarcity of men and excess of women.".', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1825', 'Riyad as-Salihin 1825', 'ریاض الصالحین 1825', 'رواه مسلم', 'سيكثر المال بين يدي الناس حتى لا يوجد من يأخذه، وسيقل الرجال ويكثر النساء إما بسبب الحروب الطاحنة وإما لكثرة ولادة النساء، حتى يكون للرجل الواحد أربعون امرأة، من بنات وأخوات وشبههن من القريبات يلتجئن إليه ويستغثن به.', 'الحض على التبكير في إخراج الصدقات.
الإشارة إلى كثرة المال بين يدي الناس حتى لا يوجد من يأخذه في آخر الزمان.
الإشارة إلى كثرة الحروب والقتل في آخر الزمان مما يؤدي إلى قتل الرجال فيقلون ويكثر النساء.', 'يلذن به : يعتصمن به.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3118', false),
(21826, 2, 219, 1826, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: « اشترى رجل من رجل عقاراً، فوجد الذي اشترى العقار في عقاره جرة فيها ذهب، فقال له الذي اشترى العقار خذ ذهبك: إنما اشتريت منك الأرض، ولم أشتر الذهب، وقال الذي له الأرض: إنما بعتك الأرض وما فيها، فتحاكما إلى رجل، فقال الذي تحاكما إليه: ألكما ولد؟ قال أحدهما : لي غلام، وقال الآخر: لي جارية، قال: أنكحا الغلام الجارية وأنفقوا على أنفسهما منه وتصدقا».', 'The Prophet (ﷺ) said, "A man bought a piece of land from another man, and the buyer found a jar filled with gold in the land. The buyer said to the seller: ''Take your gold, as I bought only the land from you and not the gold.'' The owner of the land said: ''I sold you the land with everything in it.'' So both of them took their case before a third man who asked: ''Have you any children?'' One of them said: ''I have a boy.'' The other said, ''I have a girl.'' The man said: ''Marry the girl to the boy and spend the money on them; and whatever remains give it in charity."''.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1826', 'Riyad as-Salihin 1826', 'ریاض الصالحین 1826', 'متفق عليه', 'يخبرنا النبي صلى الله عليه وسلم أن رجلاً اشترى من رجل أرضا فوجد المشتري بها ذهبا ولشدة ورعه رد هذا الذهب إلى البائع؛ لأنه اشترى الأرض ولم يشتر الذهب الذي أودع فيه، فأبى البائع أيضا أن يأخذه؛ لشدة تحريه وورعه، ولأنه باع الأرض بما فيها، فاختصما وقالا للقاضي: ابعث من يقبضه وتضعه حيث رأيت، فامتنع، فسألهما هل عندهما أولاد؟ فأخبر أحدهما أن عنده غلام، وأخبر الآخر أن عنده جارية، فاقترح عليهما أن يزوج الشاب البنت وينفق عليهما من هذا الذهب وأن يتصدقا منه.', 'فيه تورع البائع والمشتري، وإنصاف الحاكم بينهما، وعدم طمعه.
وجوب رد الحقوق إلى أهلها إذا عرف أصحابها.
استحباب نكاح أبناء الرجال الصالحين بعضهم لبعض.
فضل الورع وترك ما فيه شبهة من المال.
فضل التصدق والإنفاق في سبيل الله تعالى.', 'العقار : كالأراضي والمنازل و العمائر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3119', false),
(21827, 2, 219, 1827, 'hadith', 'وعنه رضي الله عنه أنه سمع رسول الله صلى الله عليه وسلم يقول: «كانت امرأتان معهما ابناهما، جاء الذئب فذهب بابن إحداهما، فقالت لصاحبتها: إنما ذهب بابنك، وقالت الأخرى إنما ذهب بابنك فتحاكما إلى داود صلى الله عليه وسلم فقضى به للكبرى، فخرجتا على سليمان بن داود، صلى الله عليه وسلم فأخبرتاه، فقال: ائتوني بالسكين أشقه بينهما. فقالت الصغرى: لا تفعل رحمك الله، هو ابنها، فقضى به للصغرى».', 'The Messenger of Allah (ﷺ) said, "There were two women, each had her child with her. A wolf came and took away the child of one of them. One woman said to her companion: ''The wolf has taken your son.'' The other said: ''It has taken your son.'' So both of them took the dispute to Prophet Dawud (David) (ﷺ) who judged that the boy should be given to the older lady. Then they went to Prophet Sulaiman (Solomon) (ﷺ) son of Dawud and put the case before him. Prophet Sulaiman said: ''Give me a knife so that I may cut the child into two and give one half to each of you.'' The younger woman said: ''Do not do so; may Allah bless you! He is her child.'' On that Prophet Sulaiman decided the case in favour of the younger woman.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1827', 'Riyad as-Salihin 1827', 'ریاض الصالحین 1827', 'متفق عليه', 'يخبرنا نبينا صلى الله عليه وسلم عن قصة امرأتين خرجتا بابنين لهما فأكل الذئب ابن واحدة منهما وبقي ابن الأخرى، فقالت كل واحدة منهما إنه لي، فتحاكمتا إلى داود -عليه السلام- فقضى به للكبرى منهما اجتهادا منه؛ لأن الكبرى ربما تكون قد توقفت عن الإنجاب، أما الصغرى شابة وربما تنجب غيره في المستقبل، ثم خرجتا من عنده إلى سليمان -عليه السلام- ابنه، فأخبرتاه بالخبر فدعا بالسكين، وقال: أشقه بينكما نصفين، فأما الكبرى فرحبت وأما الصغرى فرفضت، وقالت هو ابن الكبرى، أدركتها الشفقة والرحمة لأنه ابنها حقيقة فقالت هو ابنها يا نبي الله، فقضى به للصغرى ببينة وقرينة كونها ترحم هذا الولد وتقول هو للكبرى ويبقى حيا أهون من شقه نصفين، فقضى به للصغرى.', 'أخذ العلماء من هذا الحديث العمل بالقرائن وأنه يجوز للقاضي أن يحكم بالقرائن إذا كانت قوية.
أن الفطنة والفهم موهبة من الله تعالى لا تتعلق بكبر سن ولا صغره.
إن قضاء داود بالولد للكبرى لسبب اقتضى ترجيح قولها عنده وهو أن الكبرى ربما تكون قد توقفت عن الإنجاب أما الصغرى شابة وربما تنجب غيره في المستقبل؛ إذ لا بينة لإِحداهما.
فيه جواز حكم الأنبياء بالاجتهاد وإن كان وجود النص ممكنا لديهم بالوحي، ليكون في ذلك زيادة أجورهم ولعصمتهم من الخطأ إذ لا يقرون على الباطل لعصمتهم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3120', false),
(21828, 2, 219, 1828, 'hadith', 'عن مرادس الأسلمي رضي الله عنه قال: قال للنبي صلى الله عليه وسلم : «يذهب الصالحون الأول فالأول، وتبقى حثالة كحثالة الشعير أو التمر، لا يباليهم الله باله».', 'The Prophet (ﷺ) said, "The pious men will depart one after another, the dregs of people, like the sediment of barley or dates will remain; Allah will not raise them in value and esteem.".', 'مرادس الأسلمي رضي الله عنه', 'Mirdas Al-Aslami (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1828', 'Riyad as-Salihin 1828', 'ریاض الصالحین 1828', 'رواه البخاري', 'يخبرنا النبي الكريم صلى الله عليه وسلم أنه في آخر الزمان يقبض الله أرواح الصالحين، ويبقى أناس ليسوا أهلًا للعناية، فلا يرفع الله لهم قدراً ولا يقيم لهم وزناً ولا يرحمهم ولا ينزل عليهم الرحمة وهم شرار الخلق عند الله وعليهم تقوم الساعة.', 'أن موت الصالحين وأهل العلم والفضل من أشراط الساعة.
الندب إلى الاقتداء بأهل الخير، والتحذير من مخالفتهم.
لا يبقى في آخر الزمان إلا أهل الجهل ممن لا يعرفون معروفًا ولا ينكرون منكرًا.', 'حثالة : بالثاء وبالفاء، روايتان، وهو الرديء والمراد هنا سَقَط الناس.
لا يباليهم الله بالة : ليس لهم قدر، فلا يعبأ الله بهم، ولا يقيم لهم وزنًا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3121', false),
(21829, 2, 219, 1829, 'hadith', 'عن رفاعة بن رافع الزرقي رضي الله عنه قال: جاء جبريل إلى النبي صلى الله عليه وسلم : »إذا أنزل الله تعالى بقوم عذاباً. وعن رفاعة بن رافع الزُّرَقِيِّ - رضي الله عنه - قال: جاء جبريل إلى النبيّ - صلى الله عليه وسلم - قال: مَا تَعُدُّونَ أهْلَ بَدْرٍ فِيكُمْ؟ قال: «مِنْ أفْضَلِ المُسْلِمِينَ» أوْ كَلِمَةً نَحْوَهَا. قال: وَكَذلِكَ مَنْ شَهِدَ بَدْرًا مِنَ المَلائِكَةِ. (رواه البخاري)', 'Jibril (Gabriel) came to the Prophet (ﷺ) and asked him: "How do you estimate among you those who participated in the battle of Badr?" He replied, "They were the best of Muslims" (or he may have said something similar to that). Jibril said: "The same is the case with the angels who were at Badr.".', 'رفاعة بن رافع الزرقي رضي الله عنه', 'Rifa''ah bin Rafi'' Az-Zuraqi (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1829', 'Riyad as-Salihin 1829', 'ریاض الصالحین 1829', null, 'يخبرنا الصحابي الجليل رفاعة رضي الله عنه أن جبريل عليه السلام أتى النبي صلى الله عليه وسلم فقال له: ما منزلة الذين شهدوا الجهاد في غزوة بدر، وقد نصر الله نبيه والمؤمنين الذين كانوا معه فيها نصرا مؤزرا فقال صلى لله عليه وسلم: هم من أفضل المسلمين عندنا، فرد جبريل عليه السلام: وأيضا الذين حضروها وقاتلوا من الملائكة.', 'عظيم فضل أهل بدر، وعدتهم ثلاث مائة وثلاثة عشر رجلًا.
فضل الملائكة الذين شهدوا بدرا وأنهم قاتلوا بها.
بيان ما لغزوة بدر من الأهمية ونصرة الله نبيه صلى الله عليه وسلم والمؤمنين وكسر شوكة المشركين في هذه الغزوة.
أن الملائكة تقاتل مع المؤمنين وتثبت أقدامهم في قتالهم ضد أعداء الله -تعالى-.', 'بدر : اسم مكان بين مكة والمدينة كان فيه وقعة بين المسلمين والمشركين.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4925', false),
(21830, 2, 219, 1830, 'hadith', 'عن ابن عمر رضي الله عنهما قال : قال رسولُ اللهِ : « إذَا أنْزَلَ اللهُ تَعَالَى بِقَومٍ عَذَاباً ، أصَابَ العَذَابُ مَنْ كَانَ فِيهِمْ ، ثُمَّ بُعِثُوا عَلَى أَعْمَالِهِمْ » . متفق عليه .', 'The Messenger of Allah (ﷺ) said, "If Allah afflicts punishment upon a nation, it befalls the whole population indiscriminately and then they will be resurrected and judged according to their deeds.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', null, 'رياض الصالحين 1830', 'Riyad as-Salihin 1830', 'ریاض الصالحین 1830', null, null, null, null, 'sunnah.com', null, false, null, false),
(21831, 2, 219, 1831, 'hadith', 'عن جابر رضي الله عنه قال: كان جذع يقوم إليه النبي صلى الله عليه وسلم ، يعني في الخطبة. فلما وضع المنبر، سمعنا للجذع مثل صوت العشار حتى نزل النبي، صلى الله عليه وسلم ، فوضع يده عليه فسكن". وفي رواية: فلما كان يوم الجمعة قعد النبي، صلى الله عليه وسلم على المنبر، فصاحت النخلة التى كان يخطب عندها حتى كادت أن تنشق. وفي رواية : فصاحت صياح الصبي، فنزل النبي صلى الله عليه وسلم ، حتى أخذها فضمها إليه، فجعلت تئن أنين الصبي الذي يسكت حتى استقرت ، قال: "بكت على ما كانت تسمع من الذكر".', 'There was a trunk of a date-palm tree upon which the Prophet (ﷺ) used to recline while delivering Khutbah (sermon). When a pulpit was placed in the mosque, we heard the trunk crying out like a pregnant she-camel. the Prophet (ﷺ) came down from the pulpit and put his hand on the trunk and it became quiet.Another narration is: The Prophet (ﷺ) used to stand by a tree or a date-palm on Friday (to give the Khutbah). Then an Ansari woman or man said, "O Messenger of Allah! Shall we make a pulpit for you?" He replied, "If you wish." So they made a pulpit for him and when it was Friday, the Prophet (ﷺ) sat on the pulpit .', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1831', 'Riyad as-Salihin 1831', 'ریاض الصالحین 1831', 'رواه البخاري', 'اتخذ النبي صلى الله عليه وسلم جذع نخلة منبراً له؛ فلما استبدله النبي صلى الله عليه وسلم سمُع صوت الجذع وبكاءه بسبب ما كان يسمع من الذكر، فنزل النبي صلى الله عليه وسلم فوضع يده عليه فَسَكَنَ. وفي رواية: فنزل النبي صلى الله عليه وسلم حتى أخذها فَضَمَّها إليه، وكان ذلك في خطبة الجمعة.', 'في الحديث دلالة على أن الجمادات قد يخلق الله لها إدراكًا.
الدلالة على رحمة وشفقة سيد المرسلين -صلى الله عليه وسلم- حتى مع الجمادات, مما يدل على أنه رحمة للعالمين.
السنة في خطبة الجمعة أن تكون على المنبر.', 'جذع : ساق نخلة.
عشار : الناقة التي انتهت في حملها إلى عشرة أشهر حتى تلد.
استقرت : سكنت.
تئن : تُصَوِّت.
وضع المنبر : أي في مسجد النبي -صلى الله عليه وسلم-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4927', false),
(21832, 2, 219, 1832, 'hadith', 'عن أبي ثعلبة الخشني جرثوم بن ناشر رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «إن الله تعالى فرض فرائض فلا تضيعوها، وحد حدوداً فلا تعتدوها، وحرم أشياء فلا تنتهكوها، وسكت عن أشياء رحمة لكم غير نسيان فلا تبحثوا عنها». حديث حسن. رواه الدارقطني وغيره.', 'The Messenger of Allah (ﷺ) said, "Allah, the Exalted, has laid down certain duties which you should not neglect, and has put certain limits which you should not transgress, and has kept silent about other matters out of mercy for you and not out of forgetfulness, so do not seek to investigate them."', 'أبي ثعلبة الخشني جرثوم بن ناشر رضي الله عنه', 'Abu Tha''labah Al-Khushani (May Allah be pleased with him) said:', 'قال النووي: حديث حسن', 'رياض الصالحين 1832', 'Riyad as-Salihin 1832', 'ریاض الصالحین 1832', null, 'يخبر النبي صلى الله عليه وسلم أن الله أوجب أشياء وفرض فرائض فالتزموها ولا تفرطوا فيها بالترك أو التهاون فيها، وجعل لكم حواجز وزواجر مقدرةً تحجزكم وتزجركم عما لا يرضاه، فلا تزيدوا عليها عمَّا أمر به الشرع، وحرم محرمات فلا تتناولوها ولا تقربوها، وما عدا ذلك تركها وسكت عنها رحمة بعباده، فتبقى على أصل إباحتها فلا تبحثوا عنها.', 'الحديث دليل على أن الله هو المشرع فالأمر بيده سبحانه.
تضمن الحديث قواعد الشرع حكمًا وإباحةً؛ إذ الحكم الشرعي إمَّا مسكوتٌ عنه أو متكلَّم به، وهو إما: مأمورٌ به وجوبًا أو ندبًا، أو منهيٌّ عنه تحريمًا أو كراهةً، أو مباحٌ.
أن ما سكت الله عنه فلم يفرضه، ولم يحده، ولم ينه عنه فهو الحلال.
حسن بيان النبي صلى الله عليه وسلم حيث ساق الحديث بهذا التقسيم الواضح البين .
وجوب المحافظة على فرائض الله تعالى.
تحريم التعدي على حدود الله تعالى.', null, 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66510', false),
(21833, 2, 219, 1833, 'hadith', 'عن عبد الله بن أبي أوفى رضي الله عنهما قال: غزونا مع رسول الله صلى الله عليه وسلم سبع غزوات نأكل الجراد، وفي رواية: نأكل معه الجراد".', 'We accompanied the Messenger of Allah (ﷺ) in seven expeditions, and we ate locusts..', 'عبد الله بن أبي أوفى رضي الله عنهما', '''Abdullah bin Abu ''Aufa (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1833', 'Riyad as-Salihin 1833', 'ریاض الصالحین 1833', 'متفق عليه', 'أنَّ الله سبحانه وتعالى رَزَقَ أصْحَابَ رَسُولِ اللهِ - صلى الله عليه وسلم - بِسَبْع غَزَوَات يَمُدَّهُم بِالْجَرَاد لعدم وجود القُوتِ عندهم كما أمدَّهم بالعنْبر الذي خرَجَ من البَحْرِ فأكلوا منه في غزوة أخرى.', 'حِلِّ أَكْلِ الْجَرَادِ.
الجراد حَلَالٌ بِأَي سَبَبٍ صَارَ مَوْتُه، لأن النبي -صلى الله عليه وسلم- قال: "أُحِلَّت لَنَا مَيتتان ودَمَان فأمَّا الميتتان، فالجرادُ والسَّمك، وأما الدمان، فالكبد و الطحال".', 'الجَرَادُ : طَائِرٌ صغير خلقته عجيبة، فيه صفات من حيوانات مختلفة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/2999', false),
(21834, 2, 219, 1834, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: «لا يلدغ المؤمن من جحر مرتين».', 'The Prophet (ﷺ) said, "A believer should not be stung twice from the same hole.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1834', 'Riyad as-Salihin 1834', 'ریاض الصالحین 1834', 'متفق عليه', 'يخبرنا النبي الكريم صلى الله عليه وسلم أن المؤمن لا يصاب من مكان واحد مرتين، فينبغي أن يكون حازمًا حذرًا متيقظًا لا يؤتى من الغفلة فينخدع.', 'ليس من شيم المؤمن أن ينخدع من الغادر اللئيم المتمرد مرتين.
وجوب أخذ المؤمن الحيطة والحذر حتى لا ينخدع بعدوه أو يؤتى من قبل نفسه ودنياه.
توجيه من النبي -صلى الله عليه وسلم- للمؤمن أن يكون كَيِّسًا فَطِنًا.
فيه أدب شريف أدَّبَ به النبي -صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ- أمته، ونبههم كيف يحذرون مما يخافون من سوء عاقبته.', 'لا يلدغ : لا يلسع، والمراد:لا يصاب.
من جحر واحد : من مكان واحد.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4928', false),
(21835, 2, 219, 1835, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم ، : «ثلاثة لا يكلمهم الله يوم القيامة ولا ينظر إليهم ولا يزكيهم ولهم عذاب أليم: رجل على فضل ماء بالفلاة يمنعه من ابن السبيل، ورجل بايع رجلاً، سلعة، بعد العصر، فحلف بالله لأخذها بكذا وكذا، فصدقه وهو على غير ذلك، ورجل بايع إماماً لا يبايعه إلا لدنيا، فإن أعطاه منها وفى ، وإن لم يعطه منها لم يف».', 'The Messenger of Allah (ﷺ) said, "There are three (types of) people with whom Allah will neither speak on the Day of Resurrection nor purify them (from sins) and there will be a painful chastisement for them: A person who has spare water in a desert and he refuses to give it to the traveller; a person who sells a commodity to another person after the afternoon prayer and swears by Allah that he has bought it at such and such price, and the buyer pays him accordingly though in reality it was not true; and a person who pledges allegiance to an Imam (leader) just for some worldly benefit, and then if the Imam bestows on him (something out of that) he fulfills his allegiance, and if does not give him, he does not fulfill it.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1835', 'Riyad as-Salihin 1835', 'ریاض الصالحین 1835', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21836, 2, 219, 1836, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: " بين النفختين أربعون" قالوا: يا أبا هريرة أربعون يوماً؟ قال: أبيت، قالوا: أربعون سنة؟ قال: أبيت، قالوا: أربعون شهراً؟ قال: أبيت" ويبلى كل شئ من الإنسان إلا عجب ذنبه، فيه يركب الخلق، ثم ينزل الله من السماء ماء، فينبتون كما ينبت البقل".', 'The Prophet (ﷺ) said, "Between the two Blowing of the Trumpet there will be an interval of forty." The people said, "O Abu Hurairah! Do you mean forty days?" He said, "I cannot say anything." They said, "Do you mean forty years?" He said, "I cannot say anything." They said, "Do you mean forty months?" He said, "I cannot say anything. The Prophet added: ''Everything of the human body will perish except the last coccyx bone (end part of the spinal cord), and from that bone Allah will reconstruct the whole body. Then Allah will send down water from the sky and people will grow like green vegetables''.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1836', 'Riyad as-Salihin 1836', 'ریاض الصالحین 1836', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21837, 2, 219, 1837, 'hadith', 'وعنه قال: بينما النبي صلى الله عليه وسلم في مجلس يحدث القوم، جاءه أعرابي فقال: متى الساعة؟ فمضى رسول الله صلى الله عليه وسلم ، يحدث، فقال بعض القوم: سمع ما قال: فكره ما قال، وقال بعضهم: بل لم يسمع، حتى إذا قضى حديثه قال: "أين السائل عن الساعة؟ "قال: ها أنا يا رسول الله . قال: "إذا ضيعت الأمانة ، فانتظر الساعة" قال: كيف إضاعتها؟ قالك "إذا وسد الأمر إلى غير أهله فانتظر الساعة".', 'Once the Prophet (ﷺ) was speaking to us when, a bedouin came and asked him: "When will the Last Day be?" The Messenger of Allah (ﷺ) continued his talk. Some of those present thought that he had heard him but disliked the interruption and the other said that he had not hear him. When the Messenger of Allah (ﷺ) concluded his speech he asked, "Where is the one who inquired about the Last Day?" The man replied: "Here I am." The Messenger of Allah (ﷺ) replied, "When the practice of honouring a trust is lost, expect the Last Day." He asked: "How could it be lost?" He replied, "When the government is entrusted to the undeserving people, then wait for the Last Day.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1837', 'Riyad as-Salihin 1837', 'ریاض الصالحین 1837', 'رواه البخاري', 'كان النبي صلى الله عليه وسلم في مجلس يتحدث مع الصحابة، فجاء رجل من سكان البادية وسأله: ما الوقت الذي تقوم فيه الساعة؟ فاستمر عليه الصلاة والسلام في حديثه الذي كان فيه ولم يجبه، فتردد الصحابة فقال بعضهم: سمع النبي صلى الله عليه وسلم سؤاله فكرهه، وقال بعضهم: بل لم يسمع سؤاله، فلما انتهى عليه الصلاة والسلام من حديثه، شك الراوي قال: أظن أنه قال: أين السائل عن زمان الساعة؟ فرد عليه: ها أنا يا رسول الله، قال: إذا ضاعت الأمانة فحينها انتظر الساعة، فسأله: وكيف تكون إضاعة الأمانة؟ قال: إذا جُعل الأمر المتعلق بالدين كالخلافة والقضاء والإفتاء بولاية غير أهل الدين والأمانات، فانتظر قيام الساعة، والمراد بالأمر بانتظارها الترقب، وأنها قريبة، وليس المراد القعود عن العمل.', 'الأئمة ائتمنهم الله على عباده وفرض عليهم النصح، وإذا قلدوا الأمر لغير المتأهل له فقد ضيعوا الأمانات.
الساعة لا تقوم حتى يؤتمن الخائن، وهذا إنما يكون إذا غلب الجهال وضعف أهل الحق عن القيام به ونصرته.
مشروعية تعليم السائل لقوله عليه الصلاة والسلام: أين السائل؟
مراجعة العالم عند عدم فهم السائل لقوله: كيف إضاعتها؟
ينبغي للعالم والقاضي ونحوهما رعاية تقدم الأسبق فالأسبق، فهنا إكمال موعظة الصحابة كان مقدَّمًا على إجابة السؤال.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66250', false),
(21838, 2, 219, 1838, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: «يصلون لكم، فإن أصابوا فلكم، وإن أخطؤوا فلكم وعليهم».', 'The Messenger of Allah (ﷺ) said, "Your leaders will lead you in Salat (prayer). If they conduct it properly, you and they will be rewarded; but if they make mistakes you will earn the reward and they will be held responsible (for the mistakes).".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1838', 'Riyad as-Salihin 1838', 'ریاض الصالحین 1838', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21839, 2, 219, 1839, 'hadith', 'وعنه رضي الله عنه : {كنتم خير أمة أخرجت للناس} قال: خير الناس للناس يأتون بهم في السلاسل في أعناقهم حتى يدخلوا في الإسلام. أخرجه: البخاري.', '"You are the best of peoples ever raised up for (the benefit of) mankind..." (3:110): The best for mankind are those who bring them with chains round their necks till they embrace Islam (and thereby save them from the eternal punishment in the Hell-fire, and make them enter Jannah in the Hereafter).".', null, 'Abu Hurairah (May Allah be pleased with him) said in the interpretation of the Ayah', 'صحيحان، والحديث الأول موقوف على أبي هريرة، والثاني مرفوع', 'رياض الصالحين 1839', 'Riyad as-Salihin 1839', 'ریاض الصالحین 1839', null, 'عَجِب الله سبحانه لقوم يُقادون إلى الجنة بالسلاسل، وهم قوم كانوا من الكفار يأسرهم المسلمون في الجهاد، ثم يُسلمون فيكون هذا الأسر سببًا في إسلامهم ودخولهم الجنة، ويعتبر الحديث الثاني كالتفسير والبيان للحديث الموقوف الأول، وقد وصف هؤلاء الآسرون في أثر أبي هريرة رضي الله عنه بأنهم خير الناس للناس، إذ كانوا سببًا في هداية هؤلاء المأسورين، وصدّر رضي الله عنه كلامه بالآية؛ لأن هذا مظهر من المظاهر الذي تتجلى فيه خيرية هذه الأمة.', 'خير الأمم وأنفع الناس للناس هي أمة الإسلام الذي جاء به محمد -صلى الله عليه وسلم-.
الجهاد في سبيل الله غايته إخراج الناس من ظلمات الكفر والشرك إلى نور التوحيد والإسلام.
أن من وجوه أفضلية أصحاب الرسول وخيريتهم للناس أنهم يأسرون الأسرى ويدعونهم للدخول في الإسلام؛ فيسلمون فيكونون من أهل الجنة, وذلك منتهى الفضل والنعمة.
فضل دعوة الناس للإسلام والحرص على هدايتهم.
بيان رحمة الله بعباده المؤمنين وفضله في إدخالهم الجنة.', 'أخرجت للناس : أظهرت للناس.
يأتون بهم في السلاسل : يأتون بهم أسرى مقيدين بالأغلال.
عَجِب : هذه صفة من صفات الله -تعالى- التي يثبتها أهل السنة والجماعة على الوجه اللائق به -عز وجل-، وهي تدل على محبة الله -تعالى- لهذا الفعل الذي هو محل التعجب، وتعجبه -سبحانه- ليس كتعجب المخلوق.
الجنة : هي الدار التي أعدها الله لمن اطاعه، فيها من النعيم المقيم ما لا يخطر على بال.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4932', false),
(21840, 2, 219, 1840, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: «عجب الله عز وجل من قوم يدخلون الجنة في السلاسل» ((رواهما البخاري)). معناه: يؤسرون ويقيدون ثم يسلمون فيدخلون الجنة.', 'the Prophet (ﷺ) said, "Allah marvels at those people who enter Jannah in chains.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', null, 'رياض الصالحين 1840', 'Riyad as-Salihin 1840', 'ریاض الصالحین 1840', null, null, null, null, 'sunnah.com', null, false, null, false)
