insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21841, 2, 219, 1841, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: «أحب البلاد إلى الله مساجدها ، وأبغض البلاد إلى الله أسواقها».', 'the Prophet (ﷺ) said, "The dearest parts on the face of the earth near Allah are its mosques, and the most hated parts near Allah are its markets.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1841', 'Riyad as-Salihin 1841', 'ریاض الصالحین 1841', 'رواه مسلم', 'أخبر النبي صلى الله عليه وسلم أن أحب الأماكن إلى الله عز وجل مساجدها؛ لأنها بيوت الطاعات، وأساسها على التقوى، وأبغض البلاد إلى الله أسواقها؛ لأنها غالبًا محل الغش والخداع والربا والأيمان الكاذبة وإخلاف الوعد والإعراض عن ذكر الله.', 'حرمة المساجد ومكانتها؛ لأنها بيوت يذكر فيها اسم الله كثيرًا.
الحث على لزوم المساجد، وكثرة التردد إليها، طلبًا لمحبة الله تعالى ومرضاته، وعلى تقليل التردد إلى الأسواق، إلا للحاجة؛ تجنبًا عن الوقوع في أسباب المَقْت.
قال النووي: المساجد محل نزول الرحمة والأسواق ضدها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4933', false),
(21842, 2, 219, 1842, 'hadith', 'عن سلمان الفارسي رضي الله عنه من قوله قال: لا تكونن إن استطعت أول من يدخل السوق، ولا آخر من يخرج منها، فإنها معركة الشيطان، وبها ينصب رايته. ((رواه مسلم هكذا)). ورواه البرقاني في صحيحه عن سلمان قال: قال رسول الله صلى الله عليه وسلم : «لا تكن أول من يدخل السوق، ولا آخر من يخرج منها، فيها باض الشيطان وفرخ».', 'The Prophet (ﷺ) said, "Do not, if you can help, be the first to enter the market and the last to leave it because it is an arena of Satan and the standard of Satan is set there.".There are other narrations with some variation in the wordings.', 'سلمان الفارسي رضي الله عنه', 'Salman Al-Farisi (May Allah be pleased with him) said:', null, 'رياض الصالحين 1842', 'Riyad as-Salihin 1842', 'ریاض الصالحین 1842', null, null, null, null, 'sunnah.com', null, false, null, false),
(21843, 2, 219, 1843, 'hadith', 'عن عاصم الأحول عن عبد الله بن سرجس رضي الله عنه قال: قلت لرسول الله صلى الله عليه وسلم : يا رسول الله غفر الله لك، قال: «ولك» قال عاصم: فقلت له: استغفر لك رضي الله عنه صلى الله عليه وسلم ؟ قال: نعم ولك، ثم تلا هذه الآية: {واستغفر لذنبك، وللمؤمنين والمؤمنات}.', '''Abdullah bin Sarjis (May Allah be pleased with him) said to the Messenger of Allah (ﷺ): "O Messenger of Allah! May Allah forgive all your sins!" The Messenger of Allah (ﷺ) said, "And yours also." ''Asim reported: I asked ''Abdullah: "Did the Messenger of Allah (ﷺ) seek forgiveness for you?" He replied: "Yes, and for you also." Then he recited the Verse: "Seek forgiveness for your sins and for the believing men and the believing women." (47:19).', 'عاصم الأحول عن عبد الله بن سرجس رضي الله عنه', '''Asim Al-Ahwal said:', 'صحيح', 'رياض الصالحين 1843', 'Riyad as-Salihin 1843', 'ریاض الصالحین 1843', 'محمد:19)). ((رواه مسلم', 'أخبر عبد الله بن سرجس رضي الله عنه أنه دعا للنبي صلى الله عليه وسلم بالمغفرة، فقابله النبي صلى الله عليه وسلم بالدعاء أيضا بالمغفرة، فسأل عاصمٌ الأحول عبدَ الله بن سرجس رضي الله عنه أستغفر لك رسول الله صلى الله عليه وسلم ؟ قال: نعم، واستغفر لك أيضا، ثم استدل على ذلك بقول الله تعالى لنبيه صلى الله عليه وسلم : {وَاسْتَغْفِرْ لِذَنْبِكَ وَلِلمُؤْمِنِينَ وَالمُؤْمِنَاتِ} .', 'استغفر رسول الله -صلى الله عليه وسلم- لعامة المسلمين لأنه أمر بذلك؛ فلا يتخلف عن أداء ما أمر به البتة.
بيان كرم خلق الرسول -صلى الله عليه وسلم- حيث يقابل الحسنة بمثلها.
جواز إطلاق الآية على بعضها؛ لقول عاصم الأحول: ثم تلا هذه الآية.', 'غفر : المغفرة هي أن الله -تعالى- يستر العبد ولا يطلع الناس على ذنبه ويعفو عنه ويتجاوز عنه لأنها مأخوذة من الستر والوقاية.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8262', false),
(21844, 2, 219, 1844, 'hadith', 'عن أبي مسعود الأنصاري رضي الله عنه قال: قال النبي صلى الله عليه وسلم : «إن مما أدرك الناس من كلام النبوة الأولى: إذا لم تستحي فاصنع ما شئت».', 'The Prophet (ﷺ) said, "One of the admonitions of the previous Prophets which has been conveyed to people is that if you have no modesty, you can do whatever you like.".', 'أبي مسعود الأنصاري رضي الله عنه', 'Abu Mas''ud Al-Ansari (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1844', 'Riyad as-Salihin 1844', 'ریاض الصالحین 1844', 'رواه البخاري', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ مما جاء فيه الوصية عن الأنبياء المتقدِّمين، وتَدَاوَلَه الناس بينهم وتوارثوه عنهم قرنًا بعد قرن، حتى وصل إلى أوّل هذه الأمة، انظر إلى ما تريد أنْ تَفعلَه، فإنْ كان ممّا لا يُستَحى منه فافعله، وإنْ كان ممّا يُستَحى منه فَدَعْه؛ فإنَّ المانع مِن فِعْل القبائح هو الحياء، فمَن لم يكن له حياءٌ، انْهَمَك في كلّ فَحْشاء ومُنكر.', 'الحياء أصل الأخلاق الكريمة.
الحياء صفة من صفات الأنبياء عليهم السلام، وهو من المأثور عنهم.
الحياء هو الذي يجعل المرء المسلم يفعل ما يُجَمِّلُ ويَزِيْن، ويَترك ما يُدّنِّس ويَشَيْن.
قال النووي: الأمر فيه للإباحة، أي: إذا أردت فعل شيء فإن كان مما لا تستحي إذا فعلتَه من الله ولا من الناس فافعله، وإلا فلا، وعلى هذا مدار الإسلام، وتوجيه ذلك أنَّ المأمورَ به الواجب والمندوب يُستحيَى مِن تَرْكِه، والمنهي عنه الحرام والمكروه يُستحيى من فعله، وأما المباح فالحياء من فعله جائز، وكذا مِن تركه، فتضمن الحديث الأحكام الخمسة، وقيل: هو أمرُ تهديد، ومعناه: إذا نُزِع مِنك الحياء فافعل ما شئت؛ فإنّ الله مجازيك عليه، وقيل: هو أمرٌ بمعنى الخبر، أي: مَن لا يَستحيي يَصنع ما أراد.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4559', false),
(21845, 2, 219, 1845, 'hadith', 'عن ابن مسعود رضي الله عنه قال: قال النبي صلى الله عليه وسلم : «أول ما يقضى بين الناس يوم القيامة في الدماء».', 'The Prophet (ﷺ) said, "The first matter concerning which people will be judged on the Day of Resurrection will be the matter of blood."', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1845', 'Riyad as-Salihin 1845', 'ریاض الصالحین 1845', 'متفق عليه', 'ذَكَرَ النبيُّ صلى الله عليه وسلم أنَّ أوَّلَ ما يُحْكَمُ بين الناس في ظُلمِ بعضِهم بعضًا يومَ القيامة: في الدماء، كالقتل والجروح.', 'عِظَمُ أمر الدِّماء، فإنَّ البَدَاءةَ تكونُ بالأهم.
الذنوب تَعْظُمُ بحسب عِظَمِ المَفسدة الواقعة بها، وإزهاق الأنفس البريئة من أعظم المفاسد ولا أعظم منها إلا الكفر والشرك بالله تعالى.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/2962', false),
(21846, 2, 219, 1846, 'hadith', 'عن عائشة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم : «خلقت الملائكة من نور، وخلق الجان من مارج من نار، وخلق آدم مما وصف لكم».', 'The Messenger of Allah (ﷺ) said, "Angels were created from light, jinns were created from a smokeless flame of fire, and ''Adam was created from that which you have been told (i.e., sounding clay like the clay of pottery).".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1846', 'Riyad as-Salihin 1846', 'ریاض الصالحین 1846', 'رواه مسلم', 'أخبر صلى الله عليه وسلم عن بدء الخلق، فذكر أن الملائكة خلقوا من النور، ولذلك كانوا كلهم لا يعصون الله ولا يستكبرون عن عبادته، أما الجن فخلقوا من نار، ولهذا يتصف كثير منهم بالطيش والعبث والعدوان، وخلق آدم مما ذكر لكم يعني خلق من طين من تراب من صلصال كالفَخار؛ لأن التراب صار طينًا ثم صار فخارًا فخلق منه آدم -عليه الصلاة والسلام-.', 'تنبيه على عظيم قدرة الله -تعالى-.
بيان أصل تكوين خلقة الملائكة والجن والإنسان.
خلق الله الملائكة من نور.
خلق الله الجان من نار.
خلق الله آدم من طين.
في الحديث دليل على أن الجن هم ذرية الشيطان الأكبر الذي أبى أن يسجد لآدم.', 'المارج : اللهب الذي يعلو النار، فيختلط بعضه ببعض: أحمر، وأصفر، وأخضر.
مما وصف لكم : من الطين.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8264', false),
(21847, 2, 219, 1847, 'hadith', 'وعنها رضي الله عنها قالت: «كان خلق نبي الله صلى الله عليه وسلم القرآن».', 'The conduct of the Prophet (ﷺ) was entirely according to the Qur''an..', null, '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1847', 'Riyad as-Salihin 1847', 'ریاض الصالحین 1847', 'رواه مسلم في جملة حديث طويل', null, null, null, 'sunnah.com', null, false, null, false),
(21848, 2, 219, 1848, 'hadith', 'وعنها قالت : قال رسول الله صلى الله عليه وسلم : "من أحب لقاء الله أحب الله لقاءه، ومن كره لقاء الله كره الله لقاءه" فقلت: يا رسول الله ، أكراهية الموت؟ فكلنا نكره الموت! قال:"ليس كذلك، ولكن المؤمن إذا بشر برحمة الله ورضوانه وجنته أحب لقاء الله ، فأحب الله لقاءه، وإن الكافر إذا بشر بعذاب الله وسخطه، كره لقاء الله وكره الله لقاءه".', 'The Messenger of Allah (ﷺ) said, "He who loves to meet Allah, Allah loves to meet him; and he who dislikes to meet Allah, Allah abhors to meet him." I (''Aishah) said: "O Messenger of Allah! So far as the feelings of aversion against death is concerned, we all have this feeling." Thereupon he said, "I do not mean that. What I meant is that when a (true) believer is given the glad tidings of the Mercy of Allah, His Pleasures and His Jannah (at the time of death), he loves to meet Allah, and Allah also loves to meet him. When a disbeliever is given the news of the Torment of Allah and His Wrath (at the time of death), he dislikes to meet Allah and Allah also abhors to meet him.".', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1848', 'Riyad as-Salihin 1848', 'ریاض الصالحین 1848', 'رواه مسلم', 'أن النبي صلى الله عليه وسلم قال: (من أحب لقاء الله أحب الله لقاءه ومن كره لقاء الله كره الله لقاءه) فسألت عائشة رضي الله عنها : هل تعني بذلك كراهية الموت يا رسول الله، فكلنا يكره الموت؟ قال: (ليس كذلك) فأخبر النبي صلى الله عليه وسلم أن الإنسان إذا أحب لقاء الله أحب الله لقاءه، وذلك أن المؤمن يؤمن بما أعد الله للمؤمنين في الجنة من الثواب الجزيل والعطاء العميم الواسع فيحب ذلك وترخص عليه الدنيا ولا يهتم بها؛ لأنه سوف ينتقل إلى خير منها، فحينئذ يحب لقاء الله، ولاسيما عند الموت إذا بُشِّر بالرضوان والرحمة فإنه يحب لقاء الله عز وجل ، ويشتاق إليه، فيحب الله لقاءه، أما الكافر والعياذ بالله فإنه إذا بشر بعذاب الله وسخطه كره لقاء الله فكره الله لقاءه، ولهذا جاء في حديث المحتضر أن نفس الكافر إذا بشرت بالغضب والسخط تفرقت في جسده وأبت أن تخرج، ولهذا تنزع روح الكافر من جسده نزعًا؛ ويُكرَه على أن تخرج روحه؛ وذلك لأنه يبشر والعياذ بالله بالشر، ولهذا قال الله تعالى : (ولو ترى إذ الظالمون في غمرات الموت والملائكة باسطو أيديهم أخرجوا أنفسكم).', 'حب لقاء الله أو كراهية لقائه هي التي تكون عند النزع وخروج الروح في حالة لا تقبل التوبة حيث يبشر كل إنسان بما هو صائر إليه.
كل إنسان يرى مقامه في حالة الاحتضار والنزع.
حب لقاء الله أو كراهية لقائه لا تعني تمني الموت أو كراهيته.
الحث على القيام بالطاعات والدأب عليها والإخلاص فيها، استعدادًا للقاء الله -تعالى-.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8266', false),
(21849, 2, 219, 1849, 'hadith', 'عن أم المؤمنين صفية بن حيي رضي الله عنها قالت: كان النبي صلى الله عليه وسلم معتكفاً، فأتيته أزوره ليلاً، فحدثته ثم قمت لأنقلب، فقام معي ليقلبني، فمر رجلان من الأنصار رضي الله عنهما ، فلما رأيا النبي صلى الله عليه وسلم أسرعا، فقال صلى الله عليه وسلم : على رسلكما إنها صفية بنت حيي فقالا: سبحان الله يا رسول الله! :«إن الشيطان يجري من ابن آدم مجرى الدم، وإني خشيت أن يقذف في قلوبكما شراً أو قال: شيئاً».', 'I came to visit the Prophet (ﷺ) while he was in the state of I''tikaf .', 'أم المؤمنين صفية بن حيي رضي الله عنها', 'Safiyyah bint Huyai (May Allah be pleased with her), the Mother of the Believers, said:', 'صحيح', 'رياض الصالحين 1849', 'Riyad as-Salihin 1849', 'ریاض الصالحین 1849', 'متفق عليه', 'كان النبي صلى الله عليه وسلم معتكفًا في العشر الأواخر من رمضان، فزارته زوجه صَفِيَّةَ رضي الله عنها في إحدى الليالي فحدثته ساعة، ثم قامت لتعود إلى بيتها ، فقام معها يشيعها، ويؤنسها، فمر رجلان من الأنصار، فلما رأيا رسول الله صلى الله عليه وسلم أسرعا في مشيهما حياء من النبي ـصلى الله عليه وسلم ـ حين رأيا معه أهله، فقال لهما على رِسْلِكُمَا، أي: تأنيا في المشي، فإنما هي زوجتي صَفِيَّةَ، فقالا سُبْحَان الله، وهل يتطرق إلى الوهم ظن السوء بك، فأخبرهما: أن الشيطان حريص على إغواء بني آدم، وله قدرة عليهم عظيمة، فإنه يجري منهم مجرى الدم من لطف مداخله، وخَفِيِّ مسالكه، وخشي أن يقذف في قلوبهما شيئًا.', 'مشروعية الاعتكاف، لاسيما في العشر الأواخر من رمضان.
جواز زيارة المعتكف.
المحادثة اليسيرة لا تنافي الاعتكاف، خصوصا لمصلحة، كمؤانسة الأهل مثلا.
جواز خلوة المعتكف بأهله ومحادثتهم، إذا لم يُثِرْ ذلك شهوته المنافية للاعتكاف.
جواز خروج المعتكف من المسجد ليُشيع زائره لحاجة.
حسن خلق النبي -صلى الله عليه وسلم-، إذ آنسها، ثم قام ليشيعها إلى بيتها.
جواز خروج المرأة ليلا لغرض، لكن بشرط أن تؤمن الفتنة.
شدة تعظيم الصحابة -رضي الله عنهم- للنبي -صلى الله عليه وسلم-.
أن الوسوسة الشيطانية لا تؤمن على العبد فإذا كان أصحاب النبي -صلى الله عليه وسلم- لم يؤمن عليهم منها فغيرهم من باب أولى.
مشروعية إخبار المرء بما يدفع سوء الظن به.
تسليط الشيطان على ابن آدم؛ حيث يجري منه مجرى الدم.
مشروعية تسبيح الله تعالى عند التعجب.', 'لأَنْقَلِبَ : لأَرجِع.
لِيَقْلِبَنِي : ليردني ويرجعني إلى منزلي.
على رِسْلِكُمَا : أي تمهلا ولا تسرعا.
فقالا: سُبْحَان الله : تسبيحٌ وردَ مورد التعجب.
خشيت : خفت.
يَقذف : يرمي.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4534', false),
(21850, 2, 219, 1850, 'hadith', 'عن أبي الفضل العباس بن عبد المطلب رضي الله عنه قال: شهدت مع رسول الله صلى الله عليه وسلم يوم حنين فلزمت أنا وأبو سفيان بن الحارث بن عبد المطلب رسول الله صلى الله عليه وسلم فلم نفارقه ورسول الله صلى الله عليه وسلم على بغلة له بيضاء، فلما التقى المسلمون والمشركون ولى المسلمون مدبرين ، فطفق رسول الله صلى الله عليه وسلم ، يركض بغلته قبل الكفار، وأنا آخذ بلجام بغلة رسول الله صلى الله عليه وسلم ،أكفها إرادة أن لا تسرع وأبو سفيان آخذ بركاب رسول الله صلى الله عليه وسلم فقال: رسول الله صلى الله عليه وسلم "أي عباس ناد أصحاب السمرة" قال العباس، وكان رجلاً صيتا فقلت بأعلى صوتي: أين أصحاب السمرة، فوالله لكأن عطفتهم حين سمعوا صوتى عطفة البقر على أولادها، فقالوا: يا لبيك يا لبيك، فاقتتلوا هم والكفار، والدعوة في الأنصار يقولون: يا معشر الأنصار، يا معشر الأنصار، ثم قصرت الدعوة على بني الحارث بن الخزرج، فنظر رسول الله صلى الله عليه وسلم وهو على بغلته كالمتطاول عليها إلى قتالهم فقال: "هذا حين حمي الوطيس" ثم أخذ رسول الله صلى الله عليه وسلم حصيات، فرمى بهن وجوه الكفار، ثم قال: "انهزموا ورب محمد"، فذهبت أنظر فإذا القتال على هيئته فيما أرى، فوالله ما هو إلا أن رماهم بحصياته، فما زلت أرى حدهم كيلاً، وأمرهم مدبراً، ((رواه مسلم)).«الوطيس» التنور، ومعناه: اشتدت الحرب. وقوله: «حدهم» هو بالحاء المهملة: أي بأسهم.', 'I was in the company of the Messenger of Allah (ﷺ) on the day of (the battle of) Hunain. Abu Sufyan bin Al-Harith and I did not leave the Messenger of Allah (ﷺ) throughout the battle. The Messenger of Allah (ﷺ) was riding on his white mule. When the Muslims had an encounter with the pagans, Muslims took to their heels. The Messenger of Allah (ﷺ) began to urge his mule towards the disbelievers, holding the bridle of his mule. I was trying to restrain it from going very fast, and Abu Sufyan was holding the stirrup of the mule of the Messenger of Allah (ﷺ). The Messenger of Allah (ﷺ) said, "O Abbas! Call out the People of As-Samurah .', 'أبي الفضل العباس بن عبد المطلب رضي الله عنه', 'Al-''Abbas bin ''Abdul-Muttalib (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1850', 'Riyad as-Salihin 1850', 'ریاض الصالحین 1850', null, 'عن أبي الفضل العباس بن عبد المطلب رضي الله عنه قال: شهدت مع رسول الله صلى الله عليه وسلم غزوة حنين، فلما التقى المسلمون والكفار ووقع القتال الشديد فيما بينهم ولى بعض المسلمين من المشركين مدبرين، فشرع رسول الله صلى الله عليه وسلم يحرك بغلته برجله جهة الكفار، وأنا آخذ بلجام بغلة رسول الله صلى الله عليه وسلم أمنعها لئلا تسرع إلى جانب العدو، وأبو سفيان ماسك بركاب رسول الله صلى الله عليه وسلم فقال رسول الله صلى الله عليه وسلم : يا عباس، ناد أصحاب السمرة وهي الشجرة التي بايعوا تحتها يوم الحديبية، في السنة السادسة، -وكان العباس رجلا قوي الصوت- فناديت بأعلى صوتي: يا أصحاب السمرة؟ -أي: لا تنسوا بيعتكم الواقعة تحت الشجرة وما يترتب عليها من الثمرة- فقال: والله حينما سمعوا صوتي أنادي عليهم أتوا مسرعين كما تُسرع قطيع البقر إذا غابت عنها أولادها، فقالوا بأجمعهم أو واحد بعد واحد: يا لبيك يا لبيك، فاقتتل المسلمون والكفار، والنداء في حق الأنصار: يا معشر الأنصار يا معشر الأنصار.
ثم اقتصرت الدعوة وانحصرت على بني الحارث بن الخزرج فنودي: يا بني الحارث، وهم قبيلة كبيرة، فنظر رسول الله صلى الله عليه وسلم وهو على بغلته، وكأن عنقه اشرأبت مرتفعة إلى قتال هؤلاء الكافرين، فقال: هذا الزمان زمان اشتداد الحرب، ثم أخذ حصيات فرمى بهن وجوه الكفار، ثم قال صلى الله عليه وسلم تفاؤلًا أو إخبارًا: انهزَموا ورب محمد. فذهبت أنظر فإذا القتال على هيئته فيما أرى، فوالله ما هو إلا أن رماهم بحصياته، فما زلت أرى بأسهم ضعيفًا، وحالهم ذليلًا.', 'الدلالة على شجاعة رسول الله -صلى الله عليه وسلم- وإقدامه في الحروب.
بيان سرعة رجوع المسلمين إلى الحق عند تذكيرهم به.
المسلمون لم ينهزموا بعيدا؛ لأن رجوعهم كان سريعا.
معجزة لرسول الله -صلى الله عليه وسلم-، إذ ليس في القوة البشرية إيصال حصيات إلى أعينهم جميعًا ولا يسع كفه الشريف حصى بعددهم.
القوة الحقيقية ليست في العدد والعُدد، وإنما في الإيمان بالله -تعالى- وشدة التوكل عليه.
بيان فضل ومكانة الأنصار -رضي الله عنهم-.', 'يوم حنين : حنين واد بين الطائف ومكة المكرمة، وفيه وقعت غزوة حنين في شوال 8 هـ.
يركض بغلته : يضربها برجله الشريفة لتسرع.
قِبَل : جهة.
أَكُفُّها : أمنعها.
أصحاب السمرة : أصحاب بيعة الرضوان وكانت عند شجر من شجر السمر.
رجل صيت : قوي الصوت عاليه.
عطفتهم : إقبالهم ورجوعهم.
عطفة البقر : تشبيه سرعة رجوعهم واجتماعهم على النبي بإقبال البقر على أولادها.
يا معشر : المعشر الجماعة من الرجال.
والدعوة في الأنصار : الاستعانة والمناداة لهم.
المتطاول : الذي يتمدد قائمًا لينظر إلى الحرب، أو يمد عنقه ليراه أو يطلع إليه.
الوطيس : التنور، ومعناه: اشتدت الحرب.
حدهم : بأسهم.
كليلًا : ضعيفًا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8267', false),
(21851, 2, 219, 1851, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «يا أيها الناس إن الله طيب لا يقبل إلا طيباً، وإن الله أمر المؤمنين بما أمر به المرسلين، فقال تعالى: {يا أيها الرسل كلوا من الطيباب واعلموا صالحاً}، وقال تعالى: {يا أيها الذين آمنوا كلوا من طيبات ما رزقناكم} ثم ذكر الرجل يطيل السفر أشعث أغبر يمد يديه إلى السماء : يا رب يارب، ومطعمه حرام، ومشربه حرام، وملبسه حرام، وغذي بالحرام فأنى يستجاب لذلك!؟».', 'The Messenger of Allah (ﷺ) said, "O people! Allah is Pure and, therefore, accepts only that which is pure. Allah has commanded the believers as He has commanded His Messengers by saying: ''O Messengers! Eat of the good things, and do good deeds.'' (23:51) And He said: ''O you who believe (in the Oneness of Allah - Islamic Monotheism)! Eat of the lawful things that We have provided you..."'' (2:172). Then he (ﷺ) made a mention of the person who travels for a long period of time, his hair are dishevelled and covered with dust. He lifts his hand towards the sky and thus makes the supplication: ''My Rubb! My Rubb!'' But his food is unlawful, his drink is unlawful, his clothes are unlawful and his nourishment is unlawful, how can, then his supplication be accepted?".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1851', 'Riyad as-Salihin 1851', 'ریاض الصالحین 1851', 'رواه مسلم', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ الله طيب قُدُّوس مُنَزَّهٌ عن النقائص والعيوب ومُتَّصِف بالكَمَالات، ولا يقبل من الأعمال والأقوال والاعتقادات إلا ما كان طيبًا، وهو الخالص لله، الموافق لهدي النبي صلى الله عليه وسلم، ولا ينبغي أن يتقرب إلى الله إلا بذلك، ومن أعظم ما يَحصُل به طِيْبة الأعمال للمؤمن طِيْبُ مَطعَمِه، وأن يكون من حلال، فبذلك يَزكُو عملُه، ولذا أمر الله المؤمنين بالذي أمر به المرسلين من أكل الحلال وعمل الصالحات، فقال: {يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا، إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ} وقال: {يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ}.
ثم حَذَّرَ صلى الله عليه وسلم من أكل الحرام الذي يُفسِد العمل ويَمنع قبولَه مهما بَذل من أسباب القبول الظاهرة؛ منها:
أولًا: إطالة السفر في وجوه الطاعات كحج وجهاد وصلة رحم وغير ذلك.
ثانيًا: مُتفرِّق الشعر لعدم تمشيطه، مُتغيِّر لونه ولون ثيابه من التراب، فهو مضطر.
ثالثًا: يرفع يديه إلى السماء بالدعاء.
رابعًا: يتوسل إلى الله بأسمائه ويُلِحُّ في ذلك: يا رب يا رب!
ومع هذه الأسباب لإجابة الدعاء لم يسمع له؛ وذلك لأن مَطعومَه ومشروبَه وملبوسَه حرام، وغذي بالحرام، فبعيد أن يستجاب لمن هذه صفته، وكيف يستجاب له؟!', 'كمال الله عزّ وجل في ذاته، وصفاته، وأفعاله، وأحكامه.
الأمر بإخلاص العمل لله عز وجل، والمتابعة للنبي صلى الله عليه وسلم.
استعمال ما يُشجِّع على العمل، حيث قال النبي صلى الله عليه وسلم: "إِنَّ الله أَمَرَ المُؤمنينَ بِمَا أَمَرَ بِهِ المُرسَلِيْنَ"، فإذا علم المؤمن أن هذا من مأمورات المرسلين فإنه يتقوَّى ويتشجّع على الامتثال.
من موانع استجابة الدعاء أكل الحرام.
من أسباب إجابة الدعاء خمسة أشياء: أحدها: إطالة السفر لما فيه من الانكسار الذي هو من أعظم أسباب الإجابة، الثاني: حالة الإضطرار، الثالث: مَدُّ اليدين إلى السماء، الرابع: الإلحاح على الله بتكرير ذكر ربوبيته، وهو من أعظم ما يُطلَب به إجابة الدعاء، الخامس: إطابة المأكل والمشرب.
أكل الحلال الطيِّب من الأسباب المُعينة للعمل الصالح.
قال القاضي: الطيب ضد الخبيث، فإذا وصف به تعالى أريد به أنه مُنزَّه عن النقائص مُقدَّس عن الآفات، وإذا وُصِف به العبد مطلقًا أريد به أنه المُتعرِّي عن رذائل الأخلاق وقبائح الأعمال والمتحلي بأضداد ذلك، وإذا وُصف به الأموال أريد به كونه حلالًا من خيار الأموال.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66518', false),
(21852, 2, 219, 1852, 'hadith', 'وعنه رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ثلاثة لا يكلمهم الله يوم القيامة، ولا يزكيهم، ولا ينظر إليهم ، ولهم عذاب أليم: شيخ زان، وملك كذاب، وعائل مستكبر» ((رواه مسلم)). (4)', 'The Messenger of Allah (ﷺ) said, "There are three (types of) people whom Allah will neither speak to on the Day of Resurrection nor will He purify them (i.e., from their sins), nor will look upon them; and they will have a painful chastisement. These are: An old man who commits fornication; a king who is a great liar and a poor man who is proud."', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1852', 'Riyad as-Salihin 1852', 'ریاض الصالحین 1852', null, 'ثلاثة أصناف من الناس لا يكلمهم الله يوم القيامة، ولا ينظر إليهم، ولا يطهرهم من ذنوبهم، ولهم عذاب أليم:
رجل كبير طعن في السن يزني، وإمام يكذب، وفقير يستكبر ويحتقر غيره.', 'إثبات صفة الكلام لله -تعالى-، على الوجه اللائق به سبحانه، لا كما يتأوله بعضهم قائلاً لا يكلمهم لا يظهر الرضى عنهم.
الزنا والكذب والكبر من الذنوب الكبيرة.
إذا وقعت المعصية ممن انتفت عنه دواعيها كانت أكبر وأعظم.
إثبات صفة النظر لله -سبحانه- على ما يليق بجلاله وعظمته.', 'لا يزكيهم : لا يطهرهم من الذنوب، ولا يقبل أعمالهم فيمدحهم بها.
شيخ : من طعن في السن.
عائل : فقير.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5910', false),
(21853, 2, 219, 1853, 'hadith', 'وعنه رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «سيحان وجيحان والفرات والنيل كل من أنهار الجنة».', 'The Messenger of Allah (ﷺ) said, "Saihan (Oxus), Jaihan (Jaxartes), Al-Furat (Euphrates) and An-Nil (Nile) are all from the rivers of Jannah.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1853', 'Riyad as-Salihin 1853', 'ریاض الصالحین 1853', 'رواه مسلم', 'سيحان وجيحان، والفرات والنيل أربعة أنهار في الدنيا وصفها النبي صلى الله عليه وسلم بأنها من أنهار الجنة؛ فقال بعض أهل العلم: إنها من أنهار الجنة حقيقة لكنها لما نزلت إلى الدنيا غلب عليها طابع أنهار الدنيا وصارت من أنهار الدنيا.', 'يؤخذ هذا الحديث على ظاهره، وعلى حقيقته، والله أعلم بأسراره في خلقه.
الجنة مخلوقة موجودة.
هذه الأنهار مباركة ميمونة.', 'سيحان وجيحان : نهران ببلاد الأرمن وهما عظيمان جدًا.
الفرات. : نهر يفصل بين الشام والجزيرة.
النيل. : نهر مصر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8268', false),
(21854, 2, 219, 1854, 'hadith', 'وعنه قال: أخذ رسول الله صلى الله عليه وسلم بيدي فقال: «خلق الله التربة يوم السبت، وخلق فيها الجبال يوم الأحد، وخلق الشجر يوم الأثنين وخلق المكروه يوم الثلاثاء، وخلق النور يوم الأربعاء، وبث فيها الدواب يوم الخميس، وخلق آدم صلى الله عليه وسلم بعد العصر من يوم الجمعة في آخر الخلق في آخر ساعة من النهار فيما بين العصر إلى الليل».', 'The Messenger of Allah (ﷺ) took hold of my hand and said, "Allah, the Exalted and Glorious, created the earth on Saturday, the mountains on Sunday, the trees on Monday, the things entailing labour on Tuesday, light on Wednesday, He spread out animals of all kinds on Thursday, and created Adam in the afternoon on Friday, and it was the last hour of Friday between the afternoon and the night.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1854', 'Riyad as-Salihin 1854', 'ریاض الصالحین 1854', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21855, 2, 219, 1855, 'hadith', 'عن أبي سليمان خالد بن الوليد رضي الله عنه قال: «لقد انقطعت في يدي يوم مؤته تسعة أسياف، فما بقي في يدي إلا صفيحة يمانية».', 'In the battle of Mu''tah, seven swords were broken in my hand, and all that remained with me was a Yemeni sword..', 'أبي سليمان خالد بن الوليد رضي الله عنه', 'Abu Sulaiman Khalid bin Al-Walid (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1855', 'Riyad as-Salihin 1855', 'ریاض الصالحین 1855', 'رواه البخاري', 'خالد بن الوليد رضي الله عنه سيف الله، وفارس الإسلام، وليث المشاهد، وقائد المجاهدين، كان من أشراف قريش في الجاهلية، أسلم قبل فتح مكة، وكان في غزوة أحد في جيش قريش المشركين ثم أسلم، وفي هذا دليل على كمال قدرة الله عز وجل ؛ وأنه بيده أَزِمَّة الأمور، وأنه يضل من يشاء ويهدي من يشاء، وهو يخبر عن تكسر الأسياف التسعة في يده في مؤتة، في السنة الثامنة من الهجرة، وهذا من شجاعته رضي الله عنه ، ولم يصمد معه إلا سيف عريض من سيوف اليمن.', 'فضل وشجاعة خالد بن الوليد -رضي الله عنه- وقوة بأسه، وثباته في الحروب.
كثرة القتلى من الروم في معركة مؤتة وإلا لما انقطع في خالد تسعة أسياف.
فضل الجهاد في سبيل الله -تعالى-.', 'مؤتة : موضع بقرب الشام كانت فيها غزوة مؤتة.
صفيحة : سيف يماني.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8407', false),
(21856, 2, 219, 1856, 'hadith', 'عن عمرو بن العاص رضي الله عنه سمع رسول الله صلى الله عليه وسلم يقول: «إذا حكم الحاكم، فاجتهد، ثم أصاب، فله أجران، وإن حكم واجتهد، فأخطأ، فله أجر».', 'I heard the Messenger of Allah (ﷺ) saying, "When a judge utilizes his skill of judgement and comes to a right decision, he will have a double reward, but when he uses his judgement and commits a mistake, he will have a single reward."', 'عمرو بن العاص رضي الله عنه', '''Amr bin ''Al-''As (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1856', 'Riyad as-Salihin 1856', 'ریاض الصالحین 1856', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21857, 2, 219, 1857, 'hadith', 'عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم قال: «الحمى فيح جهنم فأبردوها بالماء».', 'The Prophet (ﷺ) said, "Fever comes from the vehement raging of Hell, so cool it with water.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1857', 'Riyad as-Salihin 1857', 'ریاض الصالحین 1857', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21858, 2, 219, 1858, 'hadith', 'وعنها رضي الله عنها عن النبي صلى الله عليه وسلم قال: «من مات وعليه صوم، صام عنه وليه».', 'The Prophet (ﷺ) said, "If a person dies without observing Saum (fasts), his Wali should make it up on his behalf.".', null, '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1858', 'Riyad as-Salihin 1858', 'ریاض الصالحین 1858', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21859, 2, 219, 1859, 'hadith', 'عن عوف بن مالك بن الطفيل أن عائشة رضي الله عنها حدثت أن عبد الله بن الزبير رضي الله عنهما قال في بيع أو عطاء أعطته عائشة رضي الله عنها: والله لتنتهين عائشة، أو لأحجرن عليها، قالت أهو قال هذا ؟ قالو: نعم، قالت: هو لله علي نذر أن لا أكلم ابن الزبير أبدا، فاستشفع بن الزبير إليها حين طالت الهجرة، فقالت: لا والله لا أشفع فيه أبداً، ولا أتحنث إلى نذري فلما طال ذلك على ابن الزبير كلم المسور ابن مخرمة، وعبد الرحمن بن الأسود بن عبد يغوث وقال لهما: أنشدكما الله لما أدخلتماني على عائشة رضي الله عنها، فإنها لا يحل لها أن تنذر قطيعتى، فأقبل به المسور، وعبد الرحمن حتى استأذنا على عائشة، فقالا: السلام عليك ورحمة الله وبركاته، أندخل؟ قالت عائشة: ادخلوا، قالوا: كلنا؟ قالت: نعم ادخلوا كلكم، ولا تعلم أن معهما ابن الزبير، فلما دخلوا ، دخل ابن الزبير الحجاب، فاعتنق عائشة رضي الله عنها، وطفق يناشدها ويبكي، وطفق المسور، وعبد الرحمن يناشدانها إلا كلمته وقبلت منه، ويقولان : إن النبي صلى الله عليه وسلم نها عما قد علمت من الهجرة، ولا يحل لمسلم أن يهجر أخاه فوق ثلاث ليال، فلما أكثروا على عائشة من التذكرة والتحريج، طفقت تذكرهما وتبكي ، وتقول: إني نذرت والنذر شديد ، فلم يزالا بها حتى كلمت ابن الزبير، وأعتقت في نذرها ذلك أربعين رقبة، وكانت تذكر نذرها بعد ذلك فتبكي حتى تبل دموعها خمارها.', '''Aishah (May Allah be pleased with her) as told that ''Abdullah bin Az-Zubair (May Allah be pleased with them) had said in respect of selling of a gift which was presented to her: "By Allah! If ''Aishah does not stop this kind of thing, I will declare her incompetent to administer her property." ''Aishah (May Allah be pleased with her) asked: "Did He (''Abdullah bin Az-Zubair) say so?" The people said: "Yes." ''Aishah (May Allah be pleased with her) said: "I vow it before Allah that I will never speak to Ibn Az-Zubair." When this desertion lasted long, ''Abdullah bin Az-Zubair sought intercession with her, but she said: "By Allah I will not accept the intercession of anyone for him, and I will not commit a sin of breaking my vow." When this state of affairs was prolonged, Ibn Az-Zubair felt it hard on him. He said to Al-Miswar bin Makhramah and ''Abdur-Rahman bin Al-Aswad bin Yaghut: "I beseech you in the Name of Allah that you should take me to ''Aishah because it is unlawful for her to vow to sever relations with me." So Al-Miswar and ''Abdur-Rahman took him with them. They sought her permission, saying: "As-salamu ''alaika wa rahmatullahi wa barakatuhu! Shall we come in?" ''Aishah (May Allah be pleased with her) said: "Come in," They asked: "All of us?" She said: "All of you," not knowing that Ibn Az-Zubair was also with them. So, when they entered, Ibn Az-Zubair entered the screened place and got hold of ''Aishah (May Allah be pleased with her), his aunt. He was requesting her to forgive him and wept. Al-Miswar and ''Abdur-Rahman also pleaded on his behalf and requested her to speak to him and to accept his repentance. They said to her: "The Prophet (ﷺ) forbade to cut off relationship because it is unlawful for any Muslim not to talk to his (Muslim) brother (or sister, for that matter) for more than three (days)." So when they persisted in urging and reminding her of the superiority of having good relation with kith and kin, she began to weep, saying: "I have made a vow which is a matter of very serious nature." They persisted in their appeal till she spoke with ''Abdullah bin Az-Zubair, and she freed forty slaves as an expiation for breaking her vow. Later on, whenever she remembered her vow, she would weep so much that her veil would become wet with tears..', 'عوف بن مالك بن الطفيل أن عائشة رضي الله عنها', '''Auf bin Malik (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1859', 'Riyad as-Salihin 1859', 'ریاض الصالحین 1859', 'رواه البخاري', 'سمع عبد الله بن الزبير رضي الله عنهما أن عائشة رضي الله عنها تبرعت وأعطت عطايا كثيرة، فاستكثر ذلك منها وقال: لئن لم تنته لأمنعنها من التصرف في مالها. وهذه كلمة شديدة بالنسبة لأم المؤمنين عائشة رضي الله عنها ؛ لأنها خالته وعندها من الرأي والعلم والحلم والحكمة ما لا ينبغي أن يقال فيها ذلك القول، فسمعت رضي الله عنها بذلك وأُخبرت به أخبرها بذلك الواشون الذين يشون بين الناس ويفسدون بينهم بالنميمة، فلما وصلت هذه الكلمة إلى عائشة نذرت رضي الله عنها ألا تكلمه أبدًا؛ وذلك لشدة ما حصل لها من الانفعال على ابن أختها، وهجرتْه، ومن المعلوم أن هجر أم المؤمنين رضي الله عنها لابن أختها سيكون شديدًا عليه، فحاول أن يسترضيها، ولكنها صممت لأنها ترى أن النذر شديد، فاستشفع إليها برجلين من أصحاب رسول الله صلى الله عليه وسلم ، وفَعلا حيلةً بأم المؤمنين لكنها حيلة حسنة؛ لأنها أدت إلى مطلوب حسن، وهو الإصلاح بين الناس، فاستأذنا على عائشة رضي الله عنها فسلما عليها، ثم استأذناها في الدخول فقالا: ندخل. قالت: نعم. قالوا: كلنا. قالت: كلكم. ولم تعلم أن عبد الله بن الزبير معهما، لكنها لم تقل هل معكم عبد الله بن الزبير، فلم تستفصل وأتت بقول عام: ادخلوا كلكم، فدخلوا فلما دخلوا عليها وإذا عليها حجاب أمهات المؤمنين وهو عبارة عن ستر تستتر به أمهات المؤمنين لا يراهن الناس، وهو غير الحجاب الذي يكون لعامة النساء؛ لأن الحجاب الذي لعامة النساء هو تغطية الوجه والبدن، ولكن هذا حجاب يكون حاجبًا وحائلا بين أمهات المؤمنين والناس، فلما دخلا البيت دخل عبد الله بن الزبير الحجاب لأنه ابن أختها فهي من محارمه، فأكب عليها يقبلها ويبكي ويناشدها الله عز وجل ويحذرها من القطيعة ويبين لها أن هذا لا يجوز؛ لكنها قالت النذر شديد ثم إن الرجلين أقنعاها بالعدول عما صممت عليه من الهجر وذكراها بحديث النبي صلى الله عليه وسلم أنه لا يحل للمؤمن أن يهجر أخاه فوق ثلاث حتى اقتنعت وبكت وكلمت عبد الله بن الزبير، ولكن هذا الأمر أهمها جدًا، فكانت كلما ذكرته بكت رضي الله عنها ؛ لأنه شديد، وقد أعتقت أربعين عبدًا من أجل هذا النذر ليعتق الله تعالى رقبتها من النار، وذلك من مزيد ورعها، وإلا فالواجب رقبة واحدة.', 'جواز الهجر إذا كان لله -تعالى-، ويحرم فوق ثلاث ليال إذا كان لأمر دنيوي وحظ نفسي.
بيان كيفية الاستئذان وأدبه في قوله: السلام عليك ورحمة الله وبركاته، أندخل؟
جواز اصطحاب ضيف زائر فإن أذن له بالدخول دخل وإن لم يؤذن له رجع.
المؤمنون إخوة؛ فينبغي الإصلاح بين المتخاصمين منهم.
من نذر فرأى غيره أفضل منه، فليأت الذي هو خير، وليكفر عن يمينه.
جواز الحيل إذا لم تصل إلى شيء محرم؛ لأن عائشة -رضي الله عنها- تحيل عليها الرجلان في الدخول عليها ومعهما عبد الله بن الزبير، للإصلاح بينهم.
رقة قلوب الصحابة وسرعة بكائهم -رضي الله عنهم- من خشية الله -عز وجل- وهذا دليل على لين القلب وخشيته لله.
قوة إيمان أمهات المؤمنين وحرصهن على العتق من النار والبراءة من العذاب.', 'لأحجرن عليها : لأمنعنَّها من التصرف في مالها.
لا أُشفَّع فيه أبدًا : لا أقبل شفاعة أحد له.
لا أتحنث إلى نذري : لا أكتسب الإثم بسبب الحنث في نذري.
أنشدكما الله : أسألكما مقسمًا عليكما بالله -تعالى-.
طفق : أخذ.
يناشدها : يسألها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8409', false),
(21860, 2, 219, 1860, 'hadith', 'عن عقبة بن عامر رضي الله عنه أن رسول الله صلى الله عليه وسلم خرج إلى قتلى أحد، فصلى عليهم بعد ثمان سنين كالمودع للأحياء والأموات، ثم طلع إلى المنبر ، فقال: إني بين أيديكم فرط وأنا شهيد عليكم، وإن موعدكم الحوض ، وإني لأنظر إليه من مقامي هذا، وإني لست أخشى عليكم أن تشركوا، ولكن أخشى عليكم الدنيا أن تنافسوها" قال: فكانت آخر نظرة نظرتها إلى رسول الله صلى الله عليه وسلم . ((متفق عليه)). وفي رواية : "ولكني أخشى عليكم الدنيا أن تنافسوا فيها ، وتقتتلوا فتهلكوا كملا هلك من كان قبلكم" قال عقبة: فكان آخر ما رأيت رسول الله صلى الله عليه وسلم على المنبر. وفي رواية قال: «إني فرط لكم وأنا شهيد عليكم وإني والله لأنظر إلى حوضي الآن، وإني أعطيت مفاتيح خزائن الأرض، أو مفاتيح الأرض، وإني والله ما أخاف عليكم أن تشركوا بعدي، ولكن أخاف عليكم أن تنافسوا فيها» . والمراد بالصلاة على قتلى أحد: الدعاء لهم، لا الصلاة المعروفة.', 'One day the Messenger of Allah (ﷺ) went out and asked Allah''s forgiveness for the martyrs of the battle of Uhud after eight years. It seemed that by so doing, he bid farewell to the living and the dead. He then came back, rose to the pulpit and said, "I shall be your precursor; I am a witness for you (before Allah), and I will be present before you at the River (Haud Al-Kauthar). By Allah I can see with my own eyes the Haud from this place. I am not afraid that you will associate anything with Allah in worship after (my demise), but I apprehend that you will vie with one another for the life of the world." The narrator said: It was the last time that I saw the Messenger of Allah (ﷺ)..There are some more narrations with very minor changes in its wording.', 'عقبة بن عامر رضي الله عنه', '''Uqbah bin ''Amir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1860', 'Riyad as-Salihin 1860', 'ریاض الصالحین 1860', null, 'خرج رسول الله صلى الله عليه وسلم إلى أحد فدعا للشهداء هناك، وكان هذا بعد ثمان سنين من الغزوة، ثم صعد المنبر صلى الله عليه وسلم وخطب الناس كالمودع لهم، وأخبر أنه يرى حوضه وأنه سيسبقهم إليه، وأنه شهيد عليهم، وأخبر أن أمته ستملك خزائن الأرض، وأخبر صلى الله عليه وسلم أنه لا يخشى على أمته الشرك، ولكنه خشي شيئا آخر الناس أسرع إليه وهو أن تفتح الدنيا على الأمة فيتنافسوها ويتقاتلوا عليها فتهلكهم كما أهلكت من قبلهم.
يقول عقبة رضي الله عنه : وكانت تلك المرة آخر مرة رأى رسول الله صلى الله عليه وسلم على المنبر.', 'بيان بعض معجزات رسول -صلى الله عليه وسلم- حيث عاين حوضه الشريف من مقامه في الدنيا.
التنافس على زهرة الحياة الدنيا مضر بالدين مفرق للشمل.
بشارة بدوام الإسلام وثبات غالب المسلمين عليه.
جواز توديع من شعر بقرب أجله لإخوانه وأصحابه.
إثبات حوض النبي -صلى الله عليه وسلم- المورد وأنه موجود.
استحباب زيارة القبور والدعاء لأهلها؛ فإنها تذكرة بالآخرة.', 'فرط : سابق لكم.
تنافسوها : التنافس: الرغبة في الشيء ومحبة الانفراد به والمبالغة فيه.
أُحد : الجبل الذي كانت عنده غزوة أحد قرب المدينة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8410', false),
(21861, 2, 219, 1861, 'hadith', 'عن أبي زيد عمرو بن أخطب الأنصاري رضي الله عنه قال: صلى بنا رسول الله صلى الله عليه وسلم الفجر، وصعد المنبر، فخطبنا حتى حضرت الظهر، فنزل فصلى، ثم صعد المنبر حتى حضرت العصر، ثم نزل فصلى، ثم صعد المنبر حتى غربت الشمس، فأخبرنا ما كان هو كائن، فأعلمنا أحفظنا.', 'The Messenger of Allah (ﷺ) led us in the morning (Fajr) prayer and he ascended the pulpit and addressed us until it was the time for the Zuhr prayer. He then came down the pulpit and led us in Salat (prayer). Again he ascended the pulpit and addressed until it was the time for the ''Asr prayer. He then again came down, led us in Salat and again ascended the pulpit and addressed us until sunset. He informed us of everything that lay hidden in the past and what will happen in the future; and the most learned amongst us is the one who has preserved it in his memory..', 'أبي زيد عمرو بن أخطب الأنصاري رضي الله عنه', 'Abu Zaid ''Amr bin Akhtab Al-Ansari (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1861', 'Riyad as-Salihin 1861', 'ریاض الصالحین 1861', 'رواه مسلم', 'يخبر الصحابي عمرو بن أخطب رضي الله عنه أن النبي صلى الله عليه وسلم صلى الفجر ذات يوم، وصعد المنبر وخطب الناس حتى أذن الظهر، ثم نزل فصلى الظهر، ثم عاد فصعد المنبر وخطب حتى أذن العصر، فنزل وصلى العصر، ثم صعد المنبر فخطب حتى غابت الشمس، يعني بذلك أنه خطب يومًا كاملًا من صلاة الفجر إلى غروب الشمس، أعلمه الله عز وجل في ذلك اليوم شيئا من علوم الغيب الماضية، ومن الغيوب المستقبلة، وأخبر بها صلى الله عليه وسلم أصحابه، فأعلمهم بما قال ذلك اليوم هو من حفظ ورسخ ذلك في ذهنه.', 'شدة حرص رسول الله -صلى الله عليه وسلم- على تعليم أمته أمور دينهم.
شهادة من الصحابة الكرام -رضي الله عنهم- أن رسول الله -صلى الله عليه وسلم- بلغ الرسالة وأدى الأمانة، ونصح الأمة.
تفاوت الناس في الحفظ والفهم.
قوة تحمل النبي -صلى الله عليه وسلم-.', 'فأعلمنا أحفظنا : أكثرنا علمًا بما قاله -صلى الله عليه وسلم- في ذلك اليوم أقدرنا على الحفظ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8411', false),
(21862, 2, 219, 1862, 'hadith', 'عن عائشة رضي الله عنها قالت: قال النبي صلى الله عليه وسلم : من نذر أن يطيع الله فليطعه ومن نذر أن يعصي الله فلا يعصه".', 'The Prophet (ﷺ) said, "He who vows to obey Allah, should obey Him. But he who vows to disobey Allah, should not disobey Him.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1862', 'Riyad as-Salihin 1862', 'ریاض الصالحین 1862', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21863, 2, 219, 1863, 'hadith', '-وعن أم شريك رضي الله عنها أن رسول الله صلى الله عليه وسلم أمرها بقتل الأوزاغ وقال: «كان ينفخ على إبراهيم».', 'The Messenger of Allah (ﷺ) ordered me to kill chameleon. He also said, "It blew (fire) on Prophet Ibrahim..', null, 'Umm Sharik (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1863', 'Riyad as-Salihin 1863', 'ریاض الصالحین 1863', 'متفق عليه', 'أمر النبي صلى الله عليه وسلم بقتل الوزغ، وأخبر أنه كان ينفخ النار على إبراهيم من أجل أن يشتد لهبها؛ مما يدل على عداوته التامة لأهل التوحيد والإخلاص، وكل ما أُمر بقتله لم يجز أكله.', 'الحث على قتل الأوزاغ وعدم تركها مع القدرة على قتلها.
بيان العلة التي دعت إلى الأمر بقتل الأوزاغ، وأنها كانت تنفخ النار على أبي الأنبياء إبراهيم الخليل -عليه الصلاة والسلام- عندما ألقي فيها.
ينبغي قتل كل ضار للمسلمين.', 'الأوزاغ : جمع وزغ وهو حشرة مؤذية تتسلق الجدران.
ينفخ على إبراهيم . : أي النار.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8412', false),
(21864, 2, 219, 1864, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "من قتل وزغة في أول ضربة فله كذا وكذا حسنة،ومن قتلها في الضربة الثانية، فله كذا وكذا حسنة، ودون الأول وإن قتلها في الضربة الثالثة، فله كذا وكذا حسنة" ((رواه مسلم)). وفي رواية: "من قتل وزغاً في أول ضربة، كتب له مائة حسنة، وفى الثانية دون ذلك، وفى الثالثة دون ذلك" ((رواه مسلم)). قال أهل اللغة: «الوزغ» العظام من سام أبرص.', 'The Messenger of Allah (ﷺ) said, "He who kills a chameleon at the first blow, such and such number of good deeds will be awarded to him; whoever kills it at the second blow, such and such number of merits will be recorded for him. And if he kills it at the third blow, he will get such and such merits."Another narration is: The Messenger of Allah (ﷺ) said, "If anyone kills a chameleon with the first blow, a hundred good deeds will be recorded for him; less than that will be recorded for him if he kills it at the second blow, and still less rewards will be recorded for him if he kills it at the third blow.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1864', 'Riyad as-Salihin 1864', 'ریاض الصالحین 1864', null, 'حث النبي صلى الله عليه وسلم على قتل الوزغ ورغب فيه؛ فأخبر أن من قتله في الضربة الأولى كتب له مائة حسنة، ومن قتله في الضربة الثانية فله أقل من ذلك، ومن قتله في الثالثة فله أقل من ذلك، والحكمة من قتلها أنها كانت تنفخ النار على إبراهيم -عليه السلام- وأنها ضارة سامة.', 'ينبغي قتل كل ضار للمسلمين.
بيان أجر من قتل وزغة بضربة واحدة أو اثنتين أو ثلاثة، وأن ذلك الأجر يتناقص كلما زادت الضربات، وفي هذا دلالة على سرعة التخلص منها وعدم إمهالها.', 'الوزغ. : حيوان صغير مؤذي يشبه الضب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8413', false),
(21865, 2, 219, 1865, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: « قال رجل لأتصدقن بصدقة، فخرج بصدقته، فوضعها في يد سارق، فأصبحوا يتحدثون: تصدق على سارق! فقال: اللهم لك الحمد لأتصدقن بصدقة، فخرج بصدقته، فوضعها في يد زانية؟! فأصبحوا يتحدثون: تصدق على زانية فقال: اللهم لك الحمد على زانية، لأتصدقن بصدقة، فخرج بصدقته، فوضعها في يد غني, فأصبحوا يتحدثون! تصدق الليلة على غني, فقال: اللهم لك الحمد على سارق ، وعلى زانية، وعلى غني! فأتى فقيل له: أما صدقتك على سارق، فلعله أن يستعف عن سرقته، وأما الزانية فلعلها تستعف عن زناها، وأما الغني فلعله أن يعتبر، فينفق مما آتاه الله».', 'The Messenger of Allah (ﷺ) said: "A man (from amongst the people before you) said: ''Indeed! I will give in charity.'' So he took his Sadaqah out and placed it in a thief''s hand. In the morning the people were talking (about this incident) and saying: ''Sadaqah was given to a thief last night.'' The man said: ''O Allah! Praise be to You. I have given Sadaqah to a thief. Indeed, I will give in charity!'' So he took his Sadaqah out and he placed it in a prostitute''s hand. In the morning the people were talking (about this incident) and saying: ''Sadaqah was given to a prostitute last night.'' On hearing this, the man said: ''Praise be to You, O Allah! I gave Sadaqah to a prostitute. Indeed, I will give in charity!'' So he took his Sadaqah out and placed it in a rich man''s hand. In the morning the people were talking (about this incident) and saying: ''Sadaqah was given to a rich man last night.'' The man said: ''O Allah! Praise be to You (for helping me) give charity to a thief, a prostitute and a rich man.'' Then he had a dream in which he was told that his Sadaqah to the thief might result in his refraining from his theft, his Sadaqah to the prostitute might help her abstain from her immorality, and his Sadaqah to the rich man might help him pay heed and spend from what Allah had bestowed upon him.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1865', 'Riyad as-Salihin 1865', 'ریاض الصالحین 1865', 'رواه البخاري بلفظه، ومسلم بمعناه', 'يخبرنا النبي صلى الله عليه وسلم بخبر من أخبار الأمم المضية لأخذ العبرة منها فقال ما معناه: خرج رجل ليتصدق، ومعروف أن الصدقة على الفقراء والمساكين، فوقعت صدقته في يد سارق فأصبح الناس يتحدثون تصدق الليلة على سارق، والسارق ينبغي أن يعاقب؛ لا أن يعطى وينمى ماله، فقال هذا الرجل المتصدق: الحمد لله؛ لأن الله تعالى محمود على كل حال، ثم خرج هذا الرجل فقال: لأتصدقن الليلة، فوقعت صدقته في يد امرأة بغي تمكن الناس من الزنا بها، فأصبح الناس يتحدثون تصدق الليلة على زانية، وهذا شيء لا يقبله العقل ولا الفطرة، فقال: الحمد لله، ثم قال لأتصدقن الليلة -وكأنه رأى أن صدقته الأولى والثانية لم تقبل- فتصدق فوقعت في يد غني، والغني ليس من أهل الصدقة بل من أهل الهدية والهبة وما أشبه ذلك، فأصبح الناس يتحدثون تصدق الليلة على غني، فقال: الحمد لله، على سارق وعلى زانية وعلى غني.
 وقد كان يريد أن تقع صدقته في يد فقير متعفف نزيه لكن كان أمر الله قدرًا مقدورًا، فقيل له بواسطة نبي تلك الأمة: إن صدقاتك الثلاثة قد قبلت؛ لأنه مخلص قد نوى خيرًا لكنه لم يتيسر له، وأما السارق فلعله أن يستعف عن السرقة يقول هذا مال يكفيني، وأما البغِي فلعلها أن تستعف عن الزنا؛ لأنها ربما كانت تزني والعياذ بالله ابتغاء المال وقد حصل لها ما يكفها عن الزنا، وأما الغني فلعله يعتبر فينفق مما آتاه الله.', 'نية المتصدق إذا كانت صالحة، قبلت صدقته ولو لم تقع الموقع.
بيان فضل صدقة السر، وفضل الإخلاص، واستحباب إعادة الصدقة إذا لم تقع في الموقع.
الحكم للظاهر حتى يتبين سواه.
بيان بركة التسليم، والرضا، وذم التضجر بالقضاء.
استحباب تذكير العصاة ودعوتهم للحق؛ فلعلهم يعتبرون ويتوبون.
في الحديث دلالة على أن الصدقة كانت عند من قبلنا مختصة بأهل الحاجة من أهل الخير.', 'قال رجل : أي ممن كان قبل المسلمين.
فقيل له : فقيل له بواسطة نبي تلك الأمة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8414', false),
(21866, 2, 219, 1866, 'hadith', 'وعنه قال: كنا مع رسول الله صلى الله عليه وسلم في دعوة، فرفع إليه الذراع، وكانت تعجبه، فنهس منها نهسة وقال: أنا سيد الناس يوم القيامة، هل تدرون مم ذاك؟ يجمع الله الأولين والآخرين في صعيد واحد، فيبصرهم الناظر، ويسمعهم الداعي، وتدنوا منهم الشمس، فيبلغ الناس من الغم والكرب ما لا يطيقون ولا يحتملون ، فيقول الناس: ألا ترون إلى ما أنتم فيه إلى ما بلغكم، ألا تنظرون من يشفع لكم إلى ربكم؟ فيقول بعض الناس لبعض: أبوكم آدم، ويأتونه فيقولون: يا آدم أنت أبو البشر، خلقك الله بيده، ونفخ فيك من روحه، وأمر الملائكة، فسجدوا لك وأسكنك الجنة، ألا تشفع لنا إلى ربك؟ ألا ترى ما نحن فيه، وما بلغنا؟ فقال: إن ربي غضب غضباً لم يغضب قبله مثله، ولا يغضب بعده مثله، وإنه نهاني عن الشجرة، فعصيت، نفسي نفسي نفسي، اذهبوا إلى غيري، إذهبوا إلى نوح، فيأتون نوحا فيقولون: يا نوح ، أنت أول الرسل إلى أهل الأرض، وقد سماك الله عبداً شكوراً، ألا ترى ما نحن فيه، ألا ترى ما بلغنا ألا تشفع لنا إلى ربك؟ فيقول: إن ربي غضب اليوم غضباً لم يغضب قبله مثله، ولن يغضب بعده مثله، وإنه قد كانت لي دعوة دعوت بها على قومي، نفسي نفسي نفسي، اذهبوا إلى غيري، اذهبوا إلى إبراهيم فيأتون إبراهيم فيقولون: يا إبراهيم أنت نبي الله وخليله من أهل الأرض اشفع لنا إلى ربك، ألا ترى ما نحن فيه؟ فيقول لهم: إن ربي غضب اليوم غضباً لم يغضب قبله مثله، ولن يغضب بعده مثله، وإني كنت كذبت ثلاث كذبات، نفسي نفسي نفسي، اذهبوا إلى غيري، اذهبوا إلى موسى، فيأتون موسى، فيقولون: يا موسى أنت رسول الله فضلك الله برسالاته وبكلامه على الناس، اشفع لنا إلى ربك ألا ترى ما نحن فيه؟ فيقول: إن ربي قد غضب اليوم غضباً لم يغضب قبله مثله، ولن يغضب بعده مثله، وإني قد قتلت نفساً لم أومر بقتلها، نفسي نفسي نفسي، اذهبوا إلى غيري، اذهبوا إلى عيسى، فيأتون عيسى، فيقولون: يا عيسى أنت رسول الله وكلمته ألقاها إلى مريم وروح منه ، وكلمت الناس في المهد ، اشفع لنا إلى ربك، ألا ترى ما نحن فيه؟ فيقول عيسى: إن ربي غضب اليوم غضباً لم يغضب قبله مثله، ولن يغضب بعده مثله ولم يذكر ذنباً، نفسي نفسي نفسي، اذهبوا إلى غيري، اذهبوا إلى محمد صلى الله عليه وسلم ". وفي رواية: "فيأتوني فيقولون: يا محمد أنت رسول الله وخاتم الأنبياء، وقد غفر لك ما تقدم من ذنبك وما تأخر، اشفع لنا إلى ربك، ألا ترى ما نحن فيه؟ فأنطلق، فأتي تحت العرش، فأقع ساجداً لربي، ثم يفتح الله علي من محامده، وحسن الثناء عليه شيئاً لم يفتح على أحد قبلي ثم يقال: يا محمد ارفع رأسك، سل تعطه، واشفع تشفع، فأرفع رأسي، فأقول أمتي يارب، أمتي يا رب، فيقال: يا محمد أدخل من أمتك من لا حساب عليهم من الباب الأيمن من أبواب الجنة وهم شركاء الناس فيما سوى ذلك من الأبواب" ثم قال:" والذي نفسي بيده إن ما بين المصراعين من مصاريع الجنة كما بين مكة وهجر، أو كما بين مكة وبصرى".', 'Meat was one day brought to the Messenger of Allah (ﷺ) and a foreleg was offered to him, a part which he liked. He sliced with his teeth a piece out of it and said: I shall be the leader of mankind on the Day of Resurrection. Do you know why? Allah would gather in one plain the earlier and the later (of the human race) on the Day of Resurrection. Then the voice of the proclaimer would be heard by all of them and the eyesight would penetrate through all of them and the sun would come near. People would then experience a degree of anguish, anxiety and agony which they shall not be able to bear and they shall not be able to stand. Some people would say to the others: Don you see in which trouble you are? Don''t you see what (misfortune) has overtaken you? Why don''t you find one who should intercede for you with your Lord? Some would say to the others: Go to Adam. And they would go to Adam and say: O Adam, thou art the father of mankind. Allah created thee by His own Hand and breathed in thee of His spirit and ordered the angels to prostrate before thee. Intercede for us with thy Lord Don''t you see in what (trouble) we are? Don''t you see what (misfortune) has overtaken us? Adam would say: Verily, my Lord is angry, to an extent to which He had never been angry before nor would He be angry afterward. Verily, He forbade me (to go near) that tree and I disobeyed Him. I am concerned with my own self. Go to someone else; go to Noah. They would come to Noah and would say: O Noah, thou art the first of the Messengers (sent) on the earth (after Adam), and Allah named thee as a" Grateful Servant," intercede for us with thy Lord. Don''t you see in what (trouble) we are? Don''t you see what (misfortune) has overtaken us? He would say: Verily, my Lord is angry today as He had never been angry before, and would never be angry afterwards. There had emanated a curse from me with which I cursed my people. I am concerned with only myself, I am concerned only with myself; you better go to Ibrahim (peace be upon him). They would go to Ibrahim and say: Thou art the apostle of Allah and His Friend amongst the inhabitants of the earth; intercede for us with thy Lord. Don''t you see in which (trouble) we are? Don''t you see what (misfortune) has overtaken us? Ibrahim would say to them: Verily, my Lord is today angry as He had never been angry before and would never be angry afterwards. and (Ibrahim) would mention his lies (and then say): I am concerned only with myself, I am concerned only with myself. You better go to someone else: go to Moses. They would come to Moses (peace be upon him) and say: O Moses, thou art Allah''s messenger, Allah blessed thee with His messengership and His conversation amongst people. Intercede for us with thy Lord. Don''t you see in what (trouble) we are? Don''t you see what (misfortune) has overtaken us? Moses (peace be upon him) would say to them: Verily. my Lord is angry as He had never been angry before and would never be angry afterwards. I, in fact, killed a person whom I had not been ordered to kill. I am concerned with myself, I am concerned with myself. You better go to Jesus (peace be upon him). They would come to Jesus and would say: O Jesus, thou art the messenger of Allah and thou conversed with people in the cradle, (thou art) His Word which I-Ie sent down upon Mary. and (thou art) the Spirit from Him; so intercede for us with thy Lord. Don''t you see (the trouble) in which we are? Don''t you see (the misfortune) that has overtaken us? Jesus (peace be upon him) would say: Verily, my Lord is angry today as He had never been angry before or would ever be angry afterwards. He mentioned no sin of his. (He simply said: ) I am concerned with myself, I am concerned with myself; you go to someone else: better go to Muhammad (ﷺ). They would come to me and say: O Mahammad, thou art the messenger of Allah and the last of the apostles. Allah has pardoned thee all thy previous and later sins. Intercede for us with thy Lord; don''t you see in which (trouble) we are? Don''t you see what (misfortune) has overtaken us? I shall then set off and come below the Throne and fall down prostrate before my Lord; then Allah would reveal to me and inspire me with some of His Praises and Glorifications which He had not revealed to anyone before me. He would then say: Muhammad, raise thy head; ask and it would be granted; intercede and intercession would be accepted I would then raise my head and say: O my Lord, my people, my people. It would be said: O Muhammad, bring in by the right gate of Paradise those of your people who would have no account to render. They would share with the people some other door besides this door. The Prophet then said: By Him in Whose Hand is the life of Muhammad, verify the distance between two door leaves of the Paradise is as great as between Mecca and Hajar, or as between Mecca and Busra.', null, 'Abu Huraira', 'صحيح', 'رياض الصالحين 1866', 'Riyad as-Salihin 1866', 'ریاض الصالحین 1866', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21867, 2, 219, 1867, 'hadith', 'عن بن عباس رضي الله عنهما قال: جاء إبراهيم صلى الله عليه وسلم بأم إسماعيل وبابنها إسماعيل وهي ترضعه حتى وضعها عند البيت عند دوحة فوق زمزم في أعلى المسجد وليس بمكة يومئذ أحد وليس بها ماء، فوضعهما هناك، ووضع عندهما جراباً فيه تمر، وسقاء فيه ماء، ثم قفى إبراهيم منطلقاً، فتبعته أم إسماعيل فقالت: يا إبراهيم أين تذهب وتتركنا بهذا الوادي الذي ليس فيه أنيس ولا شيء؟ فقالت له ذلك مراراً، وجعل لا يلتفت إليها، قالت له: آلله أمرك بهذا؟ قال: نعم ، قالت: إذا لا يضيعنا، ثم رجعت، فانطلق إبراهيم صلى الله عليه وسلم ، حتى إذا كان عند الثنية حيث يرونه استقبل بوجهه البيت ، ثم دعا بهؤلاء الدعوات ، فرفع يديه فقال: {ربنا إني أسكنت من ذريتي بواد غير ذي زرع} حتى بلغ {يشكرون} وجعلت أم إسماعيل ترضع إسماعيل، وتشرب من ذلك الماء، حتى إذا نفد ما في السقاء عطشت، وعطش ابنها، وجعلت تنظر إليه يتلوى -أوقال: يتلبط- فانطلقت كراهية أن تنظر إليه ، فوجدت الصفا أقرب جبل في الأرض يليها، فقامت عليه، ثم استقبلت الوادي تنظر هل ترى أحداً؟ فلم تر أحداً، فهبطت من الصفا حتى إذا بلغت الوادي، رفعت طرف درعها، ثم سعت سعي الإنسان المجهود حتى جاوزت الوادي، ثم أتت المروة، فقامت عليها، فنظرت هل ترى أحداً؟ فلم تر أحداً، ففعلت ذلك سبع مرات، قال ابن عباس رضي الله عنهما: قال النبي صلى الله عليه وسلم "فذلك سعي الناس بينها" فلما أشرفت على المروة سمعت صوتاً، فقالت: صه-تريد نفسها- ثم تسمّعت ، فسمعت أيضاً فقالت: قد أسمعت إن كان عندك غواث فأغث، فإذا هى بالملك عند موضع زمزم، فبحث بعقبه -أو قال بجناحه- حتى ظهر الماء، فجعلت تحوضه وتقول بيدها هكذا، وجعلت تغرف الماء في سقائها وهو يفور بعدما تغرف، وفي رواية : بقدر ما تغرف، قال ابن عباس رضي الله عنهما : قال النبي صلى الله عليه وسلم : "رحم الله أم إسماعيل لو تركت زمزم -أو قال: لو لم تغرف من الماء، لكان زمزم عينا معينا" قال: فشربت ، وأرضعت ولدها، فقال لها الملك: لا تخافوا الضيعة فإن ههنا بيتا لله يبنيه هذا الغلام وأبوه، وإن الله لا يضيع أهله، وكان البيت مرتفعاً من الأرض كالرابية تأتيه السيول، فتأخذ عن يمينه وعن شماله، فكانت كذلك حتى مرت بهم رفقة من جرهم، أو أهل بيت من جرهم مقبلين من طريق كداء، فنزلوا في أسفل مكة، فرأوا طائراً عائفاً فقالوا: إن هذا الطائر ليدور على ماء لعهدنا بهذا الوادي وما فيه ماء، فأرسلوا جرياً أو جريين، فإذا هم بالماء، فرجعوا، فأخبروهم، فأقبلوا وأم إسماعيل عند الماء، فقالوا: أتأذنين لنا أن ننزل عندك؟ قالت: نعم، ولكن لا حق لكم في الماء، قالوا: نعم، قال ابن عباس: قال النبي صلى الله عليه وسلم : "فألفى ذلك أم إسماعيل، وهي تحب الأنس، فنزلوا، فأرسلوا إلى أهليهم فنزلوا معهم، حتى إذا كانوا بها أهل أبيات، وشب الغلام وتعلم العربيه منهم وأنفسهم وأعجبهم حين شب ، فلما أدرك، زوجوه امرأة منهم، وماتت أم إسماعيل، فجاء إبراهيم بعد ما تزوج إسماعيل يطالع تركته فلم يجد إسماعيل، فسأل امرأته عنه فقالت: خرج يبتغي لنا- وفي رواية: يصيد لنا - ثم سألها عن عيشهم وهيئتهم فقالت: نحن بشر ، نحن في ضيق وشدة، وشكت إليه ، قال: فإذا جاء زوجك، أقرئي عليه السلام وقولي: غير عتبة بابك، قال: ذاك أبي وقد أمرني أن أفارقك، الحقي بأهلك. فطلقها ، وتزوج منهم أخرى، فلبث عنهم إبراهيم ما شاء الله ثم أتاهم بعد، فلم يجده ، فدخل على امرأته، فسأله عنه، قالت: خرج يبتغي لنا، قال: كيف أنتم؟ وسألها عن عيشهم وهيئتهم، فقالت: نحن بخير وسعة وأثنت على الله تعالى، فقال: ما طعامكم؟ قالت: اللحم قال: فما شرابكم؟ قالت الماء. قال: اللهم بارك لهم في اللحم والماء، قال النبي صلى الله عليه وسلم : "ولم يكن لهم يؤمئذ حب ولو كان لهم دعا لهم فيه" قال: فهما لا يخلو عليهما أحد بغير مكة إلا لم يوافقاه. وفي رواية فجاء فقال: أين إسماعيل؟ فقالت امرأته: ذهب يصيد، فقالت امرأته: ألا تنزل، فتطعم وتشرب؟ قال: وما طعامكم وما شرابكم؟ قالت: طعامنا اللحم، وشرابنا الماء، قال: اللهم بارك لهم في طعامهم وشرابهم- قال، فقال أبوالقاسم صلى الله عليه وسلم : "بركة دعوة إبراهيم صلى الله عليه وسلم " قال: فإذا جاء زوجك ، فاقرئي عليه السلام ومريه يثبت عتبة بابه، فلما جاء إسماعيل، قال: هل أتاكم من أحد؟ قالت: نعم، أتانا شيخ حسن الهيئة، وأثنت عليه فسألني عنك، فأخبرته ،فسألني كيف عيشنا، فأخبرته، أنّا بخير، قال: فأوصاك بشيء؟ قالت: نعم، يقرأ عليك السلام، ويأمرك أن تثبت عبتة بابك، قال: ذاك أبي وأنت العتبة أمرني أن أمسكك، ثم لبث عنهم ما شاء الله، ثم جاء بعد ذلك وإسماعيل يبري نبلاً له تحت دوحة قريباً من زمزم، فلما رآه، قام إليه ، فصنع كما يصنع الوالد بالولد، والولد بالوالد قال يا إسماعيل إن الله أمرني بأمر ، قال: فاصنع ما أراك ربك؟ قال: وتعينني، قال: وأعينك، قال: فإن الله أمرني أن أبني بيتا ههنا، وأشار إلى أكمة مرتفعة على ما حولها، فعند ذلك رفع القواعد من البيت، فجعل إسماعيل يأتي بالحجارة وإبراهيم يبني حتى إذا ارتفع البناء، جاء بهذا الحجر فوضعه له فقام عليه، وهو يبني وإسماعيل يناوله الحجارة وهما يقولان : ربنا تقبل منا إنك أنت السميع العليم. وفي رواية: إن إبراهيم خرج بإسماعيل وأم إسماعيل، معهم شنة فيها ماء، فجعلت أم إسماعيل تشرب من الشنة، فيدر لبنها على صبيها حتى قدم مكة، فوضعها تحت دوحة، ثم رجع إبراهيم إلى أهله، فاتبعته أم إسماعيل حتى لما بلغوا كداء، نادته من ورائه: يا إبراهيم إلى من تتركنا؟ قال: إلى الله ، قالت: رضيت بالله، فرجعت، وجعلت تشرب من الشنة، ويدر لبنها على صبيها حتى لما فني الماء قالت: لو ذهبت ، فنظرت لعلي أحس أحداً، قال: فذهبت فصعدت الصفا، فنظرت ونظرت هل تحس أحداً، فلما بلغت الوادي، سمعت، وأتت المروة، وفعلت ذلك أشواطا، ثم قالت: لو ذهبت فنظرت ما فعل الصبي، فذهبت ونظرت، فإذا هو على حاله كأنه ينشغ للموت، فلم تقرها نفسها ، فقالت: لو ذهبت ، فنظرت لعلي أحس أحداً، فذهبت فصعدت الصفا، فنظرت ونظرت، فلم تحس أحداً حتى أتمت سبعاً، ثم قالت: لو ذهبت ، فنظرت ما فعل، فإذا هي بصوت فقال: أغث إن كان عندك خير، فإذا جبريل صلى الله عليه وسلم فقال بعقبه هكذا، وغمز بعقبه على الأرض فانبثق الماء فدهشت أم إسماعيل، فجعلت تحفن، وذكر الحديث بطوله. ((رواه البخاري)) بهذه الروايات كلها. «الدوحة» الشجرة الكبيرة. قوله: «قفى» : أي: ولى. ... «والجري» : الرسول. «وألفى» : معناه وجد. قوله: «ينشغ» : أي: يشهق.', 'Ibrahim (ﷺ) brought his wife and her son Isma''il (ﷺ), while she was suckling him, to a place near the Ka''bah under a tree on the spot of Zamzam, at the highest place in the mosque. In those days, there was no human being in Makkah, nor was there any water. So he made them sit over there and placed near them a leather bag containing some dates, and a small water-skin containing some water, and set out homeward. Isma''il''s mother followed him saying: "O Ibrahim! Where are you going, leaving us in this valley where there is no person whose company we may enjoy, nor is there anything (to enjoy)?" She repeated that to him many times, but he did not look back at her. Then she asked him: "Has Allah commanded you to do so?" He said: "Yes." She said: "Then He will not neglect us." She returned while Ibrahim proceeded onwards. Having reached the Thaniya, where they could not see him, he faced Ka''bah, raised his both hands and supplicated: "O our Rubb! I have made some of my offspring to dwell in an uncultivable valley by Your Sacred House (the Ka''bah at Makkah) in order, O our Rubb, that they may perform As-Salat (Iqamat-as-Salat). So fill some hearts among men with love towards them, and (O Allah) provide them with fruits so that they may give thanks." (14:37).Isma''il''s mother went on suckling Isma''il and drinking from the water which she had. When the water in the water-skin had all been used up, she became thirsty and her child also became thirsty. She started looking at Isma''il, tossing in agony. She left him, for she could not endure looking at him, and found that the mountain of As-Safa was the nearest mountain to her on that land. She stood on it and started looking at the valley keenly so that she might see somebody, but she could not see anybody. Then she descended from As-Safa, and when she reached the valley, she tucked up her robe and ran in the valley like a person in distress and trouble till she crossed the valley and reached Al-Marwah mountain where she stood and started looking, expecting to see somebody, but she could not see anybody. She repeated that (running between As-Safa and Al-Marwah) seven times." Ibn ''Abbas further related: The Prophet (ﷺ) said, "This is the source of the tradition of the Sa''y - i.e., the going of people between the two mountains. When she reached Al-Marwah (for the last time), she heard a voice and she exclaimed: ''Shshs!'' (Silencing herself) and listened attentively. She heard the voice again and said: ''O (whoever you may be) You have made me hear your voice; have you any succour for me?'' And behold! She saw an angel at the place of Zamzam, digging the earth with his heel (or with his wing), till water flowed out from that place. She started to make something like of a basin around it, using her hands in this way and began to fill her water- skin with water with her hands, and the water was flowing out until she had scooped some of it." The Prophet (ﷺ) further said, "May Allah bestow mercy on Isma''il''s mother! Had she let the Zamzam flow without trying to control it (or had she not scooped in that water) while filling her water-skin, Zamzam would have been a stream flowing on the surface of the earth." The Prophet (ﷺ) further added, "Then she drank (water) and suckled her child. The angel said to her: ''Do not be afraid of being neglected, for this is the site on which the House of Allah will be built by this boy and his father, and Allah will never let neglected His people.'' The House of Allah (the Ka''bah) at that time was on a high place resembling a hillock, and when torrents came, they flowed to its right and left. She continued living in that way till some people from the tribe of Jurhum passed by her and her child. As they were coming from through the way of Kada'', in the lower part of Makkah where they saw a bird that had a habit of flying around water and not leaving it. They said: ''This bird must be flying over water, though we know that there is no water in this valley.'' They sent one or two messengers who discovered the source of water, and returned to inform them of the water. So, they all came towards the water." The Prophet (ﷺ) added, "Isma''il''s mother was sitting near the water. They asked her: ''Do you allow us to stay with you?'' She replied: ''Yes, but you will have no right to possess the water.'' They agreed to that." The Prophet (ﷺ) further said, "Isma''il''s mother was pleased with the whole situation as she used to love the company of the people. So, they settled there, and later on they sent for their families who came and settled with them. The child (i.e., Isma''il) grew up and learnt Arabic from them (his virtues) caused them to love and admire him as he grew up, and when he reached the age of puberty, they gave him one of their daughters in marriage. After Isma''il''s mother had died, Ibrahim came after Isma''il''s marriage in order to see his family that he had left before, but he did not find Isma''il there. When he asked Isma''il''s wife about him, she replied: ''He has gone in search of our livelihood.'' Then he asked her about their way of living and their condition, and she replied complaining to him: ''We are living in hardship, misery and destitution.'' He said: ''When your husband returns, convey my salutations to him and tell him to change the threshold of the door of his house.'' When Isma''il came, he seemed to have perceived something unusual. He asked his wife: ''Did anyone visit you?'' She replied: ''Yes, an old man of such and such description came and asked me about you and I informed him, and he asked about our state of living, and, I told him that we were living in hardship and poverty.'' Thereupon Isma''il said: ''Did he advise you anything?'' She replied: ''Yes, he told me to convey his salutations to you and to change the threshold of your door.'' Isma''il said: ''That was my father, and he has ordered me to divorce you. Go back to your family.'' So Isma''il divorced her and married another woman from amongst them (Jurhum). Then Ibrahim stayed away from them for a period as long as Allah wished, and called on them again but did not find Isma''il. So he came to Isma''il''s wife and asked her about him. She said: ''He has gone in search of our livelihood.'' Ibrahim asked her about their sustenance and living: ''How are you getting on?'' She replied: ''We are prosperous and well off.'' Then she praised Allah, the Exalted. Ibrahim asked: ''What kind of food do you eat?'' She said: ''Meat.'' He said: ''What do you drink?'' She said: ''Water.'' He said, ''O Allah! Bless their meat and water!"'' The Prophet (ﷺ) added, "At that time they did not have grain, and if they had grain, he would have also invoked Allah to bless it." The Prophet (ﷺ) further said, "If somebody has only these two things as his sustenance, his health and disposition will be badly affected because these things do not suit him unless he lives in Makkah." The Prophet (ﷺ) added, "Then Ibrahim said to Isma''il''s wife, ''When your husband comes, give my regards to him and tell him that he should keep firm the threshold of his door.'' When Isma''il came back, he asked his wife: ''Did anyone call on you?'' She replied: ''Yes, a good looking old man came to me.'' She praised him and added: ''He asked about you, and I informed him, and he asked about our livelihood and I told him that we were in good condition.'' Isma''il asked her: ''Did he give you a piece of advice?'' She said: ''Yes, he told me to convey his regards to you and ordered that you should keep firm the threshold of your door.'' On that Isma''il said: ''He was my father and you are the threshold of the door. He has ordered me to keep you with me.'' Then Ibrahim stayed away from them for a period as long as Allah wished and called on them afterwards. He saw Isma''il under a tree near Zamzam, sharpening his arrows. When he saw Ibrahim, he rose up to welcome him, and they greeted each other as a father does with his son or a son does with his father. Ibrahim said: ''O Isma''il! Allah has given me an order.'' Isma''il said: ''Do what your Rubb has commanded you to do.'' Ibrahim asked: ''Will you help me?'' Isma''il said: ''I will help you.'' Ibrahim said: ''Allah has ordered me to build a house here, pointing to a hillock higher than the land surrounding it."'' The Messenger of Allah (ﷺ) added, "Then they raised the foundations of the House (i.e., Ka''bah). Isma''il brought the stones and Ibrahim was building (the house). When the walls became high, Isma''il brought stone and placed it for Ibrahim who stood over it and carried on building the House, while Isma''il was handing over the stones to him, both of them prayed: ''O our Rubb! Accept this service from us! Verily, You are the All- Hearer and the All-Knower."''.There are some more narrations about this incident, some adding details and some with minor variations in the wordings.', 'بن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1867', 'Riyad as-Salihin 1867', 'ریاض الصالحین 1867', null, 'عن ابن عباس رضي الله عنهما قال: جاء إبراهيم صلى الله عليه وسلم بأم إسماعيل هاجر القبطية -التي وهبها ملك مصر لزوجته سارة- وبابنها إسماعيل وهي ترضعه، حتى وضعها عند الكعبة، عند شجرة كبيرة ثابتة فوق زمزم في أعلى المسجد، وليس بمكة يومئذ أحد من الإِنس، وليس بها ماء فوضعهما هناك، ووضع عندهما وعاء من جلد فيه تمر، وسقاء فيه ماء، ثم ولّى منطلقًا إلى الشام، فتبعته أم إسماعيل فقالت: يا إبراهيم أين تذهب وتتركنا بهذا الوادي الذي ليس فيه أنيس ولا شيء مما يؤكل ويشرب؟ فقالت له ذلك مرارًا، ولا يلتفت إليها، وانصرف إلى طريقه، فقالت له: آلله أمرك بهذا؟ قال: نعم قالت: إذًا لا يضيعنا.
ثم رجعت إلى ابنها؛ فانطلق إبراهيم صلى الله عليه وسلم حتى إذا كان عند الثَّنِيَّة عند الحجون حيث لا يرونه استقبل بوجهه موضع البيت، ثم دعا بهؤلاء الدعوات فرفع يديه فقال: (رب إني أسكنت من ذريتي) بعضهم (بواد غير ذي زرع) وهو مكة، وكونها كذلك ليتم التفرغ فيها للعبادة، (عند بيتك المحرم) الذي حرم عنده الصيد وقطع الشجر والمقاتلة (ربنا ليقيموا الصلاة) بمكة (فاجعل أفئدة من الناس) أي: قلوبهم (تهوي) أي: تسرع (إليهم) شوقاً (وارزقهم من الثمرات لعلهم يشكرون) نعمتك، وقد استجاب الله دعاءه.
وجعلت أم إسماعيل ترضعه، وتشرب من ذلك الماء، وتأكل من ذلك الثمر؛ حتى إذا نفد وانتهى ما في السقاء من الماء؛ عطشت وعطش ابنها، وجعلت تنظر إليه يتلوى أو يتمرّغ ويضرب بنفسه الأرض فانطلقت كراهية أن تنظر إليه وهو كذلك، فوجدت الصفا أقرب جبل إليها في الأرض؛ فقامت عليه، ثم استقبلت مكة تنظر هل ترى أحداً؟ فلما بلغت الوادي المسيل وفيه انخفاض امتنع به رؤيتها لولدها فخافت عليه فأسرعت وسعت سعي الذي أصابته المشقة، وأتت المروة أي: بعد تركها السعي وعودها لعادتها قبل وصولها الوادي، فنظرت هل ترى أحدًا؟ فلم تر أحدًا، ففعلت ذلك سبع مرات، قال ابن عباس رضي الله عنهما : قال النبي صلى الله عليه وسلم : «فلذلك سعى الناس بينهما»، فلما أشرفت على المروة سمعت صوتًا، فقالت لنفسها: اسكتي، تريد من نفسها الإنصات، ثم تسمَّعت فسمعت أيضًا، فقالت: قد أسمعت فاغثني. فإذا هي بالملك جبريل عند موضع زمزم، فبحث بعقبه أي مؤخر قدمه، -أو قال بجناحه- حتى ظهر الماء، فجعلت تجعله مثل الحوض، وجعلت تغرف من الماء في سقائها وهو ينبع بشدة بعد ما تغرف -وفي رواية: بقدر ما تغرف- قال ابن عباس رضي الله عنهما : قال النبي صلى الله عليه وسلم : رحم الله أم إسماعيل لو لم تغرف من الماء لكانت زمزم عينًا معينًا. يعني جاريًا على ظاهر الأرض.
 قال: فشربت وأرضعت ولدها، فقال لها الملك: لا تخافوا الهلاك؛ فإن هاهنا بيتًا لله يبنيه هذا الغلام وأبوه، وإن الله لا يضيع أهله، وكان موضع البيت مرتفعًا من الأرض كالرابية، تأتيه السيول، فتأخذ عن يمينه وعن شماله؛ فلا تغرقه السيول، فكانت كذلك حتى مرت بهم رفقة من قبيلة جُرْهم، مقبلين من طريق كَدَاء، فنزلوا في أسفل مكة؛ فرأوا طائرًا يحوم في الجو، فقالوا: إن هذا الطائر ليدور على ماء، لعهدنا بهذا الوادي وما فيه ماء؛ فأرسلوا رسولًا أو رسولين يستطلعان، فإذا هم بالماء فرجعا فأخبروهم فأقبلوا، وأم إسماعيل عند الماء فقالوا: أتأذنين لنا أن ننزل عندك؟ قالت: نعم ولكن لاحق لكم في الماء. أي: بل الحق فيه مختص بي، فإن شئت منحت وإن شئت منعت. قالوا: نعم، فوافق ذلك أم إسماعيل، وهي تحب الأنس وتكره الوحشة.
فنزلوا فأرسلوا إلى أهليهم فجاءوا فنزلوا معهم؛ حتى اجتمعوا وكثروا وشبّ إسماعيل، وتعلم العربية منهم، و كثرت رغبتهم فيه، وأعجبهم حتى كبر ونشأ، فلما بلغ الحُلم زوجوه امرأة منهم، وماتت أم إسماعيل فجاء إبراهيم بعد ما تزوج إسماعيل يتفقد حال ما تركه؛ فلم يجد إسماعيل فسأل امرأته عنه أين هو؟ فقالت: خرج يطلب لنا رزقًا بالصيد، ثم سألها عن عيشهم من الطعام والشراب وعن حالتهم؟ فقالت: نحن بِشرٍّ، وفي ضيق من المعاش وشدة منه، وشكت إليه. 
فلما رأى مزيد التبرم وشدة الضجر مما ابتلاها الله تعالى به زيادة في الدرجات خشي أن يسري حالها إلى ولده فيقع في مثل حالها فأمره بفراقها، فقال إبراهيم: فإذا جاء زوجك أبلغيه سلامي، وقولي له يغير عتبة بابه. كناية عن طلاق امرأته؛ لأن المرأة تلازم البيت كملازمة العتبة للبيت، فلما جاء إسماعيل من صيده كأنه أحس شيئاً؛ فقال: هل جاءكم من أحد؟ قالت: نعم جاءنا شيخ موصوف بكذا؛ فسألنا عنك فأخبرته فسألني كيف عيشنا؟ فأخبرته أنا في مشقة وشدة، قال: فهل أوصاك بشيء؟ قالت: نعم أمرني أن أقرأ عليك السلام، ويقول لك غير عتبة بابك. قال: ذاكِ أبي وقد أمرني بتغيير عتبة الباب: أن أفارقك، الحقي بأهلك. وهو من كنايات الطلاق، لكنه صرح به بقوله فطلقها، وتزوج منهم امرأة أخرى.
 فلبث إبراهيم ما شاء الله ثم أتاهم بعد ذلك فلم يجد إسماعيل؛ فدخل على امرأته؛ فسأل عنه. قالت: خرج يبتغي لنا -وفي رواية فقالت امرأته: ألا تنزل فتطعم وتشرب- قال: كيف أنتم؟ وسألها عن عيشهم وحالهم فقالت: نحن بخير وسَعة. وحمدت الله تعالى . فقال: ما طعامكم؟ قالت اللحم. قال: فما شرابكم. قالت: ماء زمزم أوهو وغيره من باقي المياه كماء مطر. فقال: اللهم بارك لهم في اللحم والماء. قال النبي صلى الله عليه وسلم ولم يكن لهم يومئذ أي نوع من الحبوب، ولو كان لهم دعا لهم فيه؛ لتعمه البركة بدعائه.
قال ابن عباس رضي الله عنه : فهما لا يخلو عليهما أحد بغير مكة إلا لم يوافقاه مزاجه، ويشتكي من بطنه. قال إبراهيم: فإذا جاء زوجك من الصيد، فاقرئي عليه السلام، ومُرِيه يثبِّت عتبة بابه، فلما جاء إسماعيل من الصيد كأنه أحس شيئاً -كما جاء في رواية وجد ريح أبيه- فقال: هل أتاكم من أحد؟ قالت: نعم، شيخ حسن الهيئة، وأثنت عليه ذاكرة بعض أوصاف كماله، فسألني عنك فأخبرته، فسألني كيف عيشنا؟ فأخبرته أنّا بخير. قال: فأوصاكِ بشيء؟ قالت: نعم، يقرأ عليك السلام ويأمرك أن تثبت عتبة بابك. قال: ذاك أبي، وأنت العتبة، أمرني أن أديم عصمتك.
ثم لبث إبراهيم عنهم ما شاء الله، ثم جاء بعد ذلك وإسماعيل يصلح سهما قبل أن يُركِّب فيه نصله وهو تحت شجرة بقرب زمزم، فلما رآه قام إليه، فصنعا كما يصنع الوالد بالولد والولد بالوالد من العناق والمصافحة. 
قال إبراهيم: يا إسماعيل إن الله تعالى أمرني بأمر. قال: فاصنع ما أمرك ربك. قال وتعينني؟ قال: وأعينك. قال: فإن الله تعالى أمرني أن أبني بيتًا ها هنا، وأشار بقوله ها هنا إلى تل، وقيل شرفة مرتفعة على ما حولها من الأرض، وكانت السيول لا تعلوها، فعند ذلك رفع إبراهيم الأساس من البيت، ورفع البناء عليها، فجعل إسماعيل يأتي بالحجارة، وإبراهيم على المقام ينزل منه لأخذ الحجر من إسماعيل، ثم يعلو به فيضعه محله من البناء، حتى إذا ارتفع البناء جاء بحجر المقام؛ فلما بلغ الموضع الذي فيه الركن وضعه يومئذ موضعه، وأخذ المقام فجعله لاصقاً بالبيت، كان يبني وإسماعيل يناوله الحجارة وهما يقولان (ربنا تقبل منا) بناء البيت (إنك أنت السميع) لدعائنا (العليم) ببناء البيت.
وفي قوله (تعلم العربية) دليل قوي على قدم اللغة العربية، وأنها قبل إبراهيم -عليه السلام- لكن إسماعيل أول من نطق باللغة العربية المبينة، كما في الحديث "أول من فتق لسانه بالعربية المبينة إسماعيل وهو ابن أربع عشرة سنة". رواه الشيرازي في الألقاب وصححه الشيخ الألباني.', 'استحباب استقبال القبلة حال الدعاء؛ فقد استقبل إبراهيم -عليه السلام- البيت ودعا.
في قوله (ربنا ليقيموا الصلاة) تحريض للمقيم بمكة على عبادة المولى، والإِعراض عن أعراض الدنيا فإنها حينئذ تنقاد له.
الحث على التوكل على الله والتضرع إليه، ومن توكل على الله كفاه، ومن فوض إليه أمره وقاه.
مبادرة الأنبياء لطاعة ربهم، والتضحية من أجل مرضاته بأولادهم وأزواجهم.
أن ماء زمزم طعام طعم؛ حيث كان طعام أم إسماعيل وابنها.
فيه بيان للحكمة من السعي في مناسك الحج.
شدة فراسة العرب؛ حيث استدلوا على وجود الماء بتعاقب الطير على مكانه.
في قوله (تعلم العربية) دليل قوي على قدم اللغة العربية.
فيه استحباب مفارقة من لا صبر لها عند تعاور الشدائد.
فيه بر الوالد وتنفيذ أمره والمسارعة إليه.
وقوع الطلاق بالكناية يعني باللفظ غير الصريح لقول إبراهيم يغير عتبة بابه، وفسرها إسماعيل بالطلاق.
كراهية التضجر من حال العيش، واستحباب شكر المنعم على كل حال.
مسئولية الوالد عن أولاده وتفقده لهم.
من أساليب الدعوة الكناية.', 'بأم إسماعيل : اسمها هاجَر، وهي قبطية وهبها لسارة ملك مصر الذي أراد سارة فحفظها الله -تعالى- منه.
الدوحة : الشجرة الكبيرة.
البيت : الكعبة.
جرابًا : وعاء من الجلد.
السِقَاءُ : إناء يكون للماء واللبن.
قَفَّى : وَلَّى وذهب.
الثَّنِيَّة : الطريق في الجبل وكانت عند الحجون.
يَتَلَبَّط : يتمرغ ويضرب بنفسه الأرض.
أكَمَة : تل، وقيل: شرفة كالرابية وهو: ما اجتمع من الحجارة في مكان مرتفع واحد.
الشِّنَّة : هي الجلدة البالية، والمراد هنا السقاء.
يغيِّر عَتَبَة بابه : كناية عن طلاق امرأته، وكنى عن المرأة بعتبة الباب لما فيها من حفظ الباب وصون ما في داخله وكونها محل الوطء.
يَنْشَغُ : يَشْهَق.
زمزم : هي البئر المباركة المشهورة، تقع جنوب شرق الكعبة.
أشرفت : علت.
يدرّ لبنها : يكثر.
كَدَاء : العقبة الصغرى بأعلى مكة.
فبحث بعقبه : حفر بمؤخرة قدمه.
تَحْفِن : تملأ كفها.
درعها : قميصها.
الْجَرِيّ : الرّسول.
جَهْد : مشقة.
المجهود : الذي أصابه الجَهْد أي المشقة.
صه : اسكتي.
تُحَوِّضُهُ : تجعله مثل الحوض.
يَبْرِي نَبْلًا : يُصلِح سهمًا قبل أن يركِّب فيه نصله وريشه.
عَيْنًا مَعِينًا : ظاهرًا جاريًا على وجه الأرض.
الضَّيْعَةَ : الهلاك.
جُرْهُمٍ : قبيلة قحطانية، هاجرت من اليمن إلى الحجاز، وسكنت مكة.
طائرًا عائِفاً : الذي يحوم على الماء ويتردد ولا يمضي عنه.
أنْفَسَهُمْ : من النفاسة والجودة، أي: كثرت رغبتهم فيه.
ألْفَى : وجد.
شَبَّ : كبر ونشأ.
أدرك : بلغ الحلم.
يطالع تركته : يتفقد حال ما تركه.
آنس : أحسّ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8346', false),
(21868, 2, 219, 1868, 'hadith', 'عن سعيد بن زيد رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «الكمأة من المن، وماؤها شفاء للعين».', 'I heard the Messenger of Allah (ﷺ) saying, "Truffle (edible fungus) is a species of Al-Manna and their water cures eye diseases."', 'سعيد بن زيد رضي الله عنه', 'Sa''id bin Zaid (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1868', 'Riyad as-Salihin 1868', 'ریاض الصالحین 1868', 'متفق عليه', 'الكمأة مما امتن الله به على عباده من غير مشقة، وهي شيء ينبت بنفسه من غير استنبات ولا تكلف، وماء الكمأة شفاء للعين من الرمد أو الماء الأبيض أو غير ذلك، كما جربه بعض الناس ونفعه، قال النووي رحمه الله: (وقيل: معناه أن يخلط ماؤها بدواء ويعالج به العين، وقيل: إن كان لبرودة ما في العين من حرارة فماؤها مجردا شفاء، وإن كان لغير ذلك فمركب مع غيره، والصحيح بل الصواب أن ماءها مجردا شفاء للعين مطلقا، فيُعصَر ماؤها ويجعل في العين منه، وقد رأيت أنا وغيري في زمننا من كان عمي وذهب بصره حقيقة، فكحل عينه بماء الكمأة مجردا، فشفي وعاد إليه بصره، وهو الشيخ العدل الأيمن الكمال بن عبد الله الدمشقي).', 'ماء الكمأة دواء نبوي.

هذا الإخبار من النبي صلى الله عليه وسلم بالأدوية وهو عليه الصلاة والسلام لا يعرف القراءة ولا الكتابة من معجزاته.', 'الكمأة: ثمرة تنبت في الأرض في مواسم معلومة، تشبه البطاطس.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66078', false),
(21869, 2, 220, 1869, 'hadith', 'عن الأغر المزني رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إنه ليغان على قلبي، وإني لأستغفر الله في اليوم مائة مرة».', 'The Messenger of Allah (ﷺ) said, "Sometimes I perceive a veil over my heart, and I supplicate Allah for forgiveness a hundred times in a day.".', 'الأغر المزني رضي الله عنه', 'Al-Agharr Al-Muzani (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1869', 'Riyad as-Salihin 1869', 'ریاض الصالحین 1869', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21870, 2, 220, 1870, 'hadith', 'عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول «والله إني لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة».', 'I heard the Messenger of Allah (ﷺ) saying, "I swear by Allah that I seek Allah''s Pardon and turn to Him in repentance more than seventy times a day.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1870', 'Riyad as-Salihin 1870', 'ریاض الصالحین 1870', 'رواه البخاري', 'النبي صلى الله عليه وسلم الذي غفر الله له ما تقدم من ذنبه وما تأخر: يقسم أنه يستغفر الله ويتوب إليه في اليوم أكثر من سبعين مرة، واستغفار النبي صلى الله عليه وسلم لا يلزم أن يكون لذنوب ارتكبها ولكن ذلك لكمال عبوديته وتعلقه بذكره سبحانه ، واستشعاره عظم حق الله تعالى وتقصير العبد مهما عمل في شكر نعمه، وهو من باب التشريع للأمة من بعده، إلى غير ذلك من الحكم.', 'جواز القسم على الشيء تأكيدا له، وإن لم يكن عند السامع فيه شك.
حض الأمة على التوبة والاستغفار اقتداء بالنبي -صلى الله عليه وسلم-؛ فإنه -صلى الله عليه وسلم- مع كونه معصوما، وخير الخلق، وقد غفر له ما تقدم من ذنبه وما تأخر، يستغفر الله ويتوب إليه في اليوم أكثر من سبعين مرة.
الإكثار من الاستغفار والتوبة؛ فإن العبد لا ينفك عن ذنب أو تقصير.
استغفار النبي -صلى الله عليه وسلم- لا يلزم أن يكون لذنوب ارتكبها ولكن ذلك لكمال عبوديته وتعلقه بذكره -سبحانه-، واستشعاره عظم حق الله -تعالى- وتقصير العبد مهما عمل في شكر نعمه، وهو من باب التشريع للأمة من بعده، إلى غير ذلك من الحكم.', 'أستغفر : أي: أطلب المغفرة، وهي الصفح عن الذنب.
وأتوب إليه : أي: أعزم على التوبة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4808', false),
(21871, 2, 220, 1871, 'hadith', 'وعنه رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «والذي نفسي بيده لو لم تذنبوا، لذهب الله تعالى بكم، ولجاء بقوم يذنبون فيستغفرون الله تعالى فيغفر لهم».', 'The Messenger of Allah (ﷺ) said, "By the One in Whose Hand my soul is! If you do not commit sins, Allah would replace you with a people who would commit sins and seek forgiveness from Allah; and Allah will certainly forgive them.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1871', 'Riyad as-Salihin 1871', 'ریاض الصالحین 1871', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21872, 2, 220, 1872, 'hadith', 'عن بن عمر رضي الله عنه قال: كنا نعد لرسول الله صلى الله عليه وسلم في المجلس الواحد مائة مرة: «رب اغفر لي، وتب على إنك أنت التواب الرحيم».', 'We counted Messenger''s saying a hundred times during one single sitting: Rabb- ighfir li, wa tubb ''alayya, innaka Antat-Tawwabur-Rahim. (My Rubb! Forgive me and pardon me. Indeed, You are the Oft-Returning with compassion and Ever Merciful.".', 'بن عمر رضي الله عنه', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1872', 'Riyad as-Salihin 1872', 'ریاض الصالحین 1872', 'رواه أبوداود والترمذي)). وقال : (( حديث حسن صحيح غريب', 'قال عبد الله بن عمر رضي الله عنهما: كنا نحسب للنبي صلى الله عليه وسلم في المجلس الواحد أنه يقول مائة مرة: (رَبِّ اغفِر لي وتُب عليَّ، إنَك أنتَ التَّوابُ الرحيم).', 'استحباب كثرة الاستغفار، وذلك لأنه صلى الله عليه وسلم مع كونه مغفورًا له قطعًا، كان يستغفر في المجلس الواحد مائة مرة، فغيره الذي أولى وأحرى أن يكثر الاستغفار، على أنه صلى الله عليه وسلم كان فعله ذلك تعليمًا لأمته، وإرشادًا لهم إلى طريق الاستغفار.', '-', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65925', false),
(21873, 2, 220, 1873, 'hadith', 'عن ابن عباس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من لزم الاستغفار ، جعل الله له من كل ضيق مخرجاً ومن كل هم فرجاً، ورزقه من حيث لا يحتسب» رواه أبو داود.', 'The Messenger of Allah (ﷺ) said, "If anyone constantly seeks pardon (from Allah), Allah will appoint for him a way out of every distress and a relief from every anxiety, and will provide sustenance for him from where he expects not.".', 'ابن عباس رضي الله عنه', 'Ibn ''Abbas (May Allah be pleased with them) said:', null, 'رياض الصالحين 1873', 'Riyad as-Salihin 1873', 'ریاض الصالحین 1873', null, null, null, null, 'sunnah.com', null, false, null, false),
(21874, 2, 220, 1874, 'hadith', 'عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من قال: أستغفر الله الذي لا إله إلا هو الحي القيوم وأتوب إليه ، غفرت ذنوبه ، وإن كان قد فر من الزحف».', 'The Messenger of Allah (ﷺ) said, "He who says: ''Astaghfir ullah-alladhi la ilaha illa Huwal-Haiyul-Qayyumu, wa atubu ilaihi (I seek the forgiveness of Allah, there is no true god except Allah, the Ever-Living, the Self- Subsisting, and I turn to Him in repentance),'' his sins will be forgiven even if he should have run away from the battlefield (while he was engaged in fighting for the Cause of Allah).".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1874', 'Riyad as-Salihin 1874', 'ریاض الصالحین 1874', 'رواه أبو داود والترمذي والحاكم، وقال: حديث صحيح على شرط البخاري ومسلم', 'من قال: أَسْتَغْفِرُ الله الذي لا إله إلا هو الحَيَّ القيَّومَ وأتوب إليه غُفر له ذنبه وإن كان قد فَرَّ من قتال الكفار، ومن المعلوم أن الفِرَار من الزَّحْف هو أحد المُوبِقات السَّبع التي جاءت في حديث: (اجتنبوا السَّبع المُوبقات، ومنها: الفِرَار من الزَّحْف)، ويكون المعنى مستقيمًا: إذا كان المقصود أنه تاب من جميع الذُّنوب، ومنها: الفِرَار من الزَّحَف، وإلا فإن مجرد الاستغفار والإنسان باقٍ على الذَّنب لا ينفع وإنما ينفع ذلك مع التوبة من الذَّنْب.', 'فضل المُداومة على الاستغفار وخاصة بعد الوقوع في المعصية.
تعظيم الاستغفار وأنه يكفِّر الكبائر.
تغليظ حُرمَة الفِرار من المعركة عند التِقَاء الجيش.', 'فَرَّ من الزَّحْف : فَرَّ من لقاء العَدو في الحَرب، والزَّحْف: الجيش يزحَفُون إلى العدو، أي: يمشون.
القيوم : القَائم بتدبير أمر خَلقه في إنشائهم، ورزقهم وعلمه بِأمكنتهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10576', false),
(21875, 2, 220, 1875, 'hadith', 'عن شداد بن أوس رضي الله عنه عن النبي صلى الله عليه وسلم قال: «سيد الإستغفار أن يقول العبد : اللهم أنت ربي، لا إله إلا أنت ، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي، وأبوء بذنبي، فاغفر لي فإنه لا يغفر الذنوب إلا أنت، من قالها من النهار موقنا بها، فمات من يومه قبل أن يمسي، فهو من أهل الجنة، ومن قالها من الليل وهو موقن بها فمات قبل أن يصبح، فهو من أهل الجنة» ((رواه البخاري)). (1)', 'The Prophet (ﷺ) said, "The best supplication for seeking forgiveness (Syed-ul- Istighfar) is to say: ''Allahumma Anta Rabbi, la ilaha illa Anta, khalaqtani wa ana ''abduka, wa ana ''ala ''ahdika wa wa''dika mastata''tu, a''udhu bika min sharri ma sana''tu, abu''u laka bini''matika ''alayya, wa abu''u bidhanbi faghfir li, fa innahu la yaghfirudh-dhunuba illa Anta. (O Allah! You are my Rubb. There is no true god except You. You have created me, and I am Your slave, and I hold to Your Covenant as far as I can. I seek refuge in You from the evil of what I have done. I acknowledge the favours that You have bestowed upon me, and I confess my sins. Pardon me, for none but You has the power to pardon).'' He who supplicates in these terms during the day with firm belief in it and dies on the same day (before the evening), he will be one of the dwellers of Jannah; and if anyone supplicates in these terms during the night with firm belief in it and dies before the morning, he will be one of the dwellers of Jannah.".', 'شداد بن أوس رضي الله عنه', 'Shaddad bin Aus (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1875', 'Riyad as-Salihin 1875', 'ریاض الصالحین 1875', null, 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ للاستغفار ألفاظًا، وأنَّ أفضلَها وأعظمَها أنْ يقولَ العبد: 
"اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عَهْدِكَ وَوَعْدِكَ ما اسْتَطَعْتُ أعوذ بك من شر ما صنعتُ أَبُوءُ لك بنعمتك عليَّ وأَبُوءُ لك بذنبي فَاغْفرْ لي فإنه لا يغفر الذنوب إلا أنت" 
فيُقِرُّ العبدُ لله بالتوحيد أولًا، وأنَّ الله خالقُه ومعبوده لا شريك له، وأنه على ما عاهد الله سبحانه عليه من الإيمان به والطاعة له، بحسب استطاعته؛ لأن العبد مهما قام به من العبادة لا يَقْدِرُ أن يأتيَ بجميع ما أمره الله به ولا القيام بما يجب من شكر النعم، وأنه يلتجئ إلى الله، ويعتصم به، فإنه المستعاذ به من الشر الذي صنعه العبد، 
وأنه يقر ويعترف له طوعًا بنعمته عليه، ويرجع على نفسه بالإقرار والاعتراف بإثمه ومعصيته، 
وبعد هذا التوسل إلى الله، يدعو ربه أن يغفر له بأن يستر ذنوبه ويقيه آثامَها بعفوه وفضله ورحمته، فإنه لا يغفر الذنوب إلا هو عز وجل. 
ثم أخبر عليه الصلاة والسلام أنها من أذكار الصباح والليل، فمن قالها بيقين واستحضار لمعانيها وإيمان بها في أول يومه، ما بين طلوع الشمس إلى زوالها، وهو وقت النهار، فمات، دخل الجنة، 
ومن قالها ليلًا، وهو من غروب الشمس إلى طلوع الفجر، فمات قبل أن يصبح، دخل الجنة.', 'صيغ الاستغفار تختلف وبعضها أفضل من بعض.
أنه ينبغي للعبد أن يحرص على دعاء الله بهذا الدعاء؛ لأنه سيد الاستغفار.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5503', false),
(21876, 2, 220, 1876, 'hadith', '- وعن ثوبان رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا انصرف من صلاته ، استغفر الله ثلاثاً وقال: "اللهم أنت السلام، ومنك السلام، تباركت يا ياذا الجلال والإكرام" قيل للأوزاعي- وهو أحد رواته: كيف الإستغفار؟ قال: يقول: "أستغفر الله ، أستغفر الله".', 'Whenever the Messenger of Allah (ﷺ) finished his Salat (prayer), he would beg forgiveness three times .', null, 'Thauban (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1876', 'Riyad as-Salihin 1876', 'ریاض الصالحین 1876', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21877, 2, 220, 1877, 'hadith', 'عن عائشة رضي الله عنها قالت: كان رسول الله صلى الله عليه وسلم يكثر أن يقول قبل موته «سبحان الله وبحمده، أستغفر الله، وأتوب إليه».', 'Prior to his demise, the Messenger of Allah (ﷺ) used to supplicate frequently: Subhan Allahi wa bihamdihi; Astaghfirullaha wa atubu ilaihi (Allah is free from imperfection, and I begin with praising Him. I beg forgiveness from Allah and I turn to Him in repentance.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1877', 'Riyad as-Salihin 1877', 'ریاض الصالحین 1877', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21878, 2, 220, 1878, 'hadith', 'عن أنس رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «قال الله تعالى: يا ابن آدم إنك ما دعوتني ورجوتني غفرت لك ما كان منك ولا أبالي، يا ابن آدم لو بلغت ذنوبك عنان السماء، ثم استغفرتني ، غفرت لك ولا أبالي، يا ابن آدم إنك لو أتيتني بقراب الأرض خطايا، ثم لقيتني لا تشرك بي شيئاً، لأتيتك بقرابها مغفرة» . (2)', 'I heard the Messenger of Allah (ﷺ) saying, "Allah, the Exalted, has said: ''O son of Adam! I shall go on forgiving you so long as you pray to Me and aspire for My forgiveness whatever may be your sins. O son of Adam! I do not care even if your sins should pile up to the sky and should you beg pardon of Me, I would forgive you. O son of Adam! If you come to Me with an earthful of sins and meet Me, not associating anything with Me in worship, I will certainly grant you as much pardon as will fill the earth."''.', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'حسن', 'رياض الصالحين 1878', 'Riyad as-Salihin 1878', 'ریاض الصالحین 1878', null, 'أَخْبَرَ النبيُّ صلَّى اللهُ علَيه وسلَّم أنَّ الله تباركَ وتعالى قال في الحديثِ القدسيِّ: يا ابنَ آدمَ ما دمْتَ تدْعونِي وتَرْجو رَحْمتي، ولمْ تَقْنَطْ؛ سَتَرتُ ذنبَكَ ومحوتُه غير مبالٍ فيه؛ ولو كانَ هذا الذنب والمعصية من الكبائر. 
يا ابن آدم: لو كَثُرَت ذُنوبُك كثرةً تَملَأُ ما بينَ السَّماءِ والأرضِ بحيث تَبلُغُ أقطارَها وتَعُمَّ نَواحِيَها، ثمَّ استَغفَرتَني؛ محوت وغَفَرتُ لك جميعَها غيرَ مُبالٍ بكَثرتِها.

يا ابنَ آدمَ: إنَّك لو أتيتَني بعدَ الموتِ بمِلْءِ الأرضِ ذُنوبًا ومَعاصِيَ، وكنتَ قد مِتَّ مُوحِّدًا لا تُشرِكُ بي شيئًا؛ لقابَلتُ هذه الذُّنوبَ والْمعاصِيَ، بمِلْئِ الأرض، مَغفِرةً؛ لأنَّني واسِعُ المغفرةِ، وأغفِرُ كل الذنوب إلا الشِّركَ.', 'سعة رحمة الله تعالى ومغفرته وفضله.
فضل التوحيد، وأنَّ الله يغفر للموحدين الذنوب والمعاصي.
خطر الشرك وأن الله لا يغفر للمشركين.
قال ابن رجب: وقد تضمَّن هذا الحديث الأسباب الثلاثة التي تحصل بها مغفرة الذنوب: الأول: الدعاء مع الرجاء، الثاني: الاستغفار وطلب التوبة، الثالث: الموت على التوحيد.
هذا الحديث مما يرويه النبي صلى الله عليه وسلم عن ربه، ويسمى بالحديث القدسي أو الإلهي، وهو الذي لفظه ومعناه من الله، غير أنه ليست فيه خصائص القرآن التي امتاز بها عما سواه، من التعبد بتلاوته والطهارة له والتحدي والإعجاز وغير ذلك.
الذنوب ثلاثة أنواع: الأول: الشرك بالله؛ وهذا لا يغفره الله، قال الله عز وجل: {إنه من يشرك بالله فقد حرم الله عليه الجنة}، الثاني: ظلم العبد نفسه فيما بينه وبين ربه من ذنوب ومعاصي؛ فإن الله عز وجل يغفر ذلك، ويتجاوز إن شاء، الثالث: ذنوب لا يترك الله منها شيئًا؛ وهي ظلم العباد بعضهم بعضًا، فلا بد من القصاص.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5456', false),
(21879, 2, 220, 1879, 'hadith', 'عن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال: "يا معشر النساء تصدقن، وأكثرن من الاستغفار، فإني رأيتكن أكثر أهل النار" قالت امرأة منهن: مالنا أكثر أهل النار؟ قال: "تكثرن اللعن، وتكفرن العشير مارأيت من ناقصات عقل ودين أغلب لذي لب منكن" قالت: ما نقصان العقل والدين؟ قال" "شهادة امرأتين بشهادة رجل، وتمكث الأيام لا تصلي".', 'The Prophet (ﷺ) said, "O women folk! You should give charity and be diligent in seeking Allah''s forgiveness because I have seen (i.e., on the Night of the Ascension to the highest heavens) that dwellers of the Hell are women." A woman amongst them said: "Why is it that the majority of the dwellers of Hell are women?" The Prophet (ﷺ) replied, "You curse frequently and are ungrateful to your husbands. In spite of your lacking in wisdom and failing in religion, you are depriving the wisest of men of their intelligence." Upon this the woman asked: "What is the deficiency in our wisdom and in our religion?" He (ﷺ) replied, "Your lack of wisdom can be well judged from the fact that the evidence of two women is equal to that one man. You do not offer Salat (prayer) for some days and you do not fast (the whole of) Ramadan sometimes, it is a deficiency in religion.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1879', 'Riyad as-Salihin 1879', 'ریاض الصالحین 1879', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21880, 2, 220, 1880, 'hadith', 'عن جابر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «يأكل أهل الجنة فيها ، ويشربون ، ولا يتغوطون، ولا يتمخطون، ولا يبولون، ولكن طعامهم ذلك جشاء كرشح المسك، يلهمون التسبيح والتكبير، كما يلهمون النفس».', 'The Messenger of Allah (ﷺ) said, "The inhabitants of Jannah will eat and drink therein, but they will not have to pass excrement, to blow their noses or to urinate. Their food will be digested producing belch which will give out a smell like that of musk. They will be inspired to declare the freedom of Allah from imperfection and proclaim His Greatness as easily as you breathe.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1880', 'Riyad as-Salihin 1880', 'ریاض الصالحین 1880', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false)
